import{a as e}from"./chunk-YR3K2D3X.js";import"./chunk-MNCRUE4M.js";var a=[{id:"jl-1",level:"fresher",topic:"java-collections",difficulty:"easy",simple:{hi:"Collections framework ek school jaisa hai. List roll-number wali line hai jahan same naam do baar aa sakta hai, Set ek club hai jahan har bachcha sirf ek baar member ban sakta hai, Queue canteen ki line hai, aur Map attendance register hai jahan roll number (key) ke saamne naam (value) likha hota hai.",en:"The Collections framework is like a school. A List is a line by roll number where the same name can appear twice, a Set is a club where each child can join only once, a Queue is the canteen line, and a Map is the attendance register where each roll number (key) has a name (value).",bn:"Collections framework \u098F\u0995\u099F\u09BE \u09B8\u09CD\u0995\u09C1\u09B2\u09C7\u09B0 \u09AE\u09A4\u09CB\u0964 List \u09B9\u09B2\u09CB roll number \u0985\u09A8\u09C1\u09AF\u09BE\u09AF\u09BC\u09C0 \u09B2\u09BE\u0987\u09A8 \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 \u098F\u0995\u0987 \u09A8\u09BE\u09AE \u09A6\u09C1\u09AC\u09BE\u09B0 \u09A5\u09BE\u0995\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7, Set \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE \u0995\u09CD\u09B2\u09BE\u09AC \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 \u09AA\u09CD\u09B0\u09A4\u09CD\u09AF\u09C7\u0995\u09C7 \u098F\u0995\u09AC\u09BE\u09B0\u0987 \u09B8\u09A6\u09B8\u09CD\u09AF \u09B9\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7, Queue \u09B9\u09B2\u09CB \u0995\u09CD\u09AF\u09BE\u09A8\u09CD\u099F\u09BF\u09A8\u09C7\u09B0 \u09B2\u09BE\u0987\u09A8, \u0986\u09B0 Map \u09B9\u09B2\u09CB \u09B9\u09BE\u099C\u09BF\u09B0\u09BE \u0996\u09BE\u09A4\u09BE \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 roll number (key)-\u098F\u09B0 \u09AA\u09BE\u09B6\u09C7 \u09A8\u09BE\u09AE (value) \u09B2\u09C7\u0996\u09BE \u09A5\u09BE\u0995\u09C7\u0964"},question:"Explain the Java Collections Framework hierarchy.",answer:"The Collections Framework is a set of interfaces and implementations for storing groups of objects. Iterable is the root; Collection extends it and is split into List (ordered, duplicates allowed), Set (no duplicates) and Queue/Deque (processing order). Map (key-value pairs) is a separate hierarchy that does not extend Collection. Java 21 added SequencedCollection, SequencedSet and SequencedMap, which give a uniform getFirst(), getLast() and reversed() to ordered collections.",points:["Iterable -> Collection -> List / Set / Queue (Deque extends Queue)","List: ArrayList, LinkedList; Set: HashSet, LinkedHashSet, TreeSet; Queue/Deque: ArrayDeque, PriorityQueue","Map is separate: HashMap, LinkedHashMap, TreeMap, ConcurrentHashMap","Collections (with s) is a utility class; Collection is the interface","Java 21 sequenced interfaces: getFirst(), getLast(), reversed()","List.of / Set.of / Map.of create unmodifiable collections"],code:`List<String> list = new ArrayList<>(List.of("a", "b", "a")); // ordered, duplicates ok
Set<String> set = new HashSet<>(list);                      // [a, b] - no duplicates
Deque<Integer> stack = new ArrayDeque<>();                  // Queue/Deque branch
stack.push(1);
Map<String, Integer> marks = new HashMap<>();               // separate Map hierarchy
marks.put("Ravi", 90);

// Java 21 sequenced collections
System.out.println(list.getFirst());   // a
System.out.println(list.reversed());   // [a, b, a]`},{id:"jl-2",level:"fresher",topic:"java-collections",difficulty:"easy",simple:{hi:"ArrayList train ke coach number jaisa hai: seedha coach 7 pe pahunch jao. LinkedList ek manav-shrinkhla jaisa hai jahan har bachcha sirf apne aage-peeche wale ka haath pakadta hai; 7th bachche tak pahunchne ke liye ek-ek karke ginna padta hai, par beech mein naya bachcha jodna aasaan hai.",en:"An ArrayList is like numbered train coaches: you can walk straight to coach 7. A LinkedList is like a human chain where each child only holds the hands of the ones next to them; to reach the 7th child you must count one by one, but adding a new child into the chain is easy.",bn:"ArrayList \u09B9\u09B2\u09CB \u099F\u09CD\u09B0\u09C7\u09A8\u09C7\u09B0 \u09A8\u09AE\u09CD\u09AC\u09B0 \u09A6\u09C7\u0993\u09AF\u09BC\u09BE \u0995\u09BE\u09AE\u09B0\u09BE\u09B0 \u09AE\u09A4\u09CB: \u09B8\u09CB\u099C\u09BE \u09ED \u09A8\u09AE\u09CD\u09AC\u09B0 \u0995\u09BE\u09AE\u09B0\u09BE\u09AF\u09BC \u099A\u09B2\u09C7 \u09AF\u09BE\u0993\u09AF\u09BC\u09BE \u09AF\u09BE\u09AF\u09BC\u0964 LinkedList \u09B9\u09B2\u09CB \u09AE\u09BE\u09A8\u09AC\u09AC\u09A8\u09CD\u09A7\u09A8\u09C7\u09B0 \u09AE\u09A4\u09CB \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BE \u09AC\u09BE\u099A\u09CD\u099A\u09BE \u09B6\u09C1\u09A7\u09C1 \u09AA\u09BE\u09B6\u09C7\u09B0 \u099C\u09A8\u09C7\u09B0 \u09B9\u09BE\u09A4 \u09A7\u09B0\u09C7 \u09A5\u09BE\u0995\u09C7; \u09ED \u09A8\u09AE\u09CD\u09AC\u09B0 \u09AC\u09BE\u099A\u09CD\u099A\u09BE\u09B0 \u0995\u09BE\u099B\u09C7 \u09AF\u09C7\u09A4\u09C7 \u098F\u0995 \u098F\u0995 \u0995\u09B0\u09C7 \u0997\u09C1\u09A8\u09A4\u09C7 \u09B9\u09AF\u09BC, \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09AE\u09BE\u099D\u0996\u09BE\u09A8\u09C7 \u09A8\u09A4\u09C1\u09A8 \u09AC\u09BE\u099A\u09CD\u099A\u09BE \u099C\u09C1\u09A1\u09BC\u09C7 \u09A6\u09C7\u0993\u09AF\u09BC\u09BE \u09B8\u09B9\u099C\u0964"},question:"What is the difference between ArrayList and LinkedList? When would you use each?",answer:"ArrayList is backed by a resizable array, so get(index) is O(1) and iteration is cache-friendly, but inserting or removing in the middle shifts elements (O(n)). LinkedList is a doubly linked list: adding or removing at the ends is O(1), but get(index) is O(n) because it must walk the nodes, and each node has extra memory overhead. In practice ArrayList is the default choice; for queue/stack behaviour ArrayDeque is usually better than LinkedList.",points:["ArrayList: dynamic array, O(1) random access, amortised O(1) add at end","ArrayList grows by about 50% when full (copy to a bigger array)","LinkedList: doubly linked nodes, O(n) get(index), O(1) add/remove at head/tail","Middle insert in LinkedList is O(1) only once you already have the position; finding it is O(n)","LinkedList uses more memory (prev/next pointers per node) and is less cache-friendly","Prefer ArrayList by default; ArrayDeque for stack/queue"],code:`List<Integer> arrayList = new ArrayList<>();
List<Integer> linkedList = new LinkedList<>();
for (int i = 0; i < 5; i++) { arrayList.add(i); linkedList.add(i); }

int a = arrayList.get(3);   // O(1) - direct index into array
int b = linkedList.get(3);  // O(n) - walks nodes from the nearer end

arrayList.add(0, 99);       // O(n) - shifts all elements right
((LinkedList<Integer>) linkedList).addFirst(99); // O(1) - just relinks the head`},{id:"jl-3",level:"fresher",topic:"java-collections",difficulty:"easy",simple:{hi:"Comparable class ke andar likha hua ek fixed rule hai, jaise school mein bachche hamesha roll number se khade hote hain. Comparator ek bahar ka teacher hai jo kabhi height se, kabhi marks se line banwata hai, bina bachchon ko badle.",en:"Comparable is a fixed rule written inside the class, like children in school always standing by roll number. Comparator is an outside teacher who can line them up by height one day and by marks the next, without changing the children.",bn:"Comparable \u09B9\u09B2\u09CB class-\u098F\u09B0 \u09AD\u09C7\u09A4\u09B0\u09C7 \u09B2\u09C7\u0996\u09BE \u098F\u0995\u099F\u09BE \u09A8\u09BF\u09B0\u09CD\u09A6\u09BF\u09B7\u09CD\u099F \u09A8\u09BF\u09AF\u09BC\u09AE, \u09AF\u09C7\u09AE\u09A8 \u09B8\u09CD\u0995\u09C1\u09B2\u09C7 \u09AC\u09BE\u099A\u09CD\u099A\u09BE\u09B0\u09BE \u09B8\u09AC\u09B8\u09AE\u09AF\u09BC roll number \u0985\u09A8\u09C1\u09AF\u09BE\u09AF\u09BC\u09C0 \u09A6\u09BE\u0981\u09A1\u09BC\u09BE\u09AF\u09BC\u0964 Comparator \u09B9\u09B2\u09CB \u09AC\u09BE\u0987\u09B0\u09C7\u09B0 \u098F\u0995\u099C\u09A8 \u09B6\u09BF\u0995\u09CD\u09B7\u0995, \u09AF\u09BF\u09A8\u09BF \u0995\u0996\u09A8\u09CB \u0989\u099A\u09CD\u099A\u09A4\u09BE, \u0995\u0996\u09A8\u09CB \u09A8\u09AE\u09CD\u09AC\u09B0 \u0985\u09A8\u09C1\u09AF\u09BE\u09AF\u09BC\u09C0 \u09B2\u09BE\u0987\u09A8 \u0995\u09B0\u09BE\u09A8, \u09AC\u09BE\u099A\u09CD\u099A\u09BE\u09A6\u09C7\u09B0 \u09A8\u09BE \u09AC\u09A6\u09B2\u09C7\u0987\u0964"},question:"What is the difference between Comparable and Comparator?",answer:"Comparable defines a class's natural ordering through compareTo(T other), implemented inside the class itself, so a class can have only one natural order. Comparator is a separate object with compare(T a, T b), so you can define many different orderings without changing the class. Since Java 8 you build comparators fluently with Comparator.comparing(), thenComparing() and reversed().",points:["Comparable: java.lang, compareTo(), one natural order, implemented by the class (String, Integer)","Comparator: java.util, compare(), many external orderings, can be a lambda","Return negative / zero / positive for less / equal / greater","Collections.sort(list) and TreeSet use Comparable unless a Comparator is passed","Comparator.comparing(...).thenComparing(...).reversed() for chained sorting","Avoid a - b in compare for ints (overflow); use Integer.compare"],code:`record Student(String name, int marks) implements Comparable<Student> {
    @Override
    public int compareTo(Student other) {          // natural order: by name
        return name.compareTo(other.name);
    }
}

List<Student> list = new ArrayList<>(List.of(
        new Student("Ravi", 80), new Student("Anu", 95), new Student("Dev", 80)));

Collections.sort(list);                            // Anu, Dev, Ravi
list.sort(Comparator.comparingInt(Student::marks)
        .reversed()
        .thenComparing(Student::name));            // Anu(95), Dev(80), Ravi(80)`},{id:"jl-4",level:"fresher",topic:"java-collections",difficulty:"easy",simple:{hi:"Functional interface ek job ka post hai jisme sirf ek kaam hai, jaise 'chai banao'. Lambda wo chhota sa note hai jisme likha hai chai kaise banani hai, aur method reference bas kehta hai 'Ramu bhaiya wala tareeka use karo'.",en:"A functional interface is a job post with only one task, like 'make tea'. A lambda is a short note saying how to make the tea, and a method reference simply says 'do it the way Ramu bhaiya already does it'.",bn:"Functional interface \u09B9\u09B2\u09CB \u098F\u09AE\u09A8 \u098F\u0995\u099F\u09BE \u099A\u09BE\u0995\u09B0\u09BF\u09B0 \u09AA\u09A6 \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 \u0995\u09BE\u099C \u09AE\u09BE\u09A4\u09CD\u09B0 \u098F\u0995\u099F\u09BE, \u09AF\u09C7\u09AE\u09A8 '\u099A\u09BE \u09AC\u09BE\u09A8\u09BE\u0993'\u0964 Lambda \u09B9\u09B2\u09CB \u099B\u09CB\u099F\u09CD\u099F \u098F\u0995\u099F\u09BE \u099A\u09BF\u09B0\u0995\u09C1\u099F \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 \u09B2\u09C7\u0996\u09BE \u0995\u09C0\u09AD\u09BE\u09AC\u09C7 \u099A\u09BE \u09AC\u09BE\u09A8\u09BE\u09A4\u09C7 \u09B9\u09AC\u09C7, \u0986\u09B0 method reference \u09B6\u09C1\u09A7\u09C1 \u09AC\u09B2\u09C7 '\u09B0\u09BE\u09AE\u09C1 \u09A6\u09BE\u09A6\u09BE \u09AF\u09C7\u09AD\u09BE\u09AC\u09C7 \u09AC\u09BE\u09A8\u09BE\u09AF\u09BC \u09B8\u09C7\u09AD\u09BE\u09AC\u09C7 \u09AC\u09BE\u09A8\u09BE\u0993'\u0964"},question:"What are functional interfaces, lambdas and method references in Java?",answer:"A functional interface has exactly one abstract method (it may also have default and static methods), and it can be marked with @FunctionalInterface. A lambda expression is a short way to provide that one method's implementation, e.g. x -> x * 2. A method reference such as String::toUpperCase is an even shorter lambda that simply calls an existing method.",points:["Single abstract method (SAM); @FunctionalInterface makes the compiler check it","Built-ins in java.util.function: Function, Predicate, Consumer, Supplier, BiFunction, UnaryOperator","Older examples: Runnable, Callable, Comparator","Lambdas can use only effectively final local variables","4 kinds of method reference: static (Integer::parseInt), bound (System.out::println), unbound (String::length), constructor (ArrayList::new)"],code:`@FunctionalInterface
interface Discount {
    double apply(double price);
}

Discount festive = price -> price * 0.9;            // lambda
Function<String, Integer> length = String::length;  // unbound method reference
Supplier<List<String>> maker = ArrayList::new;      // constructor reference
Predicate<Integer> isEven = n -> n % 2 == 0;

System.out.println(festive.apply(500));   // 450.0
System.out.println(length.apply("Java")); // 4
System.out.println(isEven.test(7));       // false`},{id:"jl-5",level:"junior",topic:"java-collections",difficulty:"medium",simple:{hi:"HashMap ek post office ke letter boxes jaisa hai. Pincode (hashCode) dekh ke letter sahi box mein daala jaata hai; agar ek box mein kai letter aa gaye (collision), to postman naam padh ke (equals) sahi letter nikalta hai. Boxes bhar jaayein to post office double boxes laga deta hai.",en:"A HashMap is like the letter boxes in a post office. The pincode (hashCode) decides which box a letter goes into; if many letters land in one box (collision), the postman reads the names (equals) to find the right one. When boxes get too full, the post office doubles the number of boxes.",bn:"HashMap \u09B9\u09B2\u09CB \u09AA\u09CB\u09B8\u09CD\u099F \u0985\u09AB\u09BF\u09B8\u09C7\u09B0 \u099A\u09BF\u09A0\u09BF\u09B0 \u0996\u09CB\u09AA\u09C7\u09B0 \u09AE\u09A4\u09CB\u0964 Pincode (hashCode) \u09A6\u09C7\u0996\u09C7 \u099A\u09BF\u09A0\u09BF \u09A0\u09BF\u0995 \u0996\u09CB\u09AA\u09C7 \u09B0\u09BE\u0996\u09BE \u09B9\u09AF\u09BC; \u098F\u0995\u0987 \u0996\u09CB\u09AA\u09C7 \u0985\u09A8\u09C7\u0995 \u099A\u09BF\u09A0\u09BF \u098F\u09B2\u09C7 (collision) \u09AA\u09BF\u09AF\u09BC\u09A8 \u09A8\u09BE\u09AE \u09AA\u09A1\u09BC\u09C7 (equals) \u09B8\u09A0\u09BF\u0995 \u099A\u09BF\u09A0\u09BF\u099F\u09BE \u09AC\u09C7\u09B0 \u0995\u09B0\u09C7\u09A8\u0964 \u0996\u09CB\u09AA \u09AC\u09C7\u09B6\u09BF \u09AD\u09B0\u09C7 \u0997\u09C7\u09B2\u09C7 \u09AA\u09CB\u09B8\u09CD\u099F \u0985\u09AB\u09BF\u09B8 \u0996\u09CB\u09AA\u09C7\u09B0 \u09B8\u0982\u0996\u09CD\u09AF\u09BE \u09A6\u09CD\u09AC\u09BF\u0997\u09C1\u09A3 \u0995\u09B0\u09C7 \u09A6\u09C7\u09AF\u09BC\u0964"},question:"How does HashMap work internally?",answer:"HashMap stores entries in an array of buckets. On put(key, value) it calls key.hashCode(), spreads the bits (h ^ (h >>> 16)) and computes the bucket index as (n - 1) & hash, where n is the table size (always a power of two). If the bucket already holds entries (a collision), it walks them using equals() to either replace the value of a matching key or append a new node; get() follows the same path. When size exceeds capacity x load factor (16 x 0.75 = 12 by default) the table doubles and entries are redistributed, and since Java 8 a very long bucket is converted into a red-black tree.",points:["Array of Node<K,V> buckets; each node holds hash, key, value, next","index = (n - 1) & (h ^ (h >>> 16)); table size is a power of two","Collision: same bucket -> linked list, equals() finds the right key","Default capacity 16, load factor 0.75, resize doubles the table","Bucket with 8+ nodes becomes a red-black tree (if table >= 64)","One null key allowed (stored in bucket 0); not thread-safe; keys must have consistent equals/hashCode"],code:`Map<String, Integer> map = new HashMap<>();   // table of 16 buckets created lazily
map.put("Ravi", 90);
// 1. h = "Ravi".hashCode()
// 2. hash = h ^ (h >>> 16)        -> mixes high bits into low bits
// 3. index = (16 - 1) & hash      -> bucket number 0..15
// 4. bucket empty? store node : walk nodes, compare hash + equals()
map.put("Ravi", 95);                  // same key -> value replaced, size stays 1
System.out.println(map.get("Ravi"));  // 95
map.put(null, 0);                     // allowed, goes to bucket 0`},{id:"jl-6",level:"junior",topic:"java-collections",difficulty:"medium",simple:{hi:"HashMap ghar ki almari hai: sirf ghar wale use karte hain, koi lock nahi. Hashtable bank ka ek hi counter hai jahan ek time pe sirf ek customer. ConcurrentHashMap bank ke kai counters hain, alag-alag log ek saath apna kaam kar lete hain.",en:"A HashMap is a cupboard at home: only family uses it, so no lock. A Hashtable is a bank with a single counter where only one customer is served at a time. A ConcurrentHashMap is a bank with many counters, so different people get their work done at the same time.",bn:"HashMap \u09B9\u09B2\u09CB \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u0986\u09B2\u09AE\u09BE\u09B0\u09BF: \u09B6\u09C1\u09A7\u09C1 \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u09B2\u09CB\u0995 \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09C7, \u09A4\u09BE\u09B2\u09BE\u09B0 \u09A6\u09B0\u0995\u09BE\u09B0 \u09A8\u09C7\u0987\u0964 Hashtable \u09B9\u09B2\u09CB \u09AC\u09CD\u09AF\u09BE\u0982\u0995\u09C7\u09B0 \u098F\u0995\u099F\u09BE\u0987 \u0995\u09BE\u0989\u09A8\u09CD\u099F\u09BE\u09B0, \u098F\u0995\u09B8\u09BE\u09A5\u09C7 \u098F\u0995\u099C\u09A8\u0987 \u0995\u09BE\u099C \u0995\u09B0\u09BE\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u0964 ConcurrentHashMap \u09B9\u09B2\u09CB \u0985\u09A8\u09C7\u0995 \u0995\u09BE\u0989\u09A8\u09CD\u099F\u09BE\u09B0\u0993\u09AF\u09BC\u09BE\u09B2\u09BE \u09AC\u09CD\u09AF\u09BE\u0982\u0995, \u0986\u09B2\u09BE\u09A6\u09BE \u0986\u09B2\u09BE\u09A6\u09BE \u09B2\u09CB\u0995 \u098F\u0995\u09B8\u09BE\u09A5\u09C7 \u0995\u09BE\u099C \u09B8\u09C7\u09B0\u09C7 \u09AB\u09C7\u09B2\u09C7\u0964"},question:"What is the difference between HashMap, Hashtable and ConcurrentHashMap?",answer:"HashMap is not thread-safe, allows one null key and many null values, and is the fastest choice for single-threaded code. Hashtable is a legacy class where every method is synchronized on the whole table, so only one thread can use it at a time, and it allows no null keys or values. ConcurrentHashMap is the modern thread-safe map: reads are mostly lock-free and writes use CAS or lock only a single bucket, so many threads work in parallel; it also forbids nulls and offers atomic operations like compute() and merge().",points:["HashMap: not synchronized, null key/values allowed, fail-fast iterators","Hashtable: legacy, whole-map lock, no nulls, poor scalability","ConcurrentHashMap: CAS + per-bin locking (Java 8+), no nulls, weakly consistent iterators","Nulls are banned in concurrent maps because get() returning null would be ambiguous","Use putIfAbsent / computeIfAbsent / merge for atomic check-then-act","Collections.synchronizedMap also locks the whole map"],code:`Map<String, Integer> hits = new ConcurrentHashMap<>();

Runnable task = () -> {
    for (int i = 0; i < 1000; i++) {
        hits.merge("home", 1, Integer::sum);   // atomic read-modify-write
    }
};
Thread t1 = new Thread(task), t2 = new Thread(task);
t1.start(); t2.start();
t1.join(); t2.join();
System.out.println(hits.get("home"));          // always 2000

// hits.put(null, 1);  -> NullPointerException
// new HashMap<>().put(null, 1);  -> fine`},{id:"jl-7",level:"junior",topic:"java-collections",difficulty:"medium",simple:{hi:"HashSet ek school ka register hai jo andar se HashMap hi hai. hashCode batata hai kaunse section mein dhundho, equals batata hai ki ye wahi bachcha hai ya nahi. Agar section galat bataya to wahi bachcha do baar admission le lega.",en:"A HashSet is a school register that is really a HashMap inside. hashCode tells you which section to look in, and equals tells you whether it is the same child. If the section is wrong, the same child can get admission twice.",bn:"HashSet \u09B9\u09B2\u09CB \u09B8\u09CD\u0995\u09C1\u09B2\u09C7\u09B0 \u098F\u0995\u099F\u09BE \u09B0\u09C7\u099C\u09BF\u09B8\u09CD\u099F\u09BE\u09B0, \u09AF\u09C7\u099F\u09BE \u09AD\u09C7\u09A4\u09B0\u09C7 \u0986\u09B8\u09B2\u09C7 HashMap\u0964 hashCode \u09AC\u09B2\u09C7 \u0995\u09CB\u09A8 \u09B8\u09C7\u0995\u09B6\u09A8\u09C7 \u0996\u09C1\u0981\u099C\u09A4\u09C7 \u09B9\u09AC\u09C7, equals \u09AC\u09B2\u09C7 \u098F\u099F\u09BE \u09B8\u09C7\u0987 \u098F\u0995\u0987 \u09AC\u09BE\u099A\u09CD\u099A\u09BE \u0995\u09BF\u09A8\u09BE\u0964 \u09B8\u09C7\u0995\u09B6\u09A8 \u09AD\u09C1\u09B2 \u09B9\u09B2\u09C7 \u098F\u0995\u0987 \u09AC\u09BE\u099A\u09CD\u099A\u09BE \u09A6\u09C1\u09AC\u09BE\u09B0 \u09AD\u09B0\u09CD\u09A4\u09BF \u09B9\u09AF\u09BC\u09C7 \u09AF\u09BE\u09AC\u09C7\u0964"},question:"How does HashSet work internally, and why must equals() and hashCode() be overridden together?",answer:"HashSet is backed by a HashMap: each element is stored as a key, with a shared dummy object (PRESENT) as the value, so add() returns false when the key already exists. Uniqueness therefore depends on hashCode() to find the bucket and equals() to compare inside it. If you override equals() but not hashCode(), two equal objects can land in different buckets and the set will hold 'duplicates'; the contract is that equal objects must have equal hash codes.",points:["HashSet -> internal HashMap<E, Object>, value is a constant PRESENT","add(e) == map.put(e, PRESENT) == null","Contract: a.equals(b) implies a.hashCode() == b.hashCode() (not the reverse)","Records generate equals/hashCode automatically from components","Do not mutate fields used in hashCode while the object is in a set or map key","LinkedHashSet keeps insertion order; TreeSet uses compareTo/compare instead"],code:`class Emp {
    String id;
    Emp(String id) { this.id = id; }
    @Override public boolean equals(Object o) {
        return o instanceof Emp e && e.id.equals(id);
    }
    // hashCode NOT overridden -> bug
}

Set<Emp> set = new HashSet<>();
set.add(new Emp("E1"));
set.add(new Emp("E1"));
System.out.println(set.size());   // usually 2 - different identity hash codes

record EmpR(String id) {}         // record: equals + hashCode generated
Set<EmpR> ok = new HashSet<>(List.of(new EmpR("E1")));
System.out.println(ok.add(new EmpR("E1")));   // false - duplicate rejected`},{id:"jl-8",level:"junior",topic:"java-collections",difficulty:"medium",simple:{hi:"HashMap ek jhola hai jisme cheezein kisi bhi order mein milti hain. LinkedHashMap station ki queue hai jo aane ke order mein chalti hai, aur TreeMap library ki shelf hai jahan books A se Z sorted rehti hain. LRU cache ek chhota fridge hai: jagah khatam hui to sabse purani, kabhi na chhui gayi cheez bahar.",en:"A HashMap is a cloth bag where things come out in any order. A LinkedHashMap is a station queue that keeps the order people arrived, and a TreeMap is a library shelf with books sorted A to Z. An LRU cache is a small fridge: when it is full, the item nobody has touched for the longest time goes out.",bn:"HashMap \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE \u099D\u09CB\u09B2\u09BE, \u09AF\u09C7\u0996\u09BE\u09A8 \u09A5\u09C7\u0995\u09C7 \u099C\u09BF\u09A8\u09BF\u09B8 \u09AF\u09C7\u0995\u09CB\u09A8\u09CB \u0995\u09CD\u09B0\u09AE\u09C7 \u09AC\u09C7\u09B0 \u09B9\u09AF\u09BC\u0964 LinkedHashMap \u09B9\u09B2\u09CB \u09B8\u09CD\u099F\u09C7\u09B6\u09A8\u09C7\u09B0 \u09B2\u09BE\u0987\u09A8, \u09AF\u09C7 \u0986\u0997\u09C7 \u098F\u09B8\u09C7\u099B\u09C7 \u09B8\u09C7 \u0986\u0997\u09C7, \u0986\u09B0 TreeMap \u09B9\u09B2\u09CB \u09B2\u09BE\u0987\u09AC\u09CD\u09B0\u09C7\u09B0\u09BF\u09B0 \u09A4\u09BE\u0995 \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 \u09AC\u0987 A \u09A5\u09C7\u0995\u09C7 Z \u09B8\u09BE\u099C\u09BE\u09A8\u09CB\u0964 LRU cache \u09B9\u09B2\u09CB \u099B\u09CB\u099F\u09CD\u099F \u098F\u0995\u099F\u09BE \u09AB\u09CD\u09B0\u09BF\u099C: \u099C\u09BE\u09AF\u09BC\u0997\u09BE \u09A8\u09BE \u09A5\u09BE\u0995\u09B2\u09C7 \u09B8\u09AC\u099A\u09C7\u09AF\u09BC\u09C7 \u09AC\u09C7\u09B6\u09BF\u09A6\u09BF\u09A8 \u09A8\u09BE \u099B\u09CB\u0981\u09AF\u09BC\u09BE \u099C\u09BF\u09A8\u09BF\u09B8\u099F\u09BE \u09AC\u09BE\u0987\u09B0\u09C7 \u09AF\u09BE\u09AF\u09BC\u0964"},question:"Compare HashMap, LinkedHashMap and TreeMap. How would you build an LRU cache?",answer:"HashMap gives no ordering guarantee and O(1) average operations. LinkedHashMap adds a doubly linked list across the entries, so it iterates in insertion order, or in access order if created with accessOrder = true. TreeMap is a red-black tree that keeps keys sorted (natural order or a Comparator) with O(log n) operations and navigation methods like floorKey() and headMap(). An LRU cache is simply a LinkedHashMap in access order that overrides removeEldestEntry() to evict the least recently used entry when it grows past capacity.",points:["HashMap: unordered, O(1) average","LinkedHashMap: insertion order or access order, slightly more memory","TreeMap: sorted keys, O(log n), NavigableMap (floorKey, ceilingKey, subMap)","TreeMap with natural ordering does not allow a null key","LRU: new LinkedHashMap<>(cap, 0.75f, true) + removeEldestEntry","Not thread-safe; wrap or use a caching library for concurrent use"],code:`class LruCache<K, V> extends LinkedHashMap<K, V> {
    private final int capacity;

    LruCache(int capacity) {
        super(16, 0.75f, true);              // true = access order
        this.capacity = capacity;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > capacity;            // evict least recently used
    }
}

LruCache<String, Integer> cache = new LruCache<>(2);
cache.put("a", 1); cache.put("b", 2);
cache.get("a");                              // "a" becomes most recent
cache.put("c", 3);                           // evicts "b"
System.out.println(cache.keySet());          // [a, c]`},{id:"jl-9",level:"junior",topic:"java-collections",difficulty:"medium",simple:{hi:"Fail-fast iterator ek strict ticket checker hai: train chalte waqt kisi ne seat badli to turant seeti baja deta hai (exception). Fail-safe iterator photo kheench ke ginti karta hai, isliye beech mein koi aaye-jaaye to bhi shor nahi machata.",en:"A fail-fast iterator is a strict ticket checker: if anyone changes seats while he is counting, he blows the whistle at once (exception). A fail-safe iterator counts from a photo it took earlier, so people moving around in between does not bother it.",bn:"Fail-fast iterator \u09B9\u09B2\u09CB \u0995\u09A1\u09BC\u09BE \u099F\u09BF\u0995\u09BF\u099F \u099A\u09C7\u0995\u09BE\u09B0: \u0997\u09CB\u09A8\u09BE\u09B0 \u09B8\u09AE\u09AF\u09BC \u0995\u09C7\u0989 \u09B8\u09BF\u099F \u09AC\u09A6\u09B2\u09BE\u09B2\u09C7 \u09B8\u0999\u09CD\u0997\u09C7 \u09B8\u0999\u09CD\u0997\u09C7 \u09AC\u09BE\u0981\u09B6\u09BF \u09AC\u09BE\u099C\u09BE\u09AF\u09BC (exception)\u0964 Fail-safe iterator \u0986\u0997\u09C7 \u09A4\u09CB\u09B2\u09BE \u098F\u0995\u099F\u09BE \u099B\u09AC\u09BF \u09A6\u09C7\u0996\u09C7 \u0997\u09CB\u09A8\u09C7, \u09A4\u09BE\u0987 \u09AE\u09BE\u099D\u09C7 \u0995\u09C7\u0989 \u098F\u09B2\u09CB-\u0997\u09C7\u09B2\u09CB \u09A4\u09BE\u09A4\u09C7 \u09A4\u09BE\u09B0 \u0995\u09BF\u099B\u09C1 \u09AF\u09BE\u09AF\u09BC \u0986\u09B8\u09C7 \u09A8\u09BE\u0964"},question:"What is the difference between fail-fast and fail-safe iterators?",answer:"A fail-fast iterator (ArrayList, HashMap) throws ConcurrentModificationException if the collection is structurally modified after the iterator was created, except through the iterator's own remove(). It detects this by comparing a modCount counter, on a best-effort basis. Fail-safe (more precisely snapshot or weakly consistent) iterators of concurrent collections never throw: CopyOnWriteArrayList iterates over a snapshot copy, and ConcurrentHashMap's iterator may or may not reflect changes made during iteration.",points:["Fail-fast: java.util collections, checks modCount vs expectedModCount","Throws ConcurrentModificationException - even in a single thread","Safe removal: Iterator.remove() or list.removeIf(...)","Fail-safe/snapshot: CopyOnWriteArrayList works on a copy (costly writes)","Weakly consistent: ConcurrentHashMap, never throws CME","Fail-fast is best-effort; do not rely on it for correctness"],code:`List<Integer> list = new ArrayList<>(List.of(1, 2, 3, 4));
try {
    for (Integer n : list) {
        if (n == 2) list.remove(n);           // structural change during iteration
    }
} catch (ConcurrentModificationException e) {
    System.out.println("CME thrown");
}

list.removeIf(n -> n % 2 == 0);              // correct way
System.out.println(list);                     // [1, 3]

List<Integer> cow = new CopyOnWriteArrayList<>(List.of(1, 2, 3));
for (Integer n : cow) cow.add(n);             // no exception, iterates the snapshot
System.out.println(cow);                      // [1, 2, 3, 1, 2, 3]`},{id:"jl-10",level:"mid",topic:"java-collections",difficulty:"medium",simple:{hi:"Stream ek dhaba ka order system hai. Intermediate operations sirf recipe likhte hain (sabzi kaato, masala daalo), lekin chulha tabhi jalta hai jab customer bolta hai 'serve karo' (terminal operation). Aur agar customer ko sirf pehli plate chahiye, to baaki plates banti hi nahi.",en:"A stream is like a dhaba's order system. Intermediate operations only write down the recipe (cut vegetables, add masala), but the stove is lit only when the customer says 'serve it' (terminal operation). And if the customer wants just the first plate, the other plates are never cooked.",bn:"Stream \u09B9\u09B2\u09CB \u09A7\u09BE\u09AC\u09BE\u09B0 \u0985\u09B0\u09CD\u09A1\u09BE\u09B0 \u09AC\u09CD\u09AF\u09AC\u09B8\u09CD\u09A5\u09BE\u09B0 \u09AE\u09A4\u09CB\u0964 Intermediate operations \u09B6\u09C1\u09A7\u09C1 \u09B0\u09C7\u09B8\u09BF\u09AA\u09BF \u09B2\u09BF\u0996\u09C7 \u09B0\u09BE\u0996\u09C7 (\u09B8\u09AC\u099C\u09BF \u0995\u09BE\u099F\u09CB, \u09AE\u09B6\u09B2\u09BE \u09A6\u09BE\u0993), \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0989\u09A8\u09C1\u09A8 \u099C\u09CD\u09AC\u09B2\u09C7 \u09A4\u0996\u09A8\u0987 \u09AF\u0996\u09A8 \u0996\u09A6\u09CD\u09A6\u09C7\u09B0 \u09AC\u09B2\u09C7 '\u09AA\u09B0\u09BF\u09AC\u09C7\u09B6\u09A8 \u0995\u09B0\u09CB' (terminal operation)\u0964 \u0986\u09B0 \u0996\u09A6\u09CD\u09A6\u09C7\u09B0 \u09AF\u09A6\u09BF \u09B6\u09C1\u09A7\u09C1 \u09AA\u09CD\u09B0\u09A5\u09AE \u09AA\u09CD\u09B2\u09C7\u099F \u099A\u09BE\u09AF\u09BC, \u09AC\u09BE\u0995\u09BF \u09AA\u09CD\u09B2\u09C7\u099F\u0997\u09C1\u09B2\u09CB \u09B0\u09BE\u09A8\u09CD\u09A8\u09BE\u0987 \u09B9\u09AF\u09BC \u09A8\u09BE\u0964"},question:"What is the difference between intermediate and terminal operations in Streams? What does this code print and why?",answer:'Intermediate operations (filter, map, sorted, distinct, limit) return a new Stream and are lazy: nothing runs until a terminal operation (collect, forEach, reduce, count, findFirst) is called. Elements then flow through the whole pipeline one at a time rather than stage by stage, and short-circuiting operations like findFirst stop as soon as they have an answer. So this code prints "filter a", "filter bb", "map bb", "BB" - "ccc" and "dd" are never examined. Without findFirst() it would print nothing at all.',points:["Intermediate: return Stream, lazy, can be stateless (map) or stateful (sorted, distinct)","Terminal: produces a result or side effect and closes the stream","Processing is vertical (element by element), not horizontal","Short-circuiting: findFirst, anyMatch, limit stop early","A stream can be consumed only once (IllegalStateException otherwise)","reduce combines elements: stream.reduce(0, Integer::sum)"],code:`Stream.of("a", "bb", "ccc", "dd")
      .filter(s -> {
          System.out.println("filter " + s);
          return s.length() > 1;
      })
      .map(s -> {
          System.out.println("map " + s);
          return s.toUpperCase();
      })
      .findFirst()
      .ifPresent(System.out::println);
// Output:
// filter a
// filter bb
// map bb
// BB

int total = List.of(1, 2, 3, 4).stream().reduce(0, Integer::sum); // 10`},{id:"jl-11",level:"mid",topic:"java-collections",difficulty:"medium",simple:{hi:"groupingBy ek teacher jaisa hai jo saare bachchon ko house ke hisaab se (Red, Blue, Green) alag-alag line mein khada karta hai. Phir downstream collector har line ka hisaab nikalta hai, jaise average marks ya sabse lamba bachcha kaun.",en:"groupingBy is like a teacher who puts all the children into separate lines by house (Red, Blue, Green). Then the downstream collector works out something for each line, like the average marks or who the tallest child is.",bn:"groupingBy \u09B9\u09B2\u09CB \u098F\u09AE\u09A8 \u098F\u0995\u099C\u09A8 \u09B6\u09BF\u0995\u09CD\u09B7\u0995\u09C7\u09B0 \u09AE\u09A4\u09CB \u09AF\u09BF\u09A8\u09BF \u09B8\u09AC \u09AC\u09BE\u099A\u09CD\u099A\u09BE\u0995\u09C7 house \u0985\u09A8\u09C1\u09AF\u09BE\u09AF\u09BC\u09C0 (Red, Blue, Green) \u0986\u09B2\u09BE\u09A6\u09BE \u09B2\u09BE\u0987\u09A8\u09C7 \u09A6\u09BE\u0981\u09A1\u09BC \u0995\u09B0\u09BE\u09A8\u0964 \u09A4\u09BE\u09B0\u09AA\u09B0 downstream collector \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BE \u09B2\u09BE\u0987\u09A8\u09C7\u09B0 \u09B9\u09BF\u09B8\u09BE\u09AC \u09AC\u09C7\u09B0 \u0995\u09B0\u09C7, \u09AF\u09C7\u09AE\u09A8 \u0997\u09A1\u09BC \u09A8\u09AE\u09CD\u09AC\u09B0 \u09AC\u09BE \u09B8\u09AC\u099A\u09C7\u09AF\u09BC\u09C7 \u09B2\u09AE\u09CD\u09AC\u09BE \u09AC\u09BE\u099A\u09CD\u099A\u09BE \u0995\u09C7\u0964"},question:"Write a stream that groups employees by department and finds the average salary and the highest-paid employee per department.",answer:"Use Collectors.groupingBy(classifier, downstream): the classifier picks the key (department), and the downstream collector decides what to compute for each group - averagingDouble for the average, maxBy or counting, mapping, etc. Passing TreeMap::new as the map factory gives sorted keys, since the default map type is unspecified. Collectors.partitioningBy is the special case that splits into exactly two groups (true/false), and Collectors.toMap needs a merge function if keys can repeat.",points:["groupingBy(classifier) -> Map<K, List<T>>","groupingBy(classifier, downstream) e.g. counting(), averagingDouble(), mapping(), maxBy()","groupingBy(classifier, mapFactory, downstream) to choose TreeMap etc.","maxBy returns Optional; wrap with collectingAndThen to unwrap","partitioningBy for a boolean split; toMap(k, v, merge) for duplicates"],code:`record Employee(String name, String dept, double salary) {}

List<Employee> emps = List.of(
        new Employee("Asha", "IT", 90_000), new Employee("Ravi", "IT", 70_000),
        new Employee("Meena", "HR", 50_000), new Employee("John", "HR", 60_000));

Map<String, Double> avgByDept = emps.stream()
        .collect(Collectors.groupingBy(Employee::dept, TreeMap::new,
                 Collectors.averagingDouble(Employee::salary)));
System.out.println(avgByDept);        // {HR=55000.0, IT=80000.0}

Map<String, String> topByDept = emps.stream()
        .collect(Collectors.groupingBy(Employee::dept, TreeMap::new,
                 Collectors.collectingAndThen(
                     Collectors.maxBy(Comparator.comparingDouble(Employee::salary)),
                     e -> e.map(Employee::name).orElse("-"))));
System.out.println(topByDept);        // {HR=John, IT=Asha}`},{id:"jl-12",level:"mid",topic:"java-collections",difficulty:"medium",simple:{hi:"Optional ek gift box jaisa hai jisme gift ho bhi sakta hai aur khaali bhi ho sakta hai. Seedha haath daalne (get) ki jagah pehle dekho, aur khaali ho to apna plan B (orElse) ready rakho.",en:"Optional is like a gift box that may or may not have a gift inside. Instead of reaching in blindly (get), check first, and keep a plan B (orElse) ready in case it is empty.",bn:"Optional \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE \u0989\u09AA\u09B9\u09BE\u09B0\u09C7\u09B0 \u09AC\u09BE\u0995\u09CD\u09B8\u09C7\u09B0 \u09AE\u09A4\u09CB, \u09AD\u09C7\u09A4\u09B0\u09C7 \u0989\u09AA\u09B9\u09BE\u09B0 \u09A5\u09BE\u0995\u09A4\u09C7\u0993 \u09AA\u09BE\u09B0\u09C7, \u09AB\u09BE\u0981\u0995\u09BE\u0993 \u09B9\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u0964 \u09A8\u09BE \u09A6\u09C7\u0996\u09C7 \u09B9\u09BE\u09A4 \u09A2\u09CB\u0995\u09BE\u09A8\u09CB\u09B0 (get) \u09AC\u09A6\u09B2\u09C7 \u0986\u0997\u09C7 \u09A6\u09C7\u0996\u09C7 \u09A8\u09BE\u0993, \u0986\u09B0 \u09AB\u09BE\u0981\u0995\u09BE \u09B9\u09B2\u09C7 plan B (orElse) \u09A4\u09C8\u09B0\u09BF \u09B0\u09BE\u0996\u09CB\u0964"},question:"What is Optional, and what are the best practices and common mistakes when using it?",answer:"Optional<T> is a container that either holds a non-null value or is empty, designed mainly as a method return type to say clearly 'there may be no result' instead of returning null. You consume it with map, filter, flatMap, orElse, orElseGet, orElseThrow or ifPresentOrElse rather than calling get() blindly. It is not meant for fields, method parameters or collections, and it is not Serializable.",points:["Create: Optional.of(v) (NPE if null), Optional.ofNullable(v), Optional.empty()","orElse(x) always evaluates x; orElseGet(supplier) is lazy - use it for costly defaults","Prefer orElseThrow() over get(); avoid isPresent() + get() pairs","Do not return null from a method that returns Optional","Avoid Optional as field/parameter/collection element; return an empty list instead of Optional<List>","Primitive variants: OptionalInt, OptionalLong, OptionalDouble"],code:`record User(String name, String email) {}

Optional<User> findUser(String id) {
    return "1".equals(id) ? Optional.of(new User("Ravi", null)) : Optional.empty();
}

String email = findUser("1")
        .map(User::email)                 // Optional.ofNullable semantics -> empty
        .filter(e -> e.contains("@"))
        .orElse("not-provided");
System.out.println(email);                // not-provided

User u = findUser("2")
        .orElseGet(() -> new User("Guest", null));   // lazy default
System.out.println(u.name());             // Guest

// findUser("2").orElseThrow();  -> NoSuchElementException`},{id:"jl-13",level:"senior",topic:"java-collections",difficulty:"hard",simple:{hi:"Socho ek hi building ke saare log ek hi letter box use kar rahe hain (same hashCode). Pehle letters ek dher (list) mein padte hain, lekin 8 se zyada ho gaye to postman unhe alphabetical file (tree) mein laga deta hai taaki jaldi mile. Aur poora post office chhota pad jaaye to boxes double ho jaate hain.",en:"Imagine everyone in one building sharing a single letter box (same hashCode). At first the letters lie in a pile (list), but once there are more than 8, the postman puts them in an alphabetical file (tree) so they are found quickly. And when the whole post office gets crowded, the number of boxes is doubled.",bn:"\u09AD\u09BE\u09AC\u09CB \u098F\u0995\u099F\u09BE \u09AC\u09BF\u09B2\u09CD\u09A1\u09BF\u0982\u09AF\u09BC\u09C7\u09B0 \u09B8\u09AC\u09BE\u0987 \u098F\u0995\u099F\u09BE\u0987 \u099A\u09BF\u09A0\u09BF\u09B0 \u09AC\u09BE\u0995\u09CD\u09B8 \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u099B\u09C7 (\u098F\u0995\u0987 hashCode)\u0964 \u09AA\u09CD\u09B0\u09A5\u09AE\u09C7 \u099A\u09BF\u09A0\u09BF\u0997\u09C1\u09B2\u09CB \u098F\u0995\u099F\u09BE \u09B8\u09CD\u09A4\u09C2\u09AA\u09C7 (list) \u09AA\u09A1\u09BC\u09C7, \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09EE\u099F\u09BE\u09B0 \u09AC\u09C7\u09B6\u09BF \u09B9\u09B2\u09C7 \u09AA\u09BF\u09AF\u09BC\u09A8 \u09B8\u09C7\u0997\u09C1\u09B2\u09CB \u09AC\u09B0\u09CD\u09A3\u09BE\u09A8\u09C1\u0995\u09CD\u09B0\u09AE\u09BF\u0995 \u09AB\u09BE\u0987\u09B2\u09C7 (tree) \u09B8\u09BE\u099C\u09BF\u09AF\u09BC\u09C7 \u09B0\u09BE\u0996\u09C7\u09A8 \u09AF\u09BE\u09A4\u09C7 \u09A4\u09BE\u09A1\u09BC\u09BE\u09A4\u09BE\u09A1\u09BC\u09BF \u09AA\u09BE\u0993\u09AF\u09BC\u09BE \u09AF\u09BE\u09AF\u09BC\u0964 \u0986\u09B0 \u09AA\u09C1\u09B0\u09CB \u09AA\u09CB\u09B8\u09CD\u099F \u0985\u09AB\u09BF\u09B8 \u09AD\u09BF\u09A1\u09BC\u09C7 \u09AD\u09B0\u09C7 \u0997\u09C7\u09B2\u09C7 \u09AC\u09BE\u0995\u09CD\u09B8\u09C7\u09B0 \u09B8\u0982\u0996\u09CD\u09AF\u09BE \u09A6\u09CD\u09AC\u09BF\u0997\u09C1\u09A3 \u09B9\u09AF\u09BC\u09C7 \u09AF\u09BE\u09AF\u09BC\u0964"},question:"Explain HashMap collisions, treeification and resizing in depth. What happens if many keys have the same hashCode?",answer:"When keys map to the same bucket, Java 8+ chains them in a linked list; if one bucket reaches TREEIFY_THRESHOLD (8) nodes and the table has at least 64 buckets, that bucket becomes a red-black tree, turning worst-case lookups from O(n) into O(log n) (with a smaller table it resizes instead). The tree turns back into a list when it shrinks to 6 nodes. On resize the table doubles, and because the size is a power of two each entry either stays at index i or moves to i + oldCapacity, decided by one bit of its hash, so no full rehash is needed. If many keys share a hashCode, everything piles into one bucket; treeification limits the damage, and works best when keys are Comparable so the tree can order them.",points:["TREEIFY_THRESHOLD = 8, UNTREEIFY_THRESHOLD = 6, MIN_TREEIFY_CAPACITY = 64","Treeification protects against hash-flooding DoS attacks","Resize: new capacity = old x 2, split each bin into 'lo' and 'hi' lists","Resize is O(n) - pre-size with HashMap.newHashMap(expected) (Java 19+) or new HashMap<>(n / 0.75f + 1)","Bad hashCode (e.g. constant) makes the map behave like a list or tree","Concurrent writes to a plain HashMap during resize can lose entries - use ConcurrentHashMap"],code:`record BadKey(int id) implements Comparable<BadKey> {
    @Override public int hashCode() { return 42; }            // every key collides
    @Override public int compareTo(BadKey o) { return Integer.compare(id, o.id); }
}

Map<BadKey, Integer> map = new HashMap<>();
for (int i = 0; i < 10_000; i++) map.put(new BadKey(i), i);
// All entries sit in ONE bucket. After 8 nodes (and table >= 64)
// the bucket becomes a red-black tree, so get() is O(log n), not O(n).
System.out.println(map.get(new BadKey(9_999)));   // 9999

// Pre-size to avoid repeated resizing for ~1M entries
Map<String, Integer> big = HashMap.newHashMap(1_000_000);`},{id:"jl-14",level:"senior",topic:"java-collections",difficulty:"hard",simple:{hi:"Parallel stream ek shaadi ki rasoi jaisa hai jahan kai cooks milke kaam karte hain. 1000 rotiyan banani hon to bahut fayda, par 2 rotiyon ke liye sabko bulana time waste hai. Aur agar sab cooks ek hi tawe par ek saath roti daalein (shared state), to rotiyan jal jaayengi ya gir jaayengi.",en:"A parallel stream is like a wedding kitchen where many cooks work together. For 1000 rotis it is a big help, but calling everyone for 2 rotis wastes time. And if all the cooks throw rotis onto the same tawa at once (shared state), some get burnt or fall off.",bn:"Parallel stream \u09B9\u09B2\u09CB \u09AC\u09BF\u09AF\u09BC\u09C7\u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u09B0\u09BE\u09A8\u09CD\u09A8\u09BE\u0998\u09B0\u09C7\u09B0 \u09AE\u09A4\u09CB, \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 \u0985\u09A8\u09C7\u0995 \u09B0\u09BE\u0981\u09A7\u09C1\u09A8\u09BF \u098F\u0995\u09B8\u09BE\u09A5\u09C7 \u0995\u09BE\u099C \u0995\u09B0\u09C7\u0964 \u09E7\u09E6\u09E6\u09E6\u099F\u09BE \u09B0\u09C1\u099F\u09BF \u09AC\u09BE\u09A8\u09BE\u09A4\u09C7 \u0996\u09C1\u09AC \u0995\u09BE\u099C\u09C7 \u0986\u09B8\u09C7, \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09E8\u099F\u09CB \u09B0\u09C1\u099F\u09BF\u09B0 \u099C\u09A8\u09CD\u09AF \u09B8\u09AC\u09BE\u0987\u0995\u09C7 \u09A1\u09BE\u0995\u09BE \u09B8\u09AE\u09AF\u09BC \u09A8\u09B7\u09CD\u099F\u0964 \u0986\u09B0 \u09B8\u09AC \u09B0\u09BE\u0981\u09A7\u09C1\u09A8\u09BF \u098F\u0995\u0987 \u09A4\u09BE\u0993\u09AF\u09BC\u09BE\u09AF\u09BC \u098F\u0995\u09B8\u09BE\u09A5\u09C7 \u09B0\u09C1\u099F\u09BF \u09A6\u09BF\u09B2\u09C7 (shared state) \u0995\u09BF\u099B\u09C1 \u09AA\u09C1\u09A1\u09BC\u09AC\u09C7 \u09AC\u09BE \u09AA\u09A1\u09BC\u09C7 \u09AF\u09BE\u09AC\u09C7\u0964"},question:"When should you use parallel streams, and when do they hurt? Your teammate made a stream parallel and the results became wrong and slower - what could be the reasons?",answer:"Parallel streams split the source and process chunks on the common ForkJoinPool (by default about one thread per CPU core minus one), then combine results. They help only for large, CPU-bound work on easily splittable sources (arrays, ArrayList, IntStream.range) with stateless, non-interfering operations and a cheap combine step. Wrong results usually come from shared mutable state (adding to an ArrayList or a counter from forEach) or non-associative reduce functions; slowness comes from small data, poorly splitting sources (LinkedList, Stream.iterate), ordering constraints (findFirst, limit, forEachOrdered), boxing, or blocking I/O that starves the shared common pool.",points:["Runs on ForkJoinPool.commonPool() shared by the whole JVM","Good: large N, CPU-heavy per element, splittable source, associative reduction","Bad: I/O or blocking calls, small lists, LinkedList/iterate, ordered short-circuit ops","Never mutate shared state; use collect/reduce instead of forEach + add","reduce identity must be a true identity and the operation associative","Always measure (e.g. JMH) before and after"],code:`List<Integer> nums = IntStream.rangeClosed(1, 100_000).boxed().toList();

// WRONG: shared, non-thread-safe list -> lost elements or exceptions
List<Integer> unsafe = new ArrayList<>();
nums.parallelStream().filter(n -> n % 2 == 0).forEach(unsafe::add);

// RIGHT: let the stream combine results
List<Integer> evens = nums.parallelStream()
        .filter(n -> n % 2 == 0)
        .toList();
System.out.println(evens.size());            // 50000

// CPU-bound, splittable, primitive -> a good parallel candidate
long sumSquares = LongStream.rangeClosed(1, 10_000_000)
        .parallel()
        .map(x -> x * x % 7)
        .sum();`},{id:"jt-1",level:"fresher",topic:"java-concurrency",difficulty:"easy",simple:{hi:"Thread ek naya delivery boy hai. Runnable ek parchi hai 'ye saamaan pahuncha do', kaam ho gaya bas. Callable ek parchi hai 'pahuncha ke receipt wapas lao', yaani kaam ke baad result bhi milta hai.",en:"A thread is a new delivery boy. A Runnable is a note saying 'deliver this parcel' and that is it. A Callable is a note saying 'deliver it and bring back the receipt', so you also get a result after the work.",bn:"Thread \u09B9\u09B2\u09CB \u098F\u0995\u099C\u09A8 \u09A8\u09A4\u09C1\u09A8 \u09A1\u09C7\u09B2\u09BF\u09AD\u09BE\u09B0\u09BF \u09AC\u09AF\u09BC\u0964 Runnable \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE \u099A\u09BF\u09B0\u0995\u09C1\u099F '\u098F\u0987 \u09AA\u09BE\u09B0\u09CD\u09B8\u09C7\u09B2\u099F\u09BE \u09AA\u09CC\u0981\u099B\u09C7 \u09A6\u09BE\u0993', \u09AC\u09CD\u09AF\u09B8\u0964 Callable \u09B9\u09B2\u09CB \u099A\u09BF\u09B0\u0995\u09C1\u099F '\u09AA\u09CC\u0981\u099B\u09C7 \u09A6\u09BF\u09AF\u09BC\u09C7 \u09B0\u09B8\u09BF\u09A6 \u09A8\u09BF\u09AF\u09BC\u09C7 \u098F\u09B8\u09CB', \u09AE\u09BE\u09A8\u09C7 \u0995\u09BE\u099C\u09C7\u09B0 \u09AA\u09B0\u09C7 \u098F\u0995\u099F\u09BE \u09AB\u09B2\u0993 \u09AA\u09BE\u0993\u09AF\u09BC\u09BE \u09AF\u09BE\u09AF\u09BC\u0964"},question:"What are the different ways to create a thread in Java? What is the difference between Runnable and Callable?",answer:"You can extend Thread and override run(), or better, pass a Runnable (often a lambda) to a Thread, or submit a Runnable or Callable to an ExecutorService. Runnable.run() returns nothing and cannot throw checked exceptions, while Callable.call() returns a value and can throw checked exceptions; submitting a Callable gives you a Future to fetch the result. Java 21 also offers virtual threads via Thread.ofVirtual() or Thread.startVirtualThread(). Always call start() - calling run() directly just runs the code on the current thread.",points:["extends Thread (wastes your single inheritance) vs implements Runnable (preferred)","Callable<V>: returns V, may throw Exception; used with ExecutorService.submit -> Future<V>","start() creates a new thread; run() is an ordinary method call","Calling start() twice throws IllegalThreadStateException","Java 21: Thread.ofPlatform() / Thread.ofVirtual() builders","In real code prefer executors over creating raw threads"],code:`Thread t1 = new Thread(() -> System.out.println("Runnable on " + Thread.currentThread().getName()));
t1.start();

Callable<Integer> task = () -> 2 + 3;              // returns a value
try (ExecutorService pool = Executors.newFixedThreadPool(2)) {
    Future<Integer> future = pool.submit(task);
    System.out.println("Callable result: " + future.get());   // 5
}

Thread vt = Thread.ofVirtual().start(() -> System.out.println("virtual thread"));
vt.join();
t1.join();`},{id:"jt-2",level:"fresher",topic:"java-concurrency",difficulty:"easy",simple:{hi:"Thread ki life ek cricket player jaisi hai: team mein naam aaya (NEW), maidan mein khel raha hai ya batting ka intezaar (RUNNABLE), pad pehen ke kisi aur ke out hone ka wait (WAITING), drinks break ka fixed time (TIMED_WAITING), aur out hoke pavilion wapas (TERMINATED).",en:"A thread's life is like a cricket player's: named in the team (NEW), playing on the field or ready to bat (RUNNABLE), padded up waiting for someone else to get out (WAITING), a fixed drinks break (TIMED_WAITING), and back to the pavilion after getting out (TERMINATED).",bn:"Thread-\u098F\u09B0 \u099C\u09C0\u09AC\u09A8 \u098F\u0995\u099C\u09A8 \u0995\u09CD\u09B0\u09BF\u0995\u09C7\u099F \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u09C7\u09B0 \u09AE\u09A4\u09CB: \u09A6\u09B2\u09C7 \u09A8\u09BE\u09AE \u0989\u09A0\u09B2 (NEW), \u09AE\u09BE\u09A0\u09C7 \u0996\u09C7\u09B2\u099B\u09C7 \u09AC\u09BE \u09AC\u09CD\u09AF\u09BE\u099F \u0995\u09B0\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09A4\u09C8\u09B0\u09BF (RUNNABLE), \u09AA\u09CD\u09AF\u09BE\u09A1 \u09AA\u09B0\u09C7 \u0985\u09A8\u09CD\u09AF \u0995\u09BE\u09B0\u09CB \u0986\u0989\u099F \u09B9\u0993\u09AF\u09BC\u09BE\u09B0 \u0985\u09AA\u09C7\u0995\u09CD\u09B7\u09BE (WAITING), \u09A8\u09BF\u09B0\u09CD\u09A6\u09BF\u09B7\u09CD\u099F \u09B8\u09AE\u09AF\u09BC\u09C7\u09B0 drinks break (TIMED_WAITING), \u0986\u09B0 \u0986\u0989\u099F \u09B9\u09AF\u09BC\u09C7 \u09AA\u09CD\u09AF\u09BE\u09AD\u09BF\u09B2\u09BF\u09AF\u09BC\u09A8\u09C7 \u09AB\u09C7\u09B0\u09BE (TERMINATED)\u0964"},question:"Explain the lifecycle (states) of a thread in Java.",answer:"A Java thread is in one of six Thread.State values. NEW means created but start() not yet called; RUNNABLE means running or ready to run (the JVM does not separate the two); BLOCKED means waiting to acquire a monitor lock to enter a synchronized block. WAITING means waiting indefinitely for another thread (wait(), join(), LockSupport.park()), TIMED_WAITING is the same with a timeout (sleep(ms), wait(ms), join(ms)), and TERMINATED means run() has finished.",points:["NEW -> start() -> RUNNABLE","RUNNABLE <-> BLOCKED (waiting for a synchronized monitor)","RUNNABLE <-> WAITING / TIMED_WAITING (wait, join, sleep, park)","TERMINATED after run() completes or throws","A thread cannot be restarted once terminated","Inspect with getState() or a thread dump (jstack, jcmd Thread.print)","Always call wait() in a loop that checks a condition \u2014 it guards against lost notifications and spurious wake-ups"],code:`Object lock = new Object();
boolean[] ready = {false};
Thread t = new Thread(() -> {
    synchronized (lock) {
        while (!ready[0]) {                       // guarded wait: a notify can't be lost
            try { lock.wait(); }
            catch (InterruptedException e) { Thread.currentThread().interrupt(); return; }
        }
    }
});
System.out.println(t.getState());   // NEW
t.start();
while (t.getState() != Thread.State.WAITING) Thread.onSpinWait();
System.out.println(t.getState());   // WAITING (inside lock.wait())
synchronized (lock) { ready[0] = true; lock.notify(); }
t.join();
System.out.println(t.getState());   // TERMINATED`},{id:"jt-3",level:"fresher",topic:"java-concurrency",difficulty:"easy",simple:{hi:"JVM ek ghar jaisa hai. Heap bada common store room hai jahan sabka saamaan (objects) rakha hai aur safai wala (GC) bekaar saamaan hata deta hai. Stack har bachche ki apni school bag hai jisme sirf aaj ki copies hain. Metaspace ghar ka naksha aur rules ki file hai (class ki jaankari).",en:"The JVM is like a house. The heap is the big shared store room where everyone's things (objects) are kept, and the cleaner (GC) removes junk. The stack is each child's own school bag with just today's notebooks. Metaspace is the file with the house plan and rules (class information).",bn:"JVM \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u09AE\u09A4\u09CB\u0964 Heap \u09B9\u09B2\u09CB \u09AC\u09A1\u09BC \u098F\u0995\u099F\u09BE \u09B8\u09AC\u09BE\u09B0 \u09AD\u09BE\u0981\u09A1\u09BC\u09BE\u09B0 \u0998\u09B0, \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 \u09B8\u09AC\u09BE\u09B0 \u099C\u09BF\u09A8\u09BF\u09B8 (objects) \u09A5\u09BE\u0995\u09C7 \u0986\u09B0 \u099D\u09BE\u09A1\u09BC\u09C1\u09A6\u09BE\u09B0 (GC) \u0985\u0995\u09C7\u099C\u09CB \u099C\u09BF\u09A8\u09BF\u09B8 \u09B8\u09B0\u09BF\u09AF\u09BC\u09C7 \u09A6\u09C7\u09AF\u09BC\u0964 Stack \u09B9\u09B2\u09CB \u09AA\u09CD\u09B0\u09A4\u09CD\u09AF\u09C7\u0995 \u09AC\u09BE\u099A\u09CD\u099A\u09BE\u09B0 \u09A8\u09BF\u099C\u09C7\u09B0 \u09B8\u09CD\u0995\u09C1\u09B2\u09AC\u09CD\u09AF\u09BE\u0997, \u09B6\u09C1\u09A7\u09C1 \u0986\u099C\u0995\u09C7\u09B0 \u0996\u09BE\u09A4\u09BE \u09A5\u09BE\u0995\u09C7\u0964 Metaspace \u09B9\u09B2\u09CB \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u09A8\u0995\u09B6\u09BE \u0986\u09B0 \u09A8\u09BF\u09AF\u09BC\u09AE\u09C7\u09B0 \u09AB\u09BE\u0987\u09B2 (class-\u098F\u09B0 \u09A4\u09A5\u09CD\u09AF)\u0964"},question:"What are the main memory areas of the JVM (heap, stack, metaspace)?",answer:"The heap is shared by all threads and holds objects and arrays; it is managed by the garbage collector and usually split into young (eden, survivor) and old generations. Each thread has its own stack, made of frames that hold local variables, primitive values and object references for each method call; it is freed automatically when a method returns. Metaspace (which replaced PermGen in Java 8) holds class metadata in native memory. There are also per-thread PC registers, native method stacks and the code cache for JIT-compiled code.",points:["Heap: objects, shared, GC-managed, sized with -Xms / -Xmx","Stack: one per thread, frames with locals and references, -Xss","Metaspace: class metadata in native memory, -XX:MaxMetaspaceSize","Deep recursion -> StackOverflowError; full heap -> OutOfMemoryError: Java heap space","Too many loaded classes -> OutOfMemoryError: Metaspace","String pool lives on the heap (since Java 7)"],code:`public class MemoryDemo {
    static int counter = 0;                  // static field: stored with the class's data (heap)

    public static void main(String[] args) {
        int age = 25;                        // primitive local -> main's stack frame
        String name = new String("Ravi");    // reference on stack, object on heap
        int[] marks = {90, 80};              // array object on heap
        greet(name);                         // new stack frame pushed
    }                                        // frames popped, objects become GC-eligible

    static void greet(String n) {
        System.out.println("Hi " + n);
    }
}
// MemoryDemo's class metadata (methods, bytecode) -> Metaspace`},{id:"jt-4",level:"fresher",topic:"java-concurrency",difficulty:"easy",simple:{hi:"synchronized ek ATM cabin jaisa hai jismein ek hi chaabi (lock) hai. Jo andar gaya wo darwaza band kar leta hai, baaki log bahar line mein wait karte hain, aur nikalte waqt chaabi agle ko mil jaati hai.",en:"synchronized is like an ATM cabin with a single key (lock). Whoever goes in shuts the door, the others wait outside in line, and when that person leaves, the key passes to the next one.",bn:"synchronized \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE ATM \u0995\u09C7\u09AC\u09BF\u09A8\u09C7\u09B0 \u09AE\u09A4\u09CB \u09AF\u09BE\u09B0 \u098F\u0995\u099F\u09BE\u0987 \u099A\u09BE\u09AC\u09BF (lock)\u0964 \u09AF\u09C7 \u09AD\u09C7\u09A4\u09B0\u09C7 \u09A2\u09CB\u0995\u09C7 \u09B8\u09C7 \u09A6\u09B0\u099C\u09BE \u09AC\u09A8\u09CD\u09A7 \u0995\u09B0\u09C7 \u09A6\u09C7\u09AF\u09BC, \u09AC\u09BE\u0995\u09BF\u09B0\u09BE \u09AC\u09BE\u0987\u09B0\u09C7 \u09B2\u09BE\u0987\u09A8\u09C7 \u09A6\u09BE\u0981\u09A1\u09BC\u09BE\u09AF\u09BC, \u0986\u09B0 \u09AC\u09C7\u09B0\u09CB\u09A8\u09CB\u09B0 \u09B8\u09AE\u09AF\u09BC \u099A\u09BE\u09AC\u09BF \u09AA\u09B0\u09C7\u09B0 \u099C\u09A8\u09C7\u09B0 \u09B9\u09BE\u09A4\u09C7 \u09AF\u09BE\u09AF\u09BC\u0964"},question:"What does the synchronized keyword do? What is an intrinsic (monitor) lock?",answer:"Every Java object has an intrinsic lock (monitor). A synchronized method or block acquires that lock before running and releases it on exit, even on an exception, so only one thread at a time can execute code guarded by the same lock. A synchronized instance method locks 'this', a static synchronized method locks the Class object, and a synchronized block locks whatever object you pass. Besides mutual exclusion it guarantees visibility: changes made before releasing a lock are seen by the next thread that acquires it.",points:["Gives mutual exclusion + memory visibility (happens-before)","Instance method -> this; static method -> ClassName.class; block -> chosen object","Reentrant: the same thread can acquire the same lock again","Threads waiting for the monitor are in BLOCKED state","Keep critical sections small; prefer a private final lock object","count++ is read-modify-write, so it needs synchronization or AtomicInteger"],code:`class Counter {
    private int count = 0;
    private final Object lock = new Object();

    void increment() {
        synchronized (lock) {        // only one thread at a time
            count++;
        }
    }
    int get() { synchronized (lock) { return count; } }
}

Counter c = new Counter();
Runnable r = () -> { for (int i = 0; i < 10_000; i++) c.increment(); };
Thread a = new Thread(r), b = new Thread(r);
a.start(); b.start(); a.join(); b.join();
System.out.println(c.get());   // always 20000 (without synchronized: often less)`},{id:"jt-5",level:"junior",topic:"java-concurrency",difficulty:"medium",simple:{hi:"volatile ek school ke notice board jaisa hai. Har bachcha apni copy mein purani news nahi rakhta, seedha board dekhta hai, isliye 'kal chhutti hai' sabko turant pata chal jaata hai. Lekin agar do bachche ek saath board par score badlein, to ek ka likha mit sakta hai - uske liye lock chahiye.",en:"volatile is like a school notice board. No child keeps old news in their own notebook; everyone reads the board, so 'tomorrow is a holiday' reaches all at once. But if two children update the score on the board at the same moment, one change can get wiped out - for that you need a lock.",bn:"volatile \u09B9\u09B2\u09CB \u09B8\u09CD\u0995\u09C1\u09B2\u09C7\u09B0 \u09A8\u09CB\u099F\u09BF\u09B8 \u09AC\u09CB\u09B0\u09CD\u09A1\u09C7\u09B0 \u09AE\u09A4\u09CB\u0964 \u0995\u09CB\u09A8\u09CB \u09AC\u09BE\u099A\u09CD\u099A\u09BE \u09A8\u09BF\u099C\u09C7\u09B0 \u0996\u09BE\u09A4\u09BE\u09AF\u09BC \u09AA\u09C1\u09B0\u09A8\u09CB \u0996\u09AC\u09B0 \u09B0\u09BE\u0996\u09C7 \u09A8\u09BE, \u09B8\u09AC\u09BE\u0987 \u09B8\u09B0\u09BE\u09B8\u09B0\u09BF \u09AC\u09CB\u09B0\u09CD\u09A1 \u09A6\u09C7\u0996\u09C7, \u09A4\u09BE\u0987 '\u0995\u09BE\u09B2 \u099B\u09C1\u099F\u09BF' \u0996\u09AC\u09B0 \u09B8\u09AC\u09BE\u0987 \u09B8\u0999\u09CD\u0997\u09C7 \u09B8\u0999\u09CD\u0997\u09C7 \u099C\u09BE\u09A8\u09C7\u0964 \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09A6\u09C1\u099C\u09A8 \u098F\u0995\u09B8\u09BE\u09A5\u09C7 \u09AC\u09CB\u09B0\u09CD\u09A1\u09C7 \u09B8\u09CD\u0995\u09CB\u09B0 \u09AC\u09A6\u09B2\u09BE\u09B2\u09C7 \u098F\u0995\u099C\u09A8\u09C7\u09B0 \u09B2\u09C7\u0996\u09BE \u09AE\u09C1\u099B\u09C7 \u09AF\u09C7\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7 - \u09A4\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF lock \u09B2\u09BE\u0997\u09C7\u0964"},question:"What does volatile do? Explain it in terms of the Java Memory Model. Is volatile enough to make count++ thread-safe?",answer:"The Java Memory Model allows threads to cache values and the compiler/CPU to reorder instructions, so one thread may never see another thread's write. Declaring a field volatile guarantees visibility (every read sees the latest write) and ordering: a write to a volatile variable happens-before every later read of it, so everything written before the volatile write is also visible. But volatile does not give atomicity - count++ is a read, an add and a write, so two threads can still lose updates; use AtomicInteger or a lock for that.",points:["JMM defines when writes by one thread become visible to another (happens-before)","volatile: visibility + no reordering across it, no mutual exclusion","Good for flags (running/stop), status fields, safe publication","Not for compound actions: count++, check-then-act","Other happens-before edges: lock release/acquire, Thread.start(), Thread.join()","Classic use: double-checked locking needs the instance field to be volatile"],code:`class Worker implements Runnable {
    private volatile boolean running = true;   // without volatile the loop may never stop

    public void run() {
        while (running) {
            // do work
        }
        System.out.println("Stopped");
    }
    void stop() { running = false; }
}

Worker w = new Worker();
Thread t = new Thread(w);
t.start();
Thread.sleep(100);
w.stop();          // the change is guaranteed to be visible to t
t.join();

// volatile int count; count++  -> still a race. Use AtomicInteger.incrementAndGet()`},{id:"jt-6",level:"junior",topic:"java-concurrency",difficulty:"medium",simple:{hi:"Deadlock ek patli gali jaisa hai jahan do auto aamne-saamne aa gaye. Dono kehte hain 'pehle tum peeche hato', aur koi nahi hatta, to dono hamesha ke liye ruk jaate hain. Rule bana do 'hamesha pehle left wala jaayega' (same order), to jaam nahi lagega.",en:"A deadlock is like two autos meeting face to face in a narrow lane. Each says 'you reverse first', nobody moves, and both are stuck forever. Make a rule like 'the one from the left always goes first' (same order) and the jam never happens.",bn:"Deadlock \u09B9\u09B2\u09CB \u09B8\u09B0\u09C1 \u0997\u09B2\u09BF\u09A4\u09C7 \u09AE\u09C1\u0996\u09CB\u09AE\u09C1\u0996\u09BF \u09A6\u09C1\u099F\u09CB \u0985\u099F\u09CB\u09B0 \u09AE\u09A4\u09CB\u0964 \u09A6\u09C1\u099C\u09A8\u09C7\u0987 \u09AC\u09B2\u09C7 '\u0986\u0997\u09C7 \u09A4\u09C1\u09AE\u09BF \u09AA\u09BF\u099B\u09CB\u0993', \u0995\u09C7\u0989 \u09A8\u09A1\u09BC\u09C7 \u09A8\u09BE, \u09A4\u09BE\u0987 \u09A6\u09C1\u099C\u09A8\u09C7\u0987 \u099A\u09BF\u09B0\u0995\u09BE\u09B2 \u0986\u099F\u0995\u09C7 \u09A5\u09BE\u0995\u09C7\u0964 \u09A8\u09BF\u09AF\u09BC\u09AE \u09AC\u09BE\u09A8\u09BE\u0993 '\u09B8\u09AC\u09B8\u09AE\u09AF\u09BC \u09AC\u09BE\u0981\u09A6\u09BF\u0995\u09C7\u09B0\u099F\u09BE \u0986\u0997\u09C7 \u09AF\u09BE\u09AC\u09C7' (\u098F\u0995\u0987 \u0995\u09CD\u09B0\u09AE), \u09A4\u09BE\u09B9\u09B2\u09C7 \u099C\u09CD\u09AF\u09BE\u09AE \u09B9\u09AC\u09C7 \u09A8\u09BE\u0964"},question:"What is a deadlock? Write an example and explain how to prevent and detect it.",answer:"A deadlock happens when two or more threads each hold a lock and wait forever for a lock held by the other. It needs four conditions together: mutual exclusion, hold-and-wait, no preemption and circular wait. The most practical prevention is to always acquire locks in the same global order (which breaks circular wait); others are using tryLock() with a timeout, holding fewer locks, and not calling unknown code while holding a lock. You detect it with a thread dump (jstack or jcmd <pid> Thread.print shows 'Found one Java-level deadlock') or ThreadMXBean.findDeadlockedThreads().",points:["Coffman conditions: mutual exclusion, hold and wait, no preemption, circular wait","Prevention: consistent lock ordering (e.g. by account id)","ReentrantLock.tryLock(timeout) to back off and retry","Keep lock scope small; avoid nested locks and callbacks under a lock","Detection: jstack / jcmd Thread.print / VisualVM / ThreadMXBean","Related: livelock (threads keep reacting, no progress), starvation"],code:`Object lockA = new Object(), lockB = new Object();

Thread t1 = new Thread(() -> {
    synchronized (lockA) {
        sleep(50);
        synchronized (lockB) { System.out.println("t1 done"); }
    }
});
Thread t2 = new Thread(() -> {
    synchronized (lockB) {          // opposite order -> DEADLOCK
        sleep(50);
        synchronized (lockA) { System.out.println("t2 done"); }
    }
});
t1.start(); t2.start();             // both hang forever

// FIX: make t2 also lock A first, then B (same global order)

static void sleep(long ms) {
    try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
}`},{id:"jt-7",level:"junior",topic:"java-concurrency",difficulty:"medium",simple:{hi:"wait() aisa hai jaise chai ki dukaan pe tum kehte ho 'chai ban jaaye to bulana' aur bench chhod ke side mein khade ho jaate ho (lock chhod diya). notify() chaiwala ki awaaz hai 'chai ready!'. sleep() mein tum bench pe hi so jaate ho, kisi aur ko baithne nahi dete.",en:"wait() is like telling the tea stall 'call me when the chai is ready' and giving up your seat on the bench (releasing the lock). notify() is the chaiwala shouting 'chai ready!'. With sleep() you nap right on the bench and nobody else can sit there.",bn:"wait() \u09B9\u09B2\u09CB \u099A\u09BE\u09AF\u09BC\u09C7\u09B0 \u09A6\u09CB\u0995\u09BE\u09A8\u09C7 \u09AC\u09B2\u09BE '\u099A\u09BE \u09B9\u09B2\u09C7 \u09A1\u09C7\u0995\u09CB' \u0986\u09B0 \u09AC\u09C7\u099E\u09CD\u099A \u099B\u09C7\u09A1\u09BC\u09C7 \u09AA\u09BE\u09B6\u09C7 \u09A6\u09BE\u0981\u09A1\u09BC\u09BE\u09A8\u09CB (lock \u099B\u09C7\u09A1\u09BC\u09C7 \u09A6\u09C7\u0993\u09AF\u09BC\u09BE)\u0964 notify() \u09B9\u09B2\u09CB \u099A\u09BE\u0993\u09AF\u09BC\u09BE\u09B2\u09BE\u09B0 \u09A1\u09BE\u0995 '\u099A\u09BE \u09A4\u09C8\u09B0\u09BF!'\u0964 sleep()-\u098F \u09A4\u09C1\u09AE\u09BF \u09AC\u09C7\u099E\u09CD\u099A\u09C7\u0987 \u0998\u09C1\u09AE\u09BF\u09AF\u09BC\u09C7 \u09AA\u09A1\u09BC\u09CB, \u0985\u09A8\u09CD\u09AF \u0995\u09BE\u0989\u0995\u09C7 \u09AC\u09B8\u09A4\u09C7 \u09A6\u09BE\u0993 \u09A8\u09BE\u0964"},question:"How do wait(), notify() and notifyAll() work? What is the difference between wait() and sleep()?",answer:"wait(), notify() and notifyAll() are methods of Object used for inter-thread signalling on an object's monitor, so they must be called while holding that object's lock (inside synchronized), otherwise IllegalMonitorStateException is thrown. wait() releases the lock and suspends the thread until it is notified or interrupted, then re-acquires the lock before continuing; notify() wakes one waiting thread and notifyAll() wakes all of them. Always call wait() inside a while loop that re-checks the condition, because of spurious wakeups and other threads changing state. sleep() is a static Thread method that pauses for a time without releasing any lock.",points:["Must hold the monitor: call inside synchronized(obj) and use obj.wait()","wait() releases the lock; sleep() keeps it","Use while (!condition) wait(); never if","notifyAll() is safer than notify() when several conditions share one monitor","wait/notify are on Object; sleep is on Thread","Modern code usually uses BlockingQueue, Condition or CountDownLatch instead"],code:`class Mailbox {
    private String message;

    synchronized void put(String msg) throws InterruptedException {
        while (message != null) wait();      // releases the lock while waiting
        message = msg;
        notifyAll();                         // wake up waiting takers
    }

    synchronized String take() throws InterruptedException {
        while (message == null) wait();
        String m = message;
        message = null;
        notifyAll();                         // wake up waiting putters
        return m;
    }
}`},{id:"jt-8",level:"junior",topic:"java-concurrency",difficulty:"medium",simple:{hi:"Thread pool ek restaurant ke fixed waiters jaisa hai. Har customer ke liye naya waiter hire nahi karte; jo waiter free hai wo agla order le leta hai. Rush ho to order slip counter pe line (queue) mein lagti hai, aur bahut zyada rush ho to kuch extra waiters bulaye jaate hain.",en:"A thread pool is like a restaurant's fixed team of waiters. You do not hire a new waiter for every customer; whichever waiter is free takes the next order. In a rush, order slips wait in a line (queue) at the counter, and if it gets really busy, a few extra waiters are called in.",bn:"Thread pool \u09B9\u09B2\u09CB \u09B0\u09C7\u09B8\u09CD\u099F\u09C1\u09B0\u09C7\u09A8\u09CD\u099F\u09C7\u09B0 \u09A8\u09BF\u09B0\u09CD\u09A6\u09BF\u09B7\u09CD\u099F \u0995\u09AF\u09BC\u09C7\u0995\u099C\u09A8 \u0993\u09AF\u09BC\u09C7\u099F\u09BE\u09B0\u09C7\u09B0 \u09AE\u09A4\u09CB\u0964 \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BE \u0996\u09A6\u09CD\u09A6\u09C7\u09B0\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u09A8\u09A4\u09C1\u09A8 \u0993\u09AF\u09BC\u09C7\u099F\u09BE\u09B0 \u09B0\u09BE\u0996\u09BE \u09B9\u09AF\u09BC \u09A8\u09BE; \u09AF\u09C7 \u09AB\u09BE\u0981\u0995\u09BE \u09B8\u09C7 \u09AA\u09B0\u09C7\u09B0 \u0985\u09B0\u09CD\u09A1\u09BE\u09B0 \u09A8\u09C7\u09AF\u09BC\u0964 \u09AD\u09BF\u09A1\u09BC \u09B9\u09B2\u09C7 \u0985\u09B0\u09CD\u09A1\u09BE\u09B0\u09C7\u09B0 \u09B8\u09CD\u09B2\u09BF\u09AA \u0995\u09BE\u0989\u09A8\u09CD\u099F\u09BE\u09B0\u09C7 \u09B2\u09BE\u0987\u09A8\u09C7 (queue) \u09A5\u09BE\u0995\u09C7, \u0986\u09B0 \u0996\u09C1\u09AC \u09AD\u09BF\u09A1\u09BC \u09B9\u09B2\u09C7 \u0995\u09AF\u09BC\u09C7\u0995\u099C\u09A8 \u09AC\u09BE\u09A1\u09BC\u09A4\u09BF \u0993\u09AF\u09BC\u09C7\u099F\u09BE\u09B0 \u09A1\u09BE\u0995\u09BE \u09B9\u09AF\u09BC\u0964"},question:"What is ExecutorService? Explain thread pools and the parameters of ThreadPoolExecutor.",answer:"ExecutorService decouples submitting tasks from running them: you submit Runnable or Callable tasks and a pool of reused threads executes them, which avoids the cost of creating a thread per task and lets you bound concurrency. ThreadPoolExecutor is configured with corePoolSize, maximumPoolSize, keepAliveTime, a work queue, a ThreadFactory and a RejectedExecutionHandler: new tasks first fill core threads, then the queue, and only when the queue is full are extra threads up to the maximum created; beyond that tasks are rejected. Always shut the pool down with shutdown() and awaitTermination(), or use try-with-resources since ExecutorService is AutoCloseable in Java 21.",points:["Factory methods: newFixedThreadPool, newCachedThreadPool, newScheduledThreadPool, newVirtualThreadPerTaskExecutor","Order: core threads -> queue -> extra threads up to max -> reject","Rejection policies: AbortPolicy (default), CallerRunsPolicy, DiscardPolicy, DiscardOldestPolicy","newFixedThreadPool uses an unbounded queue - can cause OutOfMemoryError under load","Size: about cores for CPU-bound work, more for I/O-bound work","shutdown() = finish queued tasks; shutdownNow() = interrupt and return pending"],code:`ThreadPoolExecutor pool = new ThreadPoolExecutor(
        4,                                   // corePoolSize
        8,                                   // maximumPoolSize
        60, TimeUnit.SECONDS,                // keepAlive for extra threads
        new ArrayBlockingQueue<>(100),       // bounded work queue
        Executors.defaultThreadFactory(),
        new ThreadPoolExecutor.CallerRunsPolicy()); // back-pressure when full

for (int i = 1; i <= 5; i++) {
    int id = i;
    pool.submit(() -> System.out.println("Task " + id + " on " + Thread.currentThread().getName()));
}
pool.shutdown();                             // no new tasks, finish queued ones
pool.awaitTermination(10, TimeUnit.SECONDS);`},{id:"jt-9",level:"junior",topic:"java-concurrency",difficulty:"medium",simple:{hi:"Future ek courier tracking number jaisa hai: tumhe darwaze pe baith ke wait karna padta hai (get). CompletableFuture aisa hai jaise tum bol do 'parcel aaye to khol ke mummy ko de dena, aur na aaye to mujhe SMS kar dena' - tum apna kaam karte raho, steps apne aap hote rahenge.",en:"A Future is like a courier tracking number: you have to sit at the door and wait (get). A CompletableFuture is like saying 'when the parcel comes, open it and give it to mummy, and if it does not come, SMS me' - you carry on with your work and the steps happen on their own.",bn:"Future \u09B9\u09B2\u09CB \u0995\u09C1\u09B0\u09BF\u09AF\u09BC\u09BE\u09B0\u09C7\u09B0 \u099F\u09CD\u09B0\u09CD\u09AF\u09BE\u0995\u09BF\u0982 \u09A8\u09AE\u09CD\u09AC\u09B0\u09C7\u09B0 \u09AE\u09A4\u09CB: \u09A6\u09B0\u099C\u09BE\u09AF\u09BC \u09AC\u09B8\u09C7 \u0985\u09AA\u09C7\u0995\u09CD\u09B7\u09BE \u0995\u09B0\u09A4\u09C7 \u09B9\u09AF\u09BC (get)\u0964 CompletableFuture \u09B9\u09B2\u09CB \u09AC\u09B2\u09C7 \u09B0\u09BE\u0996\u09BE '\u09AA\u09BE\u09B0\u09CD\u09B8\u09C7\u09B2 \u098F\u09B2\u09C7 \u0996\u09C1\u09B2\u09C7 \u09AE\u09BE\u0995\u09C7 \u09A6\u09BF\u09AF\u09BC\u09C7 \u09A6\u09BF\u0993, \u09A8\u09BE \u098F\u09B2\u09C7 \u0986\u09AE\u09BE\u0995\u09C7 SMS \u0995\u09B0\u09CB' - \u09A4\u09C1\u09AE\u09BF \u09A8\u09BF\u099C\u09C7\u09B0 \u0995\u09BE\u099C \u0995\u09B0\u09A4\u09C7 \u09A5\u09BE\u0995\u09CB, \u09A7\u09BE\u09AA\u0997\u09C1\u09B2\u09CB \u09A8\u09BF\u099C\u09C7 \u09A8\u09BF\u099C\u09C7\u0987 \u09B9\u09AF\u09BC\u09C7 \u09AF\u09BE\u09AF\u09BC\u0964"},question:"What is the difference between Future and CompletableFuture?",answer:"A Future represents the result of an async task, but the only way to get it is the blocking get(), and you cannot chain further steps, combine futures or complete it manually. CompletableFuture implements both Future and CompletionStage, so you can build non-blocking pipelines: supplyAsync to start, thenApply to transform, thenCompose to chain another async call, thenCombine or allOf to join results, and exceptionally or handle for errors. By default its async methods run on ForkJoinPool.commonPool(), so for blocking I/O you should pass your own Executor.",points:["Future: get() blocks, isDone(), cancel(), no chaining or composition","CompletableFuture: supplyAsync / runAsync, thenApply, thenAccept, thenCompose, thenCombine","allOf / anyOf for many futures","Error handling: exceptionally, handle, whenComplete","join() throws unchecked CompletionException; get() throws checked exceptions","Pass a custom Executor for I/O work instead of the common pool"],code:`ExecutorService io = Executors.newFixedThreadPool(4);

CompletableFuture<String> user =
        CompletableFuture.supplyAsync(() -> "Ravi", io);        // e.g. DB call
CompletableFuture<Integer> orders =
        CompletableFuture.supplyAsync(() -> 3, io);             // e.g. REST call

String result = user
        .thenCombine(orders, (u, o) -> u + " has " + o + " orders")
        .thenApply(String::toUpperCase)
        .exceptionally(ex -> "fallback")
        .join();

System.out.println(result);   // RAVI HAS 3 ORDERS
io.shutdown();`},{id:"jt-10",level:"mid",topic:"java-concurrency",difficulty:"medium",simple:{hi:"synchronized ek automatic darwaza hai jo bahar nikalte hi khud band ho jaata hai. ReentrantLock ek manual taala hai jisme extra features hain, jaise 'ek second mein nahi khula to chhod do', par band karna tumhe khud yaad rakhna padta hai. AtomicInteger cricket scoreboard ka button hai jo ek click mein score badhata hai, bina kisi line ke.",en:"synchronized is an automatic door that closes by itself when you leave. ReentrantLock is a manual padlock with extra features, like 'if it does not open in one second, give up', but you must remember to lock it yourself. AtomicInteger is the cricket scoreboard button that adds a run in one click, with no queue.",bn:"synchronized \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE \u09B8\u09CD\u09AC\u09AF\u09BC\u0982\u0995\u09CD\u09B0\u09BF\u09AF\u09BC \u09A6\u09B0\u099C\u09BE, \u09AC\u09C7\u09B0\u09CB\u09B2\u09C7\u0987 \u09A8\u09BF\u099C\u09C7 \u09A5\u09C7\u0995\u09C7 \u09AC\u09A8\u09CD\u09A7 \u09B9\u09AF\u09BC\u0964 ReentrantLock \u09B9\u09B2\u09CB \u09B9\u09BE\u09A4\u09C7 \u09B2\u09BE\u0997\u09BE\u09A8\u09CB \u09A4\u09BE\u09B2\u09BE, \u09A4\u09BE\u09A4\u09C7 \u09AC\u09BE\u09A1\u09BC\u09A4\u09BF \u09B8\u09C1\u09AC\u09BF\u09A7\u09BE \u0986\u099B\u09C7 \u09AF\u09C7\u09AE\u09A8 '\u098F\u0995 \u09B8\u09C7\u0995\u09C7\u09A8\u09CD\u09A1\u09C7 \u09A8\u09BE \u0996\u09C1\u09B2\u09B2\u09C7 \u099B\u09C7\u09A1\u09BC\u09C7 \u09A6\u09BE\u0993', \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09AC\u09A8\u09CD\u09A7 \u0995\u09B0\u09BE\u09B0 \u0995\u09A5\u09BE \u09A8\u09BF\u099C\u09C7\u0995\u09C7\u0987 \u09AE\u09A8\u09C7 \u09B0\u09BE\u0996\u09A4\u09C7 \u09B9\u09AF\u09BC\u0964 AtomicInteger \u09B9\u09B2\u09CB \u0995\u09CD\u09B0\u09BF\u0995\u09C7\u099F \u09B8\u09CD\u0995\u09CB\u09B0\u09AC\u09CB\u09B0\u09CD\u09A1\u09C7\u09B0 \u09AC\u09CB\u09A4\u09BE\u09AE, \u098F\u0995 \u0995\u09CD\u09B2\u09BF\u0995\u09C7 \u09B0\u09BE\u09A8 \u09AC\u09BE\u09A1\u09BC\u09C7, \u0995\u09CB\u09A8\u09CB \u09B2\u09BE\u0987\u09A8 \u09B2\u09BE\u0997\u09C7 \u09A8\u09BE\u0964"},question:"Compare synchronized with ReentrantLock, and explain atomic classes like AtomicInteger.",answer:"ReentrantLock provides the same mutual exclusion and visibility as synchronized, but adds tryLock() (optionally with a timeout), lockInterruptibly(), an optional fairness policy and multiple Condition objects for separate wait-sets. The cost is that you must unlock it yourself in a finally block. Atomic classes (AtomicInteger, AtomicLong, AtomicReference) perform single-variable updates like incrementAndGet() or compareAndSet() lock-free using hardware compare-and-swap (CAS), which is faster than locking for simple counters; under very high contention LongAdder scales better.",points:["synchronized: simpler, automatic release, block-structured","ReentrantLock: tryLock, timed and interruptible locking, fairness, Conditions","Always: lock.lock(); try { ... } finally { lock.unlock(); }","ReadWriteLock / StampedLock for read-heavy data","Atomic*: CAS loop, lock-free, only for single-variable invariants","LongAdder for hot counters (metrics) with many writers"],code:`class Account {
    private final ReentrantLock lock = new ReentrantLock();
    private double balance = 1000;

    boolean withdraw(double amt) throws InterruptedException {
        if (!lock.tryLock(1, TimeUnit.SECONDS)) return false;   // avoid waiting forever
        try {
            if (balance < amt) return false;
            balance -= amt;
            return true;
        } finally {
            lock.unlock();                                     // always release
        }
    }
}

AtomicInteger visits = new AtomicInteger();
visits.incrementAndGet();                    // atomic, no lock
visits.compareAndSet(1, 100);                // set to 100 only if it is still 1
System.out.println(visits.get());            // 100`},{id:"jt-11",level:"mid",topic:"java-concurrency",difficulty:"medium",simple:{hi:"Platform thread ek bada bus driver hai - mehenga aur kam hain. Virtual threads chhote passengers hain jo ek hi bus mein baari-baari baithte hain: jo station pe ruk ke wait kar raha hai (I/O), wo utar jaata hai aur uski seat kisi aur ko mil jaati hai. Isliye kam buses mein hazaaron log safar kar lete hain.",en:"A platform thread is a bus driver - expensive and few in number. Virtual threads are passengers who take turns in the same bus: whoever is waiting at a stop (I/O) gets off and their seat goes to someone else. That is how thousands of people travel with only a few buses.",bn:"Platform thread \u09B9\u09B2\u09CB \u09AC\u09BE\u09B8\u09C7\u09B0 \u099A\u09BE\u09B2\u0995 - \u09A6\u09BE\u09AE\u09BF \u0986\u09B0 \u09B8\u0982\u0996\u09CD\u09AF\u09BE\u09AF\u09BC \u0995\u09AE\u0964 Virtual threads \u09B9\u09B2\u09CB \u09AF\u09BE\u09A4\u09CD\u09B0\u09C0, \u09AF\u09BE\u09B0\u09BE \u09AA\u09BE\u09B2\u09BE \u0995\u09B0\u09C7 \u098F\u0995\u0987 \u09AC\u09BE\u09B8\u09C7 \u09AC\u09B8\u09C7: \u09AF\u09C7 \u09B8\u09CD\u099F\u09AA\u09C7 \u0985\u09AA\u09C7\u0995\u09CD\u09B7\u09BE \u0995\u09B0\u099B\u09C7 (I/O) \u09B8\u09C7 \u09A8\u09C7\u09AE\u09C7 \u09AF\u09BE\u09AF\u09BC \u0986\u09B0 \u09A4\u09BE\u09B0 \u09B8\u09BF\u099F \u0985\u09A8\u09CD\u09AF \u0995\u09C7\u0989 \u09AA\u09BE\u09AF\u09BC\u0964 \u09A4\u09BE\u0987 \u0985\u09B2\u09CD\u09AA \u0995\u09AF\u09BC\u09C7\u0995\u099F\u09BE \u09AC\u09BE\u09B8\u09C7 \u09B9\u09BE\u099C\u09BE\u09B0 \u09B9\u09BE\u099C\u09BE\u09B0 \u09AE\u09BE\u09A8\u09C1\u09B7 \u09AF\u09BE\u09A4\u09BE\u09AF\u09BC\u09BE\u09A4 \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u0964"},question:"What are virtual threads in Java 21? When should you use them and what are the pitfalls?",answer:"Virtual threads (final in Java 21) are lightweight threads managed by the JVM rather than the OS. Many of them are multiplexed onto a small pool of platform 'carrier' threads; when a virtual thread blocks on I/O, sleep or a lock, it is unmounted and its carrier runs another one, so you can have hundreds of thousands of them and keep writing simple blocking code. They suit I/O-bound, high-concurrency work such as servers that call databases and APIs; they do not make CPU-bound code faster. Pitfalls: do not pool them, limit access to scarce resources with a Semaphore instead, watch heavy ThreadLocal use, and in Java 21 a virtual thread that blocks inside a synchronized block pins its carrier, so prefer ReentrantLock around long blocking calls.",points:["Create: Thread.ofVirtual().start(r), Thread.startVirtualThread(r), Executors.newVirtualThreadPerTaskExecutor()","Cheap to create (small, growable stacks on the heap); one per task is fine","Best for blocking I/O-bound workloads (thread-per-request style)","No benefit for CPU-bound work - use platform threads / ForkJoinPool","Never pool virtual threads; use Semaphore to throttle","Pinning in Java 21: blocking inside synchronized or native code holds the carrier"],code:`import java.time.Duration;
import java.util.concurrent.*;
import java.util.stream.IntStream;

public class VirtualDemo {
    public static void main(String[] args) {
        long start = System.currentTimeMillis();
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            IntStream.range(0, 10_000).forEach(i ->
                executor.submit(() -> {
                    Thread.sleep(Duration.ofSeconds(1));   // simulated blocking I/O
                    return i;
                }));
        }   // close() waits for all tasks
        System.out.println("Took ~" + (System.currentTimeMillis() - start) + " ms"); // ~1000+ ms
    }
}`},{id:"jt-12",level:"mid",topic:"java-concurrency",difficulty:"medium",simple:{hi:"Producer-consumer ek jalebi ki dukaan jaisa hai. Halwai (producer) jalebi banake tray (queue) mein rakhta hai, aur waiter (consumer) tray se uthake customer ko deta hai. Tray bhari ho to halwai rukta hai, khaali ho to waiter rukta hai, aur dukaan band karne ke liye ek 'bas, aaj itna hi' wali parchi (poison pill) daal di jaati hai.",en:"Producer-consumer is like a jalebi shop. The halwai (producer) makes jalebis and puts them on a tray (queue), and the waiter (consumer) picks them up for customers. If the tray is full the halwai waits, if it is empty the waiter waits, and to close the shop a 'that's all for today' slip (poison pill) is placed on the tray.",bn:"Producer-consumer \u09B9\u09B2\u09CB \u099C\u09BF\u09B2\u09BF\u09AA\u09BF\u09B0 \u09A6\u09CB\u0995\u09BE\u09A8\u09C7\u09B0 \u09AE\u09A4\u09CB\u0964 \u09AE\u09AF\u09BC\u09B0\u09BE (producer) \u099C\u09BF\u09B2\u09BF\u09AA\u09BF \u09AC\u09BE\u09A8\u09BF\u09AF\u09BC\u09C7 \u099F\u09CD\u09B0\u09C7\u09A4\u09C7 (queue) \u09B0\u09BE\u0996\u09C7, \u0986\u09B0 \u0993\u09AF\u09BC\u09C7\u099F\u09BE\u09B0 (consumer) \u099F\u09CD\u09B0\u09C7 \u09A5\u09C7\u0995\u09C7 \u09A4\u09C1\u09B2\u09C7 \u0996\u09A6\u09CD\u09A6\u09C7\u09B0\u0995\u09C7 \u09A6\u09C7\u09AF\u09BC\u0964 \u099F\u09CD\u09B0\u09C7 \u09AD\u09B0\u09CD\u09A4\u09BF \u09B9\u09B2\u09C7 \u09AE\u09AF\u09BC\u09B0\u09BE \u09A5\u09BE\u09AE\u09C7, \u0996\u09BE\u09B2\u09BF \u09B9\u09B2\u09C7 \u0993\u09AF\u09BC\u09C7\u099F\u09BE\u09B0 \u09A5\u09BE\u09AE\u09C7, \u0986\u09B0 \u09A6\u09CB\u0995\u09BE\u09A8 \u09AC\u09A8\u09CD\u09A7 \u0995\u09B0\u09A4\u09C7 '\u0986\u099C \u098F\u0987\u099F\u09C1\u0995\u09C1\u0987' \u09B2\u09C7\u0996\u09BE \u098F\u0995\u099F\u09BE \u099A\u09BF\u09B0\u0995\u09C1\u099F (poison pill) \u09B0\u09BE\u0996\u09BE \u09B9\u09AF\u09BC\u0964"},question:"Implement the producer-consumer problem in Java.",answer:"The cleanest solution uses a BlockingQueue: put() blocks the producer when the bounded queue is full, and take() blocks the consumer when it is empty, so the queue handles all locking and signalling. To stop the consumer cleanly, the producer sends a special 'poison pill' value after the last item. The same can be built manually with synchronized plus wait()/notifyAll() in while loops, or with a ReentrantLock and two Conditions (notFull, notEmpty), but BlockingQueue is what you should use in production.",points:["ArrayBlockingQueue (bounded, array) or LinkedBlockingQueue (optionally bounded)","put/take block; offer/poll with timeout do not block forever","Bounded queue gives back-pressure so a fast producer cannot exhaust memory","Poison pill or interrupt to shut the consumer down","Restore the interrupt flag when catching InterruptedException","Manual version: synchronized + while(condition) wait() + notifyAll()"],code:`import java.util.concurrent.*;
public class ProducerConsumer {
    public static void main(String[] args) throws InterruptedException {
        BlockingQueue<Integer> queue = new ArrayBlockingQueue<>(5);
        int POISON = -1;
        Thread producer = new Thread(() -> {
            try {
                for (int i = 1; i <= 10; i++) queue.put(i);   // blocks when full
                queue.put(POISON);                            // signal end
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });
        Thread consumer = new Thread(() -> {
            try {
                while (true) {
                    int item = queue.take();                  // blocks when empty
                    if (item == POISON) break;
                    System.out.println("Consumed " + item);
                }
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });
        producer.start(); consumer.start();
        producer.join(); consumer.join();
    }
}`},{id:"jt-13",level:"senior",topic:"java-concurrency",difficulty:"hard",simple:{hi:"GC ek safai karmachari hai. G1 ghar ko kamron mein baant ke pehle sabse gande kamre saaf karta hai, thodi der ke liye sabko rokta hai. ZGC itni chupchaap safai karta hai ki ghar wale kaam karte rehte hain aur pata bhi nahi chalta. Lekin agar ghar mein koi roz kabaad jama kar raha hai (memory leak), to koi bhi safai wala kaam nahi aayega - pehle wo aadat sudhaaro.",en:"GC is a cleaner. G1 divides the house into rooms and cleans the dirtiest rooms first, asking everyone to pause briefly. ZGC cleans so quietly that the family keeps working without noticing. But if someone keeps piling up junk every day (memory leak), no cleaner can help - fix that habit first.",bn:"GC \u09B9\u09B2\u09CB \u098F\u0995\u099C\u09A8 \u09B8\u09BE\u09AB\u09BE\u0987\u0995\u09B0\u09CD\u09AE\u09C0\u0964 G1 \u09AC\u09BE\u09A1\u09BC\u09BF\u099F\u09BE\u0995\u09C7 \u0998\u09B0\u09C7 \u09AD\u09BE\u0997 \u0995\u09B0\u09C7 \u0986\u0997\u09C7 \u09B8\u09AC\u099A\u09C7\u09AF\u09BC\u09C7 \u09A8\u09CB\u0982\u09B0\u09BE \u0998\u09B0\u0997\u09C1\u09B2\u09CB \u09AA\u09B0\u09BF\u09B7\u09CD\u0995\u09BE\u09B0 \u0995\u09B0\u09C7, \u0985\u09B2\u09CD\u09AA \u09B8\u09AE\u09AF\u09BC\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u09B8\u09AC\u09BE\u0987\u0995\u09C7 \u09A5\u09BE\u09AE\u09BE\u09AF\u09BC\u0964 ZGC \u098F\u09A4 \u099A\u09C1\u09AA\u099A\u09BE\u09AA \u09AA\u09B0\u09BF\u09B7\u09CD\u0995\u09BE\u09B0 \u0995\u09B0\u09C7 \u09AF\u09C7 \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u09B2\u09CB\u0995 \u0995\u09BE\u099C \u0995\u09B0\u09A4\u09C7\u0987 \u09A5\u09BE\u0995\u09C7, \u099F\u09C7\u09B0\u0993 \u09AA\u09BE\u09AF\u09BC \u09A8\u09BE\u0964 \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0995\u09C7\u0989 \u09AF\u09A6\u09BF \u09B0\u09CB\u099C \u099C\u099E\u09CD\u099C\u09BE\u09B2 \u099C\u09AE\u09BE\u09AF\u09BC (memory leak), \u0995\u09CB\u09A8\u09CB \u09B8\u09BE\u09AB\u09BE\u0987\u0995\u09B0\u09CD\u09AE\u09C0\u0987 \u0995\u09BE\u099C\u09C7 \u0986\u09B8\u09AC\u09C7 \u09A8\u09BE - \u0986\u0997\u09C7 \u09B8\u09C7\u0987 \u0985\u09AD\u09CD\u09AF\u09BE\u09B8 \u09B8\u09BE\u09B0\u09BE\u0993\u0964"},question:"Compare G1 and ZGC. Your Java service shows long GC pauses and eventually OutOfMemoryError in production - how do you investigate and tune it?",answer:"G1 is the default collector: it splits the heap into regions, collects the regions with the most garbage first and aims for a pause-time goal (-XX:MaxGCPauseMillis, 200 ms by default), balancing throughput and latency. ZGC does almost all work concurrently with the application and keeps pauses typically under a millisecond regardless of heap size, at some CPU and memory cost; Java 21 added Generational ZGC (-XX:+UseZGC -XX:+ZGenerational). For long pauses and OOM, first gather evidence: enable GC logs (-Xlog:gc*), set -XX:+HeapDumpOnOutOfMemoryError, record with Java Flight Recorder, and check whether old-gen usage keeps growing after full GCs (a leak) or the heap is simply too small for the load. Fix leaks in code first (unbounded caches, static collections, unclosed resources, ThreadLocals), then right-size the heap and only then switch collectors or tune flags.",points:["Serial: small heaps; Parallel: max throughput; G1: default, balanced; ZGC: ultra-low latency, large heaps","G1 flags: -XX:+UseG1GC, -XX:MaxGCPauseMillis; ZGC: -XX:+UseZGC (+ -XX:+ZGenerational on 21)","Steady growth of old gen after full GC = memory leak; analyse heap dump with Eclipse MAT / VisualVM","Tools: -Xlog:gc*, jcmd GC.heap_info, jstat -gcutil, JFR + JDK Mission Control","Set -Xms equal to -Xmx in containers, or size via -XX:MaxRAMPercentage","Reduce allocation rate (object churn) - often the biggest win"],code:`# Run with G1 and diagnostics enabled
java -XX:+UseG1GC -Xms4g -Xmx4g -XX:MaxGCPauseMillis=200 \\
     -Xlog:gc*:file=gc.log:time,uptime,level,tags \\
     -XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=/tmp/dumps \\
     -jar app.jar

# Low-latency alternative on Java 21
java -XX:+UseZGC -XX:+ZGenerational -Xmx16g -jar app.jar

# Live investigation
jcmd <pid> GC.heap_info
jstat -gcutil <pid> 1000
jcmd <pid> JFR.start duration=60s filename=rec.jfr
jcmd <pid> GC.heap_dump /tmp/dumps/heap.hprof`},{id:"jt-14",level:"senior",topic:"java-concurrency",difficulty:"hard",simple:{hi:"Class loader ek school ka admission system hai. Naya bachcha aata hai to junior clerk pehle senior se poochta hai, senior principal se: 'kya ye pehle se register mein hai?' Upar wale ke paas mila to wahi use hota hai, warna neeche wala khud admission karta hai. Isse koi nakli 'String' naam ka bachcha asli ki jagah nahi le sakta.",en:"A class loader is like a school admission system. When a new child arrives, the junior clerk first asks the senior clerk, who asks the principal: 'is this child already registered?' If someone higher up has it, that record is used; otherwise the lower clerk does the admission. This way a fake child named 'String' can never replace the real one.",bn:"Class loader \u09B9\u09B2\u09CB \u09B8\u09CD\u0995\u09C1\u09B2\u09C7\u09B0 \u09AD\u09B0\u09CD\u09A4\u09BF \u09AC\u09CD\u09AF\u09AC\u09B8\u09CD\u09A5\u09BE\u09B0 \u09AE\u09A4\u09CB\u0964 \u09A8\u09A4\u09C1\u09A8 \u09AC\u09BE\u099A\u09CD\u099A\u09BE \u098F\u09B2\u09C7 \u099C\u09C1\u09A8\u09BF\u09AF\u09BC\u09B0 \u0995\u09C7\u09B0\u09BE\u09A8\u09BF \u0986\u0997\u09C7 \u09B8\u09BF\u09A8\u09BF\u09AF\u09BC\u09B0\u0995\u09C7 \u099C\u09BF\u099C\u09CD\u099E\u09C7\u09B8 \u0995\u09B0\u09C7\u09A8, \u09B8\u09BF\u09A8\u09BF\u09AF\u09BC\u09B0 \u09AA\u09CD\u09B0\u09A7\u09BE\u09A8 \u09B6\u09BF\u0995\u09CD\u09B7\u0995\u0995\u09C7: '\u098F \u0995\u09BF \u0986\u0997\u09C7 \u09A5\u09C7\u0995\u09C7\u0987 \u09B0\u09C7\u099C\u09BF\u09B8\u09CD\u099F\u09BE\u09B0\u09C7 \u0986\u099B\u09C7?' \u0993\u09AA\u09B0\u09C7\u09B0 \u0995\u09BE\u09B0\u09CB \u0995\u09BE\u099B\u09C7 \u09A5\u09BE\u0995\u09B2\u09C7 \u09B8\u09C7\u099F\u09BE\u0987 \u099A\u09B2\u09C7, \u09A8\u0987\u09B2\u09C7 \u09A8\u09BF\u099A\u09C7\u09B0 \u099C\u09A8 \u09A8\u09BF\u099C\u09C7 \u09AD\u09B0\u09CD\u09A4\u09BF \u0995\u09B0\u09C7\u09A8\u0964 \u09A4\u09BE\u0987 'String' \u09A8\u09BE\u09AE\u09C7\u09B0 \u0995\u09CB\u09A8\u09CB \u09A8\u0995\u09B2 \u09AC\u09BE\u099A\u09CD\u099A\u09BE \u0986\u09B8\u09B2\u099F\u09BE\u09B0 \u099C\u09BE\u09AF\u09BC\u0997\u09BE \u09A8\u09BF\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7 \u09A8\u09BE\u0964"},question:"How do class loaders work in Java? Explain the delegation model and when you would write a custom class loader.",answer:"Class loaders load .class bytecode into the JVM on demand. There are three built-in loaders: the Bootstrap loader (native, loads core java.base classes, shown as null), the Platform loader (other platform modules such as java.sql; it replaced the Extension loader in Java 9) and the Application (system) loader for the classpath/module path. They follow parent-first delegation: loadClass() asks the parent first and only calls its own findClass() if the parent cannot find the class, which stops user code from replacing core classes like java.lang.String. A class's identity is its name plus its defining loader, so the same class loaded by two loaders is two different types; custom loaders are used for plugin systems, hot reloading, isolation of app versions (application servers like Tomcat load webapp classes child-first) and loading encrypted or generated bytecode.",points:["Bootstrap -> Platform -> Application, parent-first delegation","Phases: loading, linking (verify, prepare, resolve), initialization","Custom loader: extend ClassLoader, override findClass(), call defineClass()","Same name + different loader = different class -> ClassCastException surprises","ClassNotFoundException (explicit load fails) vs NoClassDefFoundError (was present at compile time, missing/failed at runtime)","Leaked class loaders (e.g. on webapp redeploy) cause Metaspace OOM"],code:`public class LoaderDemo {
    public static void main(String[] args) {
        System.out.println(String.class.getClassLoader());          // null (bootstrap)
        System.out.println(java.sql.Connection.class.getClassLoader()); // ...PlatformClassLoader@...
        System.out.println(LoaderDemo.class.getClassLoader());      // ...AppClassLoader@...
    }
}

class PluginLoader extends ClassLoader {
    private final java.nio.file.Path dir;
    PluginLoader(java.nio.file.Path dir, ClassLoader parent) { super(parent); this.dir = dir; }

    @Override
    protected Class<?> findClass(String name) throws ClassNotFoundException {
        try {
            byte[] bytes = java.nio.file.Files.readAllBytes(dir.resolve(name.replace('.', '/') + ".class"));
            return defineClass(name, bytes, 0, bytes.length);
        } catch (java.io.IOException e) {
            throw new ClassNotFoundException(name, e);
        }
    }
}`},{id:"jv-1",level:"fresher",topic:"java-core",difficulty:"easy",simple:{hi:"JDK ek poora kitchen hai (gas, bartan, recipe \u2013 sab tools), JRE sirf khana garam karke khane ka setup hai, aur JVM wo microwave hai jo khana chalata hai. Java ka bytecode ek ready-to-eat packet jaisa hai \u2013 Mumbai ho ya Kolkata, jahan bhi JVM microwave hai, wahi packet chal jaata hai.",en:"The JDK is a full kitchen (stove, utensils, all tools), the JRE is just the setup to heat and eat food, and the JVM is the microwave that runs it. Java bytecode is like a ready-to-eat packet: whether in Mumbai or Kolkata, any place with a JVM microwave can run the same packet.",bn:"JDK \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE \u09AA\u09C1\u09B0\u09CB \u09B0\u09BE\u09A8\u09CD\u09A8\u09BE\u0998\u09B0 (\u0997\u09CD\u09AF\u09BE\u09B8, \u09AC\u09BE\u09B8\u09A8, \u09B8\u09AC tools), JRE \u09B9\u09B2\u09CB \u09B6\u09C1\u09A7\u09C1 \u0996\u09BE\u09AC\u09BE\u09B0 \u0997\u09B0\u09AE \u0995\u09B0\u09C7 \u0996\u09BE\u0993\u09AF\u09BC\u09BE\u09B0 \u09AC\u09CD\u09AF\u09AC\u09B8\u09CD\u09A5\u09BE, \u0986\u09B0 JVM \u09B9\u09B2\u09CB \u09B8\u09C7\u0987 microwave \u09AF\u09C7\u099F\u09BE \u0996\u09BE\u09AC\u09BE\u09B0\u099F\u09BE \u099A\u09BE\u09B2\u09BE\u09AF\u09BC\u0964 Java-\u09B0 bytecode \u098F\u0995\u099F\u09BE ready-to-eat \u09AA\u09CD\u09AF\u09BE\u0995\u09C7\u099F\u09C7\u09B0 \u09AE\u09A4\u09CB \u2013 \u09AE\u09C1\u09AE\u09CD\u09AC\u09BE\u0987 \u09B9\u09CB\u0995 \u09AC\u09BE \u0995\u09B2\u0995\u09BE\u09A4\u09BE, \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 JVM microwave \u0986\u099B\u09C7 \u09B8\u09C7\u0996\u09BE\u09A8\u09C7\u0987 \u098F\u0995\u0987 \u09AA\u09CD\u09AF\u09BE\u0995\u09C7\u099F \u099A\u09B2\u09C7\u0964"},question:"What is the difference between JDK, JRE and JVM? How is Java platform independent?",answer:'The JVM (Java Virtual Machine) loads and executes bytecode (.class files), using an interpreter plus a JIT compiler to turn it into native machine code. The JRE is the JVM plus the core class libraries needed to run programs, and the JDK is everything needed to develop: the runtime plus tools like javac, jar, jshell and jlink. Java is platform independent because javac compiles source to platform-neutral bytecode, and each OS/CPU has its own JVM that runs that same bytecode \u2014 "write once, run anywhere". Note that the JVM itself is platform specific; only the bytecode is portable.',points:["JVM = runs bytecode (class loader, bytecode verifier, interpreter + JIT, garbage collector)","JRE = JVM + standard libraries; JDK = JRE + development tools (javac, jar, javadoc, jshell, jlink)","Since Java 11 Oracle no longer ships a separate JRE; jlink can build a minimal custom runtime image","Bytecode is portable; the JVM is platform specific","JIT compiles hot code paths to native code, so Java is not purely interpreted"],code:`// Hello.java
public class Hello {
    public static void main(String[] args) {
        System.out.println("Runs on any OS with a JVM");
    }
}

// javac Hello.java   -> Hello.class (bytecode, same file for every OS)
// java Hello         -> the OS-specific JVM runs that bytecode`},{id:"jv-2",level:"fresher",topic:"java-core",difficulty:"easy",simple:{hi:"Ek school socho: Encapsulation matlab marks register principal ke cupboard mein locked hai, sirf office se milta hai. Abstraction matlab bell bajao aur class shuru \u2013 andar ka wiring nahi pata. Inheritance matlab chhota bhai bade bhai ki uniform pehenta hai, aur Polymorphism matlab ek hi 'Monitor' word \u2013 har class ka monitor alag tarike se kaam karta hai.",en:"Think of a school: Encapsulation means the marks register is locked in the principal's cupboard and you get it only through the office. Abstraction means you ring the bell and class starts, without knowing the wiring. Inheritance means the younger brother wears the elder brother's uniform, and Polymorphism means one word 'monitor', but each class's monitor does the job in their own way.",bn:"\u098F\u0995\u099F\u09BE \u09B8\u09CD\u0995\u09C1\u09B2 \u09AD\u09BE\u09AC\u09CB: Encapsulation \u09AE\u09BE\u09A8\u09C7 \u09A8\u09AE\u09CD\u09AC\u09B0\u09C7\u09B0 \u0996\u09BE\u09A4\u09BE \u09AA\u09CD\u09B0\u09BF\u09A8\u09CD\u09B8\u09BF\u09AA\u09BE\u09B2\u09C7\u09B0 \u0986\u09B2\u09AE\u09BE\u09B0\u09BF\u09A4\u09C7 \u09A4\u09BE\u09B2\u09BE\u09AC\u09A8\u09CD\u09A7, \u09B6\u09C1\u09A7\u09C1 \u0985\u09AB\u09BF\u09B8 \u09A5\u09C7\u0995\u09C7 \u09AA\u09BE\u0993\u09AF\u09BC\u09BE \u09AF\u09BE\u09AF\u09BC\u0964 Abstraction \u09AE\u09BE\u09A8\u09C7 \u0998\u09A3\u09CD\u099F\u09BE \u09AC\u09BE\u099C\u09BE\u09B2\u09C7\u0987 \u0995\u09CD\u09B2\u09BE\u09B8 \u09B6\u09C1\u09B0\u09C1, \u09AD\u09C7\u09A4\u09B0\u09C7\u09B0 \u09A4\u09BE\u09B0 \u0995\u09C7\u09AE\u09A8 \u099C\u09BE\u09A8\u09BE\u09B0 \u09A6\u09B0\u0995\u09BE\u09B0 \u09A8\u09C7\u0987\u0964 Inheritance \u09AE\u09BE\u09A8\u09C7 \u099B\u09CB\u099F \u09AD\u09BE\u0987 \u09AC\u09A1\u09BC \u09AD\u09BE\u0987\u09AF\u09BC\u09C7\u09B0 \u0987\u0989\u09A8\u09BF\u09AB\u09B0\u09CD\u09AE \u09AA\u09B0\u09C7, \u0986\u09B0 Polymorphism \u09AE\u09BE\u09A8\u09C7 \u098F\u0995\u0987 'monitor' \u09B6\u09AC\u09CD\u09A6, \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BE \u0995\u09CD\u09B2\u09BE\u09B8\u09C7\u09B0 monitor \u09A8\u09BF\u099C\u09C7\u09B0 \u09AE\u09A4\u09CB \u0995\u09B0\u09C7 \u0995\u09BE\u099C \u0995\u09B0\u09C7\u0964"},question:"Explain the four pillars of OOP in Java with examples.",answer:"The four pillars are encapsulation, abstraction, inheritance and polymorphism. Encapsulation hides an object's state behind private fields and exposes controlled access through methods; abstraction exposes only what an object does (via interfaces or abstract classes) and hides how it does it. Inheritance lets a class reuse and extend another class with `extends` (an is-a relationship), and polymorphism lets one reference type call different implementations \u2014 compile-time via overloading and runtime via overriding with dynamic dispatch.",points:["Encapsulation: private fields + public methods, validation inside setters/methods","Abstraction: interfaces / abstract classes define the contract, not the implementation","Inheritance: `extends` for classes (single inheritance), `implements` for multiple interfaces","Polymorphism: overloading (compile time) and overriding (runtime, dynamic dispatch)","Prefer composition over deep inheritance hierarchies"],code:`interface Shape { double area(); }                 // abstraction

class Circle implements Shape {
    private final double r;                       // encapsulation
    Circle(double r) { this.r = r; }
    public double area() { return Math.PI * r * r; }
}

class Square implements Shape {
    private final double side;
    Square(double side) { this.side = side; }
    public double area() { return side * side; }
}

public class Main {
    public static void main(String[] args) {
        Shape[] shapes = { new Circle(1), new Square(2) };
        for (Shape s : shapes) System.out.println(s.area()); // polymorphism
    }
}`},{id:"jv-3",level:"fresher",topic:"java-core",difficulty:"easy",simple:{hi:"Overloading ek chai-wale jaisa hai: 'chai do' bolo to plain chai, 'chai do, adrak ke saath' bolo to adrak chai \u2013 naam same, order ki details alag. Overriding matlab beta papa ki dukaan sambhalta hai par apne naye tareeke se kaam karta hai \u2013 kaam ka naam wahi, tareeka beta wala.",en:"Overloading is like a tea seller: say 'give tea' and you get plain tea, say 'give tea with ginger' and you get ginger tea \u2013 same name, different details. Overriding is when a son takes over his father's shop but does the same job in his own new way \u2013 same job name, the son's way of doing it.",bn:"Overloading \u09B9\u09B2\u09CB \u099A\u09BE-\u0993\u09AF\u09BC\u09BE\u09B2\u09BE\u09B0 \u09AE\u09A4\u09CB: '\u099A\u09BE \u09A6\u09BE\u0993' \u09AC\u09B2\u09B2\u09C7 \u09B8\u09BE\u09A7\u09BE\u09B0\u09A3 \u099A\u09BE, '\u0986\u09A6\u09BE \u09A6\u09BF\u09AF\u09BC\u09C7 \u099A\u09BE \u09A6\u09BE\u0993' \u09AC\u09B2\u09B2\u09C7 \u0986\u09A6\u09BE-\u099A\u09BE \u2013 \u09A8\u09BE\u09AE \u098F\u0995\u0987, details \u0986\u09B2\u09BE\u09A6\u09BE\u0964 Overriding \u09AE\u09BE\u09A8\u09C7 \u099B\u09C7\u09B2\u09C7 \u09AC\u09BE\u09AC\u09BE\u09B0 \u09A6\u09CB\u0995\u09BE\u09A8 \u099A\u09BE\u09B2\u09BE\u09AF\u09BC \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09A8\u09BF\u099C\u09C7\u09B0 \u09A8\u09A4\u09C1\u09A8 \u0989\u09AA\u09BE\u09AF\u09BC\u09C7 \u2013 \u0995\u09BE\u099C\u09C7\u09B0 \u09A8\u09BE\u09AE \u098F\u0995\u0987, \u09AA\u09A6\u09CD\u09A7\u09A4\u09BF \u099B\u09C7\u09B2\u09C7\u09B0\u0964"},question:"What is the difference between method overloading and method overriding?",answer:"Overloading means the same method name with a different parameter list (number, type or order) in the same class or subclass; the compiler picks the method at compile time based on the argument types. Overriding means a subclass provides its own implementation of an inherited instance method with the same signature; the JVM picks the method at runtime based on the actual object type. Return type alone cannot distinguish overloads, while an override may use a covariant (narrower) return type, cannot reduce visibility, and cannot throw broader checked exceptions.",points:["Overloading = compile-time (static) polymorphism; overriding = runtime (dynamic) polymorphism","Overloads must differ in parameter list; changing only the return type is a compile error","Override rules: same signature, covariant return allowed, same or wider access, no new/broader checked exceptions","static, private and final methods cannot be overridden (static methods are hidden, not overridden)","Use @Override so the compiler catches signature mistakes"],code:`class Calculator {
    int add(int a, int b) { return a + b; }            // overload 1
    double add(double a, double b) { return a + b; }   // overload 2
}

class Animal {
    String sound() { return "..."; }
}

class Dog extends Animal {
    @Override
    String sound() { return "Woof"; }                  // override
}

// Animal a = new Dog();
// a.sound();  -> "Woof" (decided at runtime by the object type)`},{id:"jv-4",level:"junior",topic:"java-core",difficulty:"medium",simple:{hi:"Interface ek job description jaisa hai \u2013 'driver ko gaadi chalani aani chahiye', bas rule likha hai, aur ek insaan kai job descriptions follow kar sakta hai. Abstract class ek half-ready ghar jaisa hai \u2013 deewar aur chhat (state aur code) bani hai, baaki kamre tumhe banane hain, aur tum sirf ek hi ghar le sakte ho. Default method interface mein diya hua ready-made tip hai jo sabko free milta hai.",en:"An interface is like a job description \u2013 'the driver must know how to drive' \u2013 just rules, and one person can follow many job descriptions. An abstract class is like a half-built house \u2013 walls and roof (state and code) are ready, you finish the rooms, and you can take only one house. A default method is a ready-made tip in the interface that everyone gets for free.",bn:"Interface \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE job description-\u098F\u09B0 \u09AE\u09A4\u09CB \u2013 '\u09A1\u09CD\u09B0\u09BE\u0987\u09AD\u09BE\u09B0\u0995\u09C7 \u0997\u09BE\u09A1\u09BC\u09BF \u099A\u09BE\u09B2\u09BE\u09A4\u09C7 \u099C\u09BE\u09A8\u09A4\u09C7 \u09B9\u09AC\u09C7', \u09B6\u09C1\u09A7\u09C1 \u09A8\u09BF\u09AF\u09BC\u09AE \u09B2\u09C7\u0996\u09BE, \u0986\u09B0 \u098F\u0995\u099C\u09A8 \u09AE\u09BE\u09A8\u09C1\u09B7 \u0985\u09A8\u09C7\u0995\u0997\u09C1\u09B2\u09CB job description \u09AE\u09BE\u09A8\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u0964 Abstract class \u09B9\u09B2\u09CB \u0986\u09A7\u09BE-\u09A4\u09C8\u09B0\u09BF \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u09AE\u09A4\u09CB \u2013 \u09A6\u09C7\u0993\u09AF\u09BC\u09BE\u09B2 \u0986\u09B0 \u099B\u09BE\u09A6 (state \u0986\u09B0 code) \u09A4\u09C8\u09B0\u09BF, \u09AC\u09BE\u0995\u09BF \u0998\u09B0 \u09A4\u09CB\u09AE\u09BE\u0995\u09C7 \u09AC\u09BE\u09A8\u09BE\u09A4\u09C7 \u09B9\u09AC\u09C7, \u0986\u09B0 \u09A4\u09C1\u09AE\u09BF \u09B6\u09C1\u09A7\u09C1 \u098F\u0995\u099F\u09BE\u0987 \u09AC\u09BE\u09A1\u09BC\u09BF \u09A8\u09BF\u09A4\u09C7 \u09AA\u09BE\u09B0\u09CB\u0964 Default method \u09B9\u09B2\u09CB interface-\u098F \u09A6\u09C7\u0993\u09AF\u09BC\u09BE ready-made \u099F\u09BF\u09AA\u09B8 \u09AF\u09BE \u09B8\u09AC\u09BE\u0987 free-\u09A4\u09C7 \u09AA\u09BE\u09AF\u09BC\u0964"},question:"What is the difference between an abstract class and an interface? How do default and static methods change this?",answer:"An abstract class can have constructors, instance fields with state, and methods of any access level; a class can extend only one abstract class. An interface defines a contract; its fields are implicitly public static final constants, and a class can implement many interfaces. Since Java 8 interfaces can have default methods (inherited implementation, useful for evolving APIs without breaking implementers) and static methods (utility methods called via the interface name), and private methods are also allowed for sharing code between defaults. Use an interface for a capability/contract and an abstract class when related classes share state and partial implementation.",points:["Abstract class: constructors, instance state, any access modifiers, single inheritance","Interface: no instance state, constants only, multiple implementation","default methods let you add behaviour to an interface without breaking existing implementers","static interface methods are not inherited; call them as `InterfaceName.method()`","Diamond conflict between two defaults must be resolved by overriding (can call `A.super.m()`)","Rule of thumb: interface for 'can-do', abstract class for 'is-a with shared code'"],code:`interface Payment {
    void pay(double amount);
    default void receipt() { System.out.println("Receipt printed"); }
    static Payment upi() { return amt -> System.out.println("UPI paid " + amt); }
}

abstract class Vehicle {
    protected final String number;               // state
    Vehicle(String number) { this.number = number; } // constructor
    abstract int wheels();
    void show() { System.out.println(number + " has " + wheels() + " wheels"); }
}

class Bike extends Vehicle {
    Bike(String n) { super(n); }
    int wheels() { return 2; }
}

// Payment p = Payment.upi(); p.pay(100); p.receipt();
// new Bike("WB-01").show();`},{id:"jv-5",level:"fresher",topic:"java-core",difficulty:"easy",simple:{hi:"String ek printed exam paper jaisa hai \u2013 ek baar chhap gaya to badal nahi sakte, naya chahiye to naya print karo. String pool school ki library jaisi hai: sab bachche same 'java' book maangte hain to library ek hi copy sabko dikhati hai, naya photocopy nahi banati.",en:"A String is like a printed exam paper \u2013 once printed you cannot change it; if you need a change, you print a new one. The String pool is like the school library: when every child asks for the same 'java' book, the library shows everyone the same single copy instead of making new photocopies.",bn:"String \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE \u099B\u09BE\u09AA\u09BE\u09A8\u09CB \u09AA\u09B0\u09C0\u0995\u09CD\u09B7\u09BE\u09B0 \u09AA\u09CD\u09B0\u09B6\u09CD\u09A8\u09AA\u09A4\u09CD\u09B0\u09C7\u09B0 \u09AE\u09A4\u09CB \u2013 \u098F\u0995\u09AC\u09BE\u09B0 \u099B\u09BE\u09AA\u09BE \u09B9\u09B2\u09C7 \u09AC\u09A6\u09B2\u09BE\u09A8\u09CB \u09AF\u09BE\u09AF\u09BC \u09A8\u09BE, \u09AC\u09A6\u09B2 \u099A\u09BE\u0987\u09B2\u09C7 \u09A8\u09A4\u09C1\u09A8 \u0995\u09B0\u09C7 \u099B\u09BE\u09AA\u09BE\u09A4\u09C7 \u09B9\u09AF\u09BC\u0964 String pool \u09B9\u09B2\u09CB \u09B8\u09CD\u0995\u09C1\u09B2\u09C7\u09B0 \u09B2\u09BE\u0987\u09AC\u09CD\u09B0\u09C7\u09B0\u09BF\u09B0 \u09AE\u09A4\u09CB: \u09B8\u09AC \u09AC\u09BE\u099A\u09CD\u099A\u09BE \u098F\u0995\u0987 'java' \u09AC\u0987 \u099A\u09BE\u0987\u09B2\u09C7 \u09B2\u09BE\u0987\u09AC\u09CD\u09B0\u09C7\u09B0\u09BF \u09B8\u09AC\u09BE\u0987\u0995\u09C7 \u098F\u0995\u099F\u09BE\u0987 \u0995\u09AA\u09BF \u09A6\u09C7\u0996\u09BE\u09AF\u09BC, \u09A8\u09A4\u09C1\u09A8 photocopy \u09AC\u09BE\u09A8\u09BE\u09AF\u09BC \u09A8\u09BE\u0964"},question:"Why is String immutable in Java, and what is the String pool? What does this code print?",answer:'Output: `true`, `false`, `true`, `true`. String literals are stored once in the String pool (part of the heap), so `a` and `b` point to the same object; `new String("java")` always creates a new heap object, so `a == c` is false, while `intern()` returns the pooled instance and `equals()` compares content. Strings are immutable (the class is final and its internal value is never modified) so that pooling is safe, hash codes can be cached (great for HashMap keys), they are thread safe, and security-sensitive values like file paths or class names cannot be changed after validation.',points:["Every 'modifying' method (concat, toUpperCase, replace) returns a new String","String pool lives in the heap (moved out of PermGen in Java 7)","Literals and compile-time constant expressions are pooled automatically; `new String()` is not","Immutability enables pooling, cached hashCode, thread safety and security","Always compare content with equals(), not =="],code:`String a = "java";
String b = "java";
String c = new String("java");

System.out.println(a == b);          // true  (same pooled object)
System.out.println(a == c);          // false (c is a new heap object)
System.out.println(a == c.intern()); // true  (intern returns pooled one)
System.out.println(a.equals(c));     // true  (same content)

String s = "hi";
s.concat(" there");
System.out.println(s);               // hi  (original unchanged)`},{id:"jv-6",level:"fresher",topic:"java-core",difficulty:"easy",simple:{hi:"String ek pen se likha hua certificate hai \u2013 galti sudhaarni ho to naya certificate. StringBuilder ek pencil wali rough copy hai \u2013 mitao, likho, jaldi kaam. StringBuffer bhi pencil copy hai par class teacher ke saamne \u2013 ek baar mein ek hi bachcha likh sakta hai, isliye safe par thoda slow.",en:"A String is a certificate written in pen \u2013 to fix a mistake you need a new certificate. A StringBuilder is a rough notebook in pencil \u2013 erase, write, quick work. A StringBuffer is also a pencil notebook but in front of the class teacher \u2013 only one child can write at a time, so it is safe but a bit slow.",bn:"String \u09B9\u09B2\u09CB \u09AA\u09C7\u09A8 \u09A6\u09BF\u09AF\u09BC\u09C7 \u09B2\u09C7\u0996\u09BE \u09B8\u09BE\u09B0\u09CD\u099F\u09BF\u09AB\u09BF\u0995\u09C7\u099F \u2013 \u09AD\u09C1\u09B2 \u09A0\u09BF\u0995 \u0995\u09B0\u09A4\u09C7 \u09A8\u09A4\u09C1\u09A8 \u09B8\u09BE\u09B0\u09CD\u099F\u09BF\u09AB\u09BF\u0995\u09C7\u099F \u09B2\u09BE\u0997\u09C7\u0964 StringBuilder \u09B9\u09B2\u09CB \u09AA\u09C7\u09A8\u09B8\u09BF\u09B2\u09C7\u09B0 rough \u0996\u09BE\u09A4\u09BE \u2013 \u09AE\u09CB\u099B\u09CB, \u09B2\u09C7\u0996\u09CB, \u09A4\u09BE\u09A1\u09BC\u09BE\u09A4\u09BE\u09A1\u09BC\u09BF \u0995\u09BE\u099C\u0964 StringBuffer-\u0993 \u09AA\u09C7\u09A8\u09B8\u09BF\u09B2\u09C7\u09B0 \u0996\u09BE\u09A4\u09BE \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 class teacher-\u098F\u09B0 \u09B8\u09BE\u09AE\u09A8\u09C7 \u2013 \u098F\u0995\u09AC\u09BE\u09B0\u09C7 \u098F\u0995\u099F\u09BE\u0987 \u09AC\u09BE\u099A\u09CD\u099A\u09BE \u09B2\u09BF\u0996\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7, \u09A4\u09BE\u0987 safe \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u098F\u0995\u099F\u09C1 \u09A7\u09C0\u09B0\u0964"},question:"What is the difference between String, StringBuilder and StringBuffer?",answer:"String is immutable, so every change creates a new object; it is ideal for values that do not change. StringBuilder is a mutable character buffer that is not synchronized, so it is the fastest choice for building strings in a single thread (for example inside loops). StringBuffer is also mutable but its methods are synchronized, making it thread safe but slower; it is a legacy class and rarely needed today.",points:["String: immutable, thread safe by design, pooled literals","StringBuilder: mutable, not synchronized, fastest \u2014 default choice for building strings","StringBuffer: mutable, synchronized methods, slower, mostly legacy","Concatenating with + inside a loop creates many temporary objects; use StringBuilder","Simple one-line `a + b + c` is fine \u2014 the compiler optimises it"],code:`// Bad: creates a new String on every iteration
String s = "";
for (int i = 0; i < 5; i++) s += i;

// Good: one mutable buffer
StringBuilder sb = new StringBuilder();
for (int i = 0; i < 5; i++) sb.append(i).append(',');
sb.setLength(sb.length() - 1);   // remove last comma
System.out.println(sb);          // 0,1,2,3,4
System.out.println(sb.reverse()); // 4,3,2,1,0

StringBuffer safe = new StringBuffer("thread-safe"); // synchronized methods`},{id:"jv-7",level:"fresher",topic:"java-core",difficulty:"easy",simple:{hi:"Do bachchon ke paas same Parle-G packet hai. '==' poochta hai 'kya ye bilkul wahi ek packet hai?' \u2013 jawab nahi. 'equals()' poochta hai 'kya andar same biscuit hai?' \u2013 jawab haan.",en:"Two children each have the same Parle-G packet. '==' asks 'is this the very same packet?' \u2013 the answer is no. 'equals()' asks 'are the same biscuits inside?' \u2013 the answer is yes.",bn:"\u09A6\u09C1\u099F\u09CB \u09AC\u09BE\u099A\u09CD\u099A\u09BE\u09B0 \u0995\u09BE\u099B\u09C7 \u098F\u0995\u0987 \u09B0\u0995\u09AE Parle-G \u09AA\u09CD\u09AF\u09BE\u0995\u09C7\u099F \u0986\u099B\u09C7\u0964 '==' \u099C\u09BF\u099C\u09CD\u099E\u09C7\u09B8 \u0995\u09B0\u09C7 '\u098F\u099F\u09BE \u0995\u09BF \u098F\u0995\u09A6\u09AE \u09B8\u09C7\u0987 \u098F\u0995\u0987 \u09AA\u09CD\u09AF\u09BE\u0995\u09C7\u099F?' \u2013 \u0989\u09A4\u09CD\u09A4\u09B0 \u09A8\u09BE\u0964 'equals()' \u099C\u09BF\u099C\u09CD\u099E\u09C7\u09B8 \u0995\u09B0\u09C7 '\u09AD\u09C7\u09A4\u09B0\u09C7 \u0995\u09BF \u098F\u0995\u0987 \u09AC\u09BF\u09B8\u09CD\u0995\u09C1\u099F?' \u2013 \u0989\u09A4\u09CD\u09A4\u09B0 \u09B9\u09CD\u09AF\u09BE\u0981\u0964"},question:"What is the difference between == and equals() in Java?",answer:"`==` compares primitive values directly, and for objects it compares references \u2014 whether both variables point to the same object in memory. `equals()` is a method meant to compare logical content; the default `Object.equals()` behaves like `==`, but classes such as String, Integer, records and most collections override it to compare values. For objects you almost always want `equals()` (or `Objects.equals(a, b)` to be null safe).",points:["== on primitives compares values; on objects compares references (identity)","equals() compares content only if the class overrides it","Object.equals() default implementation is `this == obj`","Use Objects.equals(a, b) to avoid NullPointerException","Comparing wrapper objects (Integer) with == is a common bug"],code:`String a = new String("cat");
String b = new String("cat");
System.out.println(a == b);            // false - different objects
System.out.println(a.equals(b));       // true  - same content

int x = 5, y = 5;
System.out.println(x == y);            // true  - primitive values

String n = null;
System.out.println(java.util.Objects.equals(n, "cat")); // false, no NPE`},{id:"jv-8",level:"mid",topic:"java-core",difficulty:"medium",simple:{hi:"hashCode railway station ka platform number hai aur equals() ticket checker ki asli jaanch hai. Agar do log same train ke same passenger hain par alag platform pe bheje gaye, to checker unhe kabhi milayega hi nahi \u2013 isliye equal objects ka platform (hashCode) bhi same hona chahiye.",en:"hashCode is the platform number at a railway station and equals() is the ticket checker's real check. If two tickets are for the same passenger on the same train but they are sent to different platforms, the checker will never match them \u2013 so equal objects must also get the same platform (hashCode).",bn:"hashCode \u09B9\u09B2\u09CB \u09B0\u09C7\u09B2 \u09B8\u09CD\u099F\u09C7\u09B6\u09A8\u09C7\u09B0 \u09AA\u09CD\u09B2\u09CD\u09AF\u09BE\u099F\u09AB\u09B0\u09CD\u09AE \u09A8\u09AE\u09CD\u09AC\u09B0 \u0986\u09B0 equals() \u09B9\u09B2\u09CB \u099F\u09BF\u0995\u09BF\u099F \u099A\u09C7\u0995\u09BE\u09B0\u09C7\u09B0 \u0986\u09B8\u09B2 \u09AF\u09BE\u099A\u09BE\u0987\u0964 \u09AF\u09A6\u09BF \u098F\u0995\u0987 \u09AF\u09BE\u09A4\u09CD\u09B0\u09C0\u09B0 \u098F\u0995\u0987 \u099F\u09CD\u09B0\u09C7\u09A8\u09C7\u09B0 \u09A6\u09C1\u099F\u09CB \u099F\u09BF\u0995\u09BF\u099F \u0986\u09B2\u09BE\u09A6\u09BE \u09AA\u09CD\u09B2\u09CD\u09AF\u09BE\u099F\u09AB\u09B0\u09CD\u09AE\u09C7 \u09AA\u09BE\u09A0\u09BE\u09A8\u09CB \u09B9\u09AF\u09BC, \u099A\u09C7\u0995\u09BE\u09B0 \u0995\u0996\u09A8\u09CB \u09AE\u09C7\u09B2\u09BE\u09A4\u09C7\u0987 \u09AA\u09BE\u09B0\u09AC\u09C7 \u09A8\u09BE \u2013 \u09A4\u09BE\u0987 equal objects-\u098F\u09B0 \u09AA\u09CD\u09B2\u09CD\u09AF\u09BE\u099F\u09AB\u09B0\u09CD\u09AE\u0993 (hashCode) \u098F\u0995\u0987 \u09B9\u09A4\u09C7 \u09B9\u09AC\u09C7\u0964"},question:"What is the equals() and hashCode() contract? What happens if you override only equals()?",answer:"The contract says: if two objects are equal according to `equals()`, they must return the same `hashCode()`; unequal objects may share a hash code (a collision), and both methods must be consistent while the fields used do not change. `equals()` itself must be reflexive, symmetric, transitive, consistent and return false for null. If you override only `equals()`, two equal objects will usually have different identity-based hash codes, so hash-based collections like HashSet and HashMap look in the wrong bucket \u2014 you get duplicates in a set and `get()` returning null for a logically equal key.",points:["Equal objects \u21D2 equal hash codes; equal hash codes do NOT imply equal objects","equals(): reflexive, symmetric, transitive, consistent, x.equals(null) == false","Always override both together and use the same fields in each","Use immutable fields for keys; mutating a key after insertion makes it unreachable","Records generate correct equals/hashCode automatically; IDEs/Objects.hash help otherwise"],code:`import java.util.*;

final class Emp {
    private final int id; private final String name;
    Emp(int id, String name) { this.id = id; this.name = name; }

    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Emp e)) return false;
        return id == e.id && Objects.equals(name, e.name);
    }
    @Override public int hashCode() { return Objects.hash(id, name); }
}

// Set<Emp> set = new HashSet<>();
// set.add(new Emp(1, "Ravi"));
// set.add(new Emp(1, "Ravi"));
// set.size() -> 1 (would be 2 if hashCode were not overridden)`},{id:"jv-9",level:"junior",topic:"java-core",difficulty:"easy",simple:{hi:"final ek pakka rule hai \u2013 jaise exam ka final answer, ek baar likha to badalna mana. finally school ke chhutti ke baad ki safai hai \u2013 class achhi gayi ya buri, jhaadu to lagega hi. finalize ek purana chowkidar tha jo kabhi bhi aata tha, kabhi nahi \u2013 isliye ab use hata rahe hain.",en:"final is a fixed rule \u2013 like your final answer in an exam, once written you cannot change it. finally is the cleaning after school \u2013 whether the day went well or badly, the room gets swept. finalize was an old watchman who came at random times or not at all \u2013 so it is being removed now.",bn:"final \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE \u09AA\u09BE\u0995\u09BE \u09A8\u09BF\u09AF\u09BC\u09AE \u2013 \u09AA\u09B0\u09C0\u0995\u09CD\u09B7\u09BE\u09B0 final answer-\u098F\u09B0 \u09AE\u09A4\u09CB, \u098F\u0995\u09AC\u09BE\u09B0 \u09B2\u09BF\u0996\u09B2\u09C7 \u09AC\u09A6\u09B2\u09BE\u09A8\u09CB \u09AF\u09BE\u09AC\u09C7 \u09A8\u09BE\u0964 finally \u09B9\u09B2\u09CB \u09B8\u09CD\u0995\u09C1\u09B2 \u099B\u09C1\u099F\u09BF\u09B0 \u09AA\u09B0\u09C7\u09B0 \u09B8\u09BE\u09AB\u09BE\u0987 \u2013 \u09A6\u09BF\u09A8 \u09AD\u09BE\u09B2\u09CB \u09AF\u09BE\u0995 \u09AC\u09BE \u0996\u09BE\u09B0\u09BE\u09AA, \u099D\u09BE\u0981\u099F \u09A4\u09CB \u09AA\u09A1\u09BC\u09AC\u09C7\u0987\u0964 finalize \u099B\u09BF\u09B2 \u098F\u0995 \u09AA\u09C1\u09B0\u09CB\u09A8\u09CB \u09A6\u09BE\u09B0\u09CB\u09AF\u09BC\u09BE\u09A8 \u09AF\u09C7 \u0995\u0996\u09A8\u09CB \u0986\u09B8\u09A4, \u0995\u0996\u09A8\u09CB \u0986\u09B8\u09A4 \u09A8\u09BE \u2013 \u09A4\u09BE\u0987 \u098F\u0996\u09A8 \u09A4\u09BE\u0995\u09C7 \u09B8\u09B0\u09BE\u09A8\u09CB \u09B9\u099A\u09CD\u099B\u09C7\u0964"},question:"What is the difference between final, finally and finalize?",answer:"`final` is a keyword: a final variable can be assigned only once, a final method cannot be overridden, and a final class cannot be extended. `finally` is a block after try/catch that runs whether or not an exception is thrown (except in cases like System.exit or the JVM crashing), and is used for cleanup. `finalize()` was an Object method called by the garbage collector before reclaiming an object; it was unpredictable and slow, is deprecated for removal, and should be replaced by try-with-resources or `java.lang.ref.Cleaner`.",points:["final variable: assigned once (a final reference can still point to a mutable object)","final method: no override; final class: no subclass (e.g. String)","finally runs after try/catch, even after return; avoid returning from finally","finalize(): deprecated for removal, no guarantee when or whether it runs","Use try-with-resources / AutoCloseable or Cleaner instead of finalize"],code:`final class Config {                 // cannot be extended
    final int maxUsers = 100;        // cannot be reassigned
    final void print() {}            // cannot be overridden
}

static int demo() {
    try {
        return 1;
    } finally {
        System.out.println("finally runs before the method returns");
    }
}

final java.util.List<String> list = new java.util.ArrayList<>();
list.add("ok");      // allowed: object is mutable
// list = new ArrayList<>(); // compile error: reference is final`},{id:"jv-10",level:"junior",topic:"java-core",difficulty:"easy",simple:{hi:"Class mein ek hi blackboard hota hai jo sab bachche share karte hain \u2013 wo static hai. Har bachche ki apni notebook alag hai \u2013 wo instance variable hai. Blackboard pe kuch likha to sabko dikhega.",en:"A classroom has one blackboard that all children share \u2013 that is static. Each child has their own notebook \u2013 that is an instance variable. If something is written on the blackboard, everyone sees it.",bn:"\u0995\u09CD\u09B2\u09BE\u09B8\u09C7 \u098F\u0995\u099F\u09BE\u0987 \u09AC\u09CD\u09B2\u09CD\u09AF\u09BE\u0995\u09AC\u09CB\u09B0\u09CD\u09A1 \u09A5\u09BE\u0995\u09C7 \u09AF\u09BE \u09B8\u09AC \u09AC\u09BE\u099A\u09CD\u099A\u09BE share \u0995\u09B0\u09C7 \u2013 \u09B8\u09C7\u099F\u09BE static\u0964 \u09AA\u09CD\u09B0\u09A4\u09CD\u09AF\u09C7\u0995 \u09AC\u09BE\u099A\u09CD\u099A\u09BE\u09B0 \u09A8\u09BF\u099C\u09C7\u09B0 \u0996\u09BE\u09A4\u09BE \u0986\u09B2\u09BE\u09A6\u09BE \u2013 \u09B8\u09C7\u099F\u09BE instance variable\u0964 \u09AC\u09CD\u09B2\u09CD\u09AF\u09BE\u0995\u09AC\u09CB\u09B0\u09CD\u09A1\u09C7 \u0995\u09BF\u099B\u09C1 \u09B2\u09BF\u0996\u09B2\u09C7 \u09B8\u09AC\u09BE\u0987 \u09A6\u09C7\u0996\u09A4\u09C7 \u09AA\u09BE\u09AF\u09BC\u0964"},question:"What does the static keyword mean in Java? Where can it be used?",answer:"`static` means the member belongs to the class rather than to any object, so there is one copy shared by all instances and it can be accessed using the class name. It can be applied to fields (shared state or constants with `static final`), methods (utility methods like `Math.max`), nested classes (a static nested class does not need an outer instance), static initializer blocks (run once when the class is initialised), and static imports. A static method cannot use `this` or access instance members directly, and static methods are hidden, not overridden.",points:["Static field: one copy per class, shared by all objects","Static method: called via ClassName.method(), no `this`, cannot directly use instance fields","Static block runs once when the class is initialised","Static nested class has no implicit reference to the outer object","Mutable static state is shared globally \u2014 a source of thread-safety bugs and hard-to-test code"],code:`class Student {
    static int count = 0;            // shared by all students
    static final String SCHOOL = "DPS"; // constant
    final String name;

    static { System.out.println("Class loaded once"); }

    Student(String name) { this.name = name; count++; }

    static int getCount() { return count; } // no access to name here
}

// new Student("Asha"); new Student("Ravi");
// Student.getCount() -> 2`},{id:"jv-11",level:"junior",topic:"java-core",difficulty:"easy",simple:{hi:"Ghar socho: private tumhari diary hai \u2013 sirf tum padh sakte ho. Default ghar ka fridge hai \u2013 ghar ke sab log use kar sakte hain. Protected family ki property hai \u2013 ghar wale aur bachche (chahe doosre shehar mein rehte hon). Public ghar ke bahar ka nal hai \u2013 koi bhi pani le sakta hai.",en:"Think of a home: private is your diary \u2013 only you can read it. Default is the home fridge \u2013 everyone in the house can use it. Protected is family property \u2013 family members and the children (even if they live in another city). Public is the tap outside the house \u2013 anyone can take water.",bn:"\u098F\u0995\u099F\u09BE \u09AC\u09BE\u09A1\u09BC\u09BF \u09AD\u09BE\u09AC\u09CB: private \u09B9\u09B2\u09CB \u09A4\u09CB\u09AE\u09BE\u09B0 \u09A1\u09BE\u09AF\u09BC\u09C7\u09B0\u09BF \u2013 \u09B6\u09C1\u09A7\u09C1 \u09A4\u09C1\u09AE\u09BF \u09AA\u09A1\u09BC\u09A4\u09C7 \u09AA\u09BE\u09B0\u09CB\u0964 Default \u09B9\u09B2\u09CB \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u09AB\u09CD\u09B0\u09BF\u099C \u2013 \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u09B8\u09AC\u09BE\u0987 \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u0964 Protected \u09B9\u09B2\u09CB \u09AA\u09B0\u09BF\u09AC\u09BE\u09B0\u09C7\u09B0 \u09B8\u09AE\u09CD\u09AA\u09A4\u09CD\u09A4\u09BF \u2013 \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u09B2\u09CB\u0995 \u0986\u09B0 \u099B\u09C7\u09B2\u09C7\u09AE\u09C7\u09AF\u09BC\u09C7\u09B0\u09BE (\u0985\u09A8\u09CD\u09AF \u09B6\u09B9\u09B0\u09C7 \u09A5\u09BE\u0995\u09B2\u09C7\u0993)\u0964 Public \u09B9\u09B2\u09CB \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u09AC\u09BE\u0987\u09B0\u09C7\u09B0 \u0995\u09B2 \u2013 \u09AF\u09C7 \u0995\u09C7\u0989 \u099C\u09B2 \u09A8\u09BF\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u0964"},question:"Explain the access modifiers in Java.",answer:"Java has four access levels. `private` is visible only inside the same class; default (package-private, no keyword) is visible inside the same package; `protected` is visible in the same package and in subclasses in other packages (through inheritance); and `public` is visible everywhere. Top-level classes can only be public or package-private. Use the most restrictive level that works \u2014 private fields with controlled public methods is the standard encapsulation practice; with the module system, even public types are only accessible outside a module if their package is exported.",points:["private < default (package-private) < protected < public","Top-level classes: only public or package-private","protected = package + subclasses (even in other packages)","Overriding cannot reduce visibility (a public method stays public)","Modules (module-info.java) add another layer: packages must be exported"],code:`package com.shop;

public class Account {
    private double balance;          // only this class
    String branch;                   // package-private: com.shop only
    protected String type;           // package + subclasses
    public String ownerName;         // everyone

    public double getBalance() { return balance; }
    public void deposit(double amt) {
        if (amt <= 0) throw new IllegalArgumentException("Invalid amount");
        balance += amt;
    }
}`},{id:"jv-12",level:"junior",topic:"java-core",difficulty:"medium",simple:{hi:"Checked exception train journey ke pehle ki warning hai \u2013 'ticket confirm hai ya nahi, check karo', bina check kiye guard aage nahi badhne deta. Unchecked exception raste mein paani ki bottle gir jaane jaisa hai \u2013 tumhari laaparwahi, koi pehle se check nahi karta.",en:"A checked exception is like the warning before a train journey \u2013 'check whether your ticket is confirmed' \u2013 the guard won't let you go ahead without checking. An unchecked exception is like dropping your water bottle on the way \u2013 your own carelessness, and nobody checks for it beforehand.",bn:"Checked exception \u09B9\u09B2\u09CB \u099F\u09CD\u09B0\u09C7\u09A8 \u09AF\u09BE\u09A4\u09CD\u09B0\u09BE\u09B0 \u0986\u0997\u09C7\u09B0 \u09B8\u09A4\u09B0\u09CD\u0995\u09AC\u09BE\u09B0\u09CD\u09A4\u09BE \u2013 '\u099F\u09BF\u0995\u09BF\u099F confirm \u0995\u09BF\u09A8\u09BE \u09A6\u09C7\u0996\u09CB', \u09A8\u09BE \u09A6\u09C7\u0996\u09B2\u09C7 \u0997\u09BE\u09B0\u09CD\u09A1 \u098F\u0997\u09CB\u09A4\u09C7 \u09A6\u09C7\u09AF\u09BC \u09A8\u09BE\u0964 Unchecked exception \u09B9\u09B2\u09CB \u09AA\u09A5\u09C7 \u099C\u09B2\u09C7\u09B0 \u09AC\u09CB\u09A4\u09B2 \u09AA\u09A1\u09BC\u09C7 \u09AF\u09BE\u0993\u09AF\u09BC\u09BE\u09B0 \u09AE\u09A4\u09CB \u2013 \u09A8\u09BF\u099C\u09C7\u09B0 \u0985\u09B8\u09BE\u09AC\u09A7\u09BE\u09A8\u09A4\u09BE, \u0995\u09C7\u0989 \u0986\u0997\u09C7 \u09A5\u09C7\u0995\u09C7 \u099A\u09C7\u0995 \u0995\u09B0\u09C7 \u09A8\u09BE\u0964"},question:"What is the difference between checked and unchecked exceptions?",answer:"Checked exceptions are subclasses of Exception (but not RuntimeException), such as IOException or SQLException; the compiler forces you to either catch them or declare them with `throws`. Unchecked exceptions are RuntimeException and its subclasses (NullPointerException, IllegalArgumentException, ArithmeticException) plus Errors; the compiler does not force handling. Checked exceptions are meant for recoverable conditions outside the program's control, while unchecked ones usually signal programming bugs. Errors like OutOfMemoryError indicate serious JVM problems that applications normally should not catch.",points:["Throwable \u2192 Exception (checked) and Error; RuntimeException is the unchecked branch of Exception","Checked: compile-time enforced handle-or-declare rule","Unchecked: RuntimeException subclasses + Error, no compile-time enforcement","Do not catch generic Exception/Throwable and silently swallow it","Many modern APIs and frameworks prefer unchecked exceptions; wrap checked ones with a cause"],code:`import java.io.*;
import java.nio.file.*;

class Demo {
    // checked: must be declared or caught
    static String read(String path) throws IOException {
        return Files.readString(Path.of(path));
    }

    static int divide(int a, int b) {
        return a / b;            // unchecked ArithmeticException if b == 0
    }

    public static void main(String[] args) {
        try {
            System.out.println(read("data.txt"));
        } catch (IOException e) {
            System.out.println("File problem: " + e.getMessage());
        }
    }
}`},{id:"jv-13",level:"mid",topic:"java-core",difficulty:"medium",simple:{hi:"try-with-resources library ka automatic system hai: tum book lekar padhte ho, aur jaise hi tum reading room se bahar nikalte ho \u2013 chahe padhai poori hui ya beech mein bell baj gayi \u2013 book apne aap wapas shelf pe chali jaati hai. Bhoolne ka chance hi nahi.",en:"try-with-resources is like a library's automatic system: you take a book and read, and the moment you leave the reading room \u2013 whether you finished or the bell rang in between \u2013 the book goes back to the shelf by itself. There is no chance of forgetting.",bn:"try-with-resources \u09B9\u09B2\u09CB \u09B2\u09BE\u0987\u09AC\u09CD\u09B0\u09C7\u09B0\u09BF\u09B0 automatic \u09AC\u09CD\u09AF\u09AC\u09B8\u09CD\u09A5\u09BE\u09B0 \u09AE\u09A4\u09CB: \u09A4\u09C1\u09AE\u09BF \u09AC\u0987 \u09A8\u09BF\u09AF\u09BC\u09C7 \u09AA\u09A1\u09BC\u09CB, \u0986\u09B0 \u09B0\u09BF\u09A1\u09BF\u0982 \u09B0\u09C1\u09AE \u09A5\u09C7\u0995\u09C7 \u09AC\u09C7\u09B0\u09CB\u09A8\u09CB\u09B0 \u09B8\u0999\u09CD\u0997\u09C7 \u09B8\u0999\u09CD\u0997\u09C7 \u2013 \u09AA\u09A1\u09BC\u09BE \u09B6\u09C7\u09B7 \u09B9\u09CB\u0995 \u09AC\u09BE \u09AE\u09BE\u099D\u0996\u09BE\u09A8\u09C7 \u0998\u09A3\u09CD\u099F\u09BE \u09AC\u09BE\u099C\u09C1\u0995 \u2013 \u09AC\u0987 \u09A8\u09BF\u099C\u09C7 \u09A5\u09C7\u0995\u09C7\u0987 \u09A4\u09BE\u0995\u09C7 \u09AB\u09BF\u09B0\u09C7 \u09AF\u09BE\u09AF\u09BC\u0964 \u09AD\u09C1\u09B2\u09C7 \u09AF\u09BE\u0993\u09AF\u09BC\u09BE\u09B0 \u0995\u09CB\u09A8\u09CB \u09B8\u09C1\u09AF\u09CB\u0997 \u09A8\u09C7\u0987\u0964"},question:"What is try-with-resources and why is it better than closing resources in finally?",answer:"try-with-resources declares one or more resources that implement AutoCloseable in the try header, and Java automatically calls `close()` on them when the block exits, normally or with an exception, in reverse order of declaration. It is better than a manual finally block because it is shorter, cannot forget to close, handles null resources, and keeps the original exception: if `close()` also throws, that exception is attached as a suppressed exception (retrievable with `getSuppressed()`) instead of hiding the real error. Since Java 9 you can also use an existing effectively final variable in the header.",points:["Works with any AutoCloseable (streams, readers, JDBC Connection/Statement/ResultSet)","Resources are closed in reverse order of declaration","Close exceptions become suppressed exceptions; the primary exception is preserved","catch and finally blocks run after the resources are closed","Java 9+: `try (existingResource) { ... }` if the variable is effectively final"],code:`class Res implements AutoCloseable {
    private final String name;
    Res(String name) { this.name = name; System.out.println("open " + name); }
    @Override public void close() { System.out.println("close " + name); }
}

public class Main {
    public static void main(String[] args) {
        try (Res a = new Res("A"); Res b = new Res("B")) {
            System.out.println("work");
            throw new IllegalStateException("boom");
        } catch (IllegalStateException e) {
            System.out.println("caught " + e.getMessage());
        }
    }
}
// open A, open B, work, close B, close A, caught boom`},{id:"jv-14",level:"mid",topic:"java-core",difficulty:"medium",simple:{hi:"Custom exception apni dukaan ka khaas board jaisa hai. Sirf 'Error' likhne ki jagah tum likhte ho 'Udhaar band hai, 300 rupaye kam hain' \u2013 sunte hi customer ko samajh aa jaata hai kya galat hua.",en:"A custom exception is like a special notice board in your own shop. Instead of just writing 'Error', you write 'No credit, you are short by 300 rupees' \u2013 the customer understands right away what went wrong.",bn:"Custom exception \u09B9\u09B2\u09CB \u09A8\u09BF\u099C\u09C7\u09B0 \u09A6\u09CB\u0995\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u09B6\u09C7\u09B7 \u09A8\u09CB\u099F\u09BF\u09B6 \u09AC\u09CB\u09B0\u09CD\u09A1\u09C7\u09B0 \u09AE\u09A4\u09CB\u0964 \u09B6\u09C1\u09A7\u09C1 'Error' \u09B2\u09C7\u0996\u09BE\u09B0 \u09AC\u09A6\u09B2\u09C7 \u09A4\u09C1\u09AE\u09BF \u09B2\u09C7\u0996\u09CB '\u09A7\u09BE\u09B0 \u09AC\u09A8\u09CD\u09A7, \u09E9\u09E6\u09E6 \u099F\u09BE\u0995\u09BE \u0995\u09AE \u0986\u099B\u09C7' \u2013 \u09B6\u09C1\u09A8\u09C7\u0987 \u0996\u09A6\u09CD\u09A6\u09C7\u09B0 \u09AC\u09C1\u099D\u09C7 \u09AF\u09BE\u09AF\u09BC \u0995\u09C0 \u09AD\u09C1\u09B2 \u09B9\u09AF\u09BC\u09C7\u099B\u09C7\u0964"},question:"How do you create a custom exception in Java? Write an example and explain best practices.",answer:"Create a class that extends Exception for a checked exception or RuntimeException for an unchecked one, and provide constructors that take a message and an optional cause so the original stack trace is preserved when wrapping. Give it a meaningful domain name (InsufficientBalanceException), optionally extra fields like an error code, and throw it where the business rule is violated. Most modern code prefers unchecked custom exceptions for business errors, mapped to responses at a single central handler.",points:["Extend Exception (checked) or RuntimeException (unchecked)","Provide (message) and (message, cause) constructors; always pass the cause when wrapping","Use domain-specific names and add useful fields (error code, amount, id)","Do not use exceptions for normal control flow","Do not swallow exceptions; log once at the boundary, not at every layer"],code:`class InsufficientBalanceException extends RuntimeException {
    private final double shortBy;

    InsufficientBalanceException(double shortBy) {
        super("Insufficient balance, short by " + shortBy);
        this.shortBy = shortBy;
    }
    InsufficientBalanceException(String msg, Throwable cause) {
        super(msg, cause);
        this.shortBy = 0;
    }
    double getShortBy() { return shortBy; }
}

class Wallet {
    private double balance = 500;
    void pay(double amount) {
        if (amount > balance)
            throw new InsufficientBalanceException(amount - balance);
        balance -= amount;
    }
}
// new Wallet().pay(800); -> InsufficientBalanceException: ... short by 300.0`},{id:"jv-15",level:"senior",topic:"java-core",difficulty:"hard",simple:{hi:"Generics ek label laga hua tiffin dabba hai \u2013 'sirf roti'. Compiler ek strict mummy hai jo packing ke time check karti hai ki dabbe mein sirf roti hi jaaye. Par school pahunchte hi label nikal jaata hai (type erasure) \u2013 andar dekhne waale ko bas 'dabba' dikhta hai, isliye checking pehle hi ho jaani chahiye.",en:"Generics are like a tiffin box with a label \u2013 'only roti'. The compiler is a strict mother who checks at packing time that only roti goes in. But when the box reaches school the label falls off (type erasure) \u2013 anyone looking sees just 'a box', so all checking must happen beforehand.",bn:"Generics \u09B9\u09B2\u09CB \u09B2\u09C7\u09AC\u09C7\u09B2 \u09B2\u09BE\u0997\u09BE\u09A8\u09CB \u099F\u09BF\u09AB\u09BF\u09A8 \u09AC\u09BE\u0995\u09CD\u09B8 \u2013 '\u09B6\u09C1\u09A7\u09C1 \u09B0\u09C1\u099F\u09BF'\u0964 Compiler \u09B9\u09B2\u09CB \u0995\u09A1\u09BC\u09BE \u09AE\u09BE, \u09AF\u09C7 \u09AA\u09CD\u09AF\u09BE\u0995 \u0995\u09B0\u09BE\u09B0 \u09B8\u09AE\u09AF\u09BC\u0987 \u09A6\u09C7\u0996\u09C7 \u09A8\u09C7\u09AF\u09BC \u09AC\u09BE\u0995\u09CD\u09B8\u09C7 \u09B6\u09C1\u09A7\u09C1 \u09B0\u09C1\u099F\u09BF\u0987 \u09AF\u09BE\u099A\u09CD\u099B\u09C7\u0964 \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09B8\u09CD\u0995\u09C1\u09B2\u09C7 \u09AA\u09CC\u0981\u099B\u09C7 \u09B2\u09C7\u09AC\u09C7\u09B2\u099F\u09BE \u0996\u09C1\u09B2\u09C7 \u09AF\u09BE\u09AF\u09BC (type erasure) \u2013 \u09AF\u09C7 \u09A6\u09C7\u0996\u09C7 \u09B8\u09C7 \u09B6\u09C1\u09A7\u09C1 '\u098F\u0995\u099F\u09BE \u09AC\u09BE\u0995\u09CD\u09B8' \u09A6\u09C7\u0996\u09C7, \u09A4\u09BE\u0987 \u09B8\u09AC \u099A\u09C7\u0995\u09BF\u0982 \u0986\u0997\u09C7\u0987 \u09B9\u09AF\u09BC\u09C7 \u09AF\u09C7\u09A4\u09C7 \u09B9\u09AF\u09BC\u0964"},question:"What are generics and what is type erasure? What limitations does erasure cause?",answer:"Generics let classes and methods be parameterised by type (List<String>, Optional<T>), giving compile-time type safety and removing explicit casts. Java implements them with type erasure: the compiler checks types and inserts casts, then erases type parameters to their bounds (Object or the upper bound) in the bytecode, so `List<String>` and `List<Integer>` are the same class at runtime. Because of erasure you cannot do `new T()`, `new T[]`, `instanceof List<String>`, use primitives as type arguments, or overload methods that differ only in generic parameters; the compiler also generates bridge methods to keep overriding working. Wildcards follow PECS: `? extends T` for producers you read from, `? super T` for consumers you write into.",points:["Compile-time safety, no casts, reusable algorithms","Erasure: type parameters replaced by bound; generic info mostly not available at runtime","Not allowed: new T(), new T[n], instanceof List<String>, List<int>, static field of type T","Erasure keeps backward compatibility with pre-generics bytecode","PECS: Producer extends, Consumer super (e.g. Collections.copy)","Workaround for runtime type: pass a Class<T> token"],code:`import java.util.*;

class Box<T extends Comparable<T>> {
    private final T value;
    Box(T value) { this.value = value; }
    boolean isBigger(Box<T> other) { return value.compareTo(other.value) > 0; }
}

public class Main {
    static double sum(List<? extends Number> nums) {   // producer -> extends
        double s = 0;
        for (Number n : nums) s += n.doubleValue();
        return s;
    }
    static void fill(List<? super Integer> out) { out.add(42); } // consumer -> super

    public static void main(String[] args) {
        List<String> a = new ArrayList<>();
        List<Integer> b = new ArrayList<>();
        System.out.println(a.getClass() == b.getClass()); // true (erasure)
        System.out.println(sum(List.of(1, 2.5)));          // 3.5
        System.out.println(new Box<>(5).isBigger(new Box<>(3))); // true
    }
}`},{id:"jv-16",level:"junior",topic:"java-core",difficulty:"medium",simple:{hi:"Wrapper class ek gift box jaisa hai jismein ek chocolate (primitive) rakhi hai. Dukaandaar 127 tak ke chhote boxes pehle se bana ke rakhta hai, isliye sabko wahi same box milta hai; 128 ka box har baar naya banta hai. Aur khaali box (null) khologe to chocolate nahi, takleef milegi \u2013 NullPointerException!",en:"A wrapper class is like a gift box holding a chocolate (the primitive). The shopkeeper keeps ready-made boxes up to 127, so everyone gets the same box; a box for 128 is made new each time. And if you open an empty box (null), you get trouble, not chocolate \u2013 NullPointerException!",bn:"Wrapper class \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE gift box, \u09AF\u09BE\u09B0 \u09AD\u09C7\u09A4\u09B0\u09C7 \u098F\u0995\u099F\u09BE \u099A\u0995\u09CB\u09B2\u09C7\u099F (primitive) \u09B0\u09BE\u0996\u09BE\u0964 \u09A6\u09CB\u0995\u09BE\u09A8\u09A6\u09BE\u09B0 \u09E7\u09E8\u09ED \u09AA\u09B0\u09CD\u09AF\u09A8\u09CD\u09A4 \u099B\u09CB\u099F \u09AC\u09BE\u0995\u09CD\u09B8 \u0986\u0997\u09C7 \u09A5\u09C7\u0995\u09C7 \u09AC\u09BE\u09A8\u09BF\u09AF\u09BC\u09C7 \u09B0\u09BE\u0996\u09C7, \u09A4\u09BE\u0987 \u09B8\u09AC\u09BE\u0987 \u098F\u0995\u0987 \u09AC\u09BE\u0995\u09CD\u09B8 \u09AA\u09BE\u09AF\u09BC; \u09E7\u09E8\u09EE-\u098F\u09B0 \u09AC\u09BE\u0995\u09CD\u09B8 \u09AA\u09CD\u09B0\u09A4\u09BF\u09AC\u09BE\u09B0 \u09A8\u09A4\u09C1\u09A8 \u09AC\u09BE\u09A8\u09BE\u09A8\u09CB \u09B9\u09AF\u09BC\u0964 \u0986\u09B0 \u0996\u09BE\u09B2\u09BF \u09AC\u09BE\u0995\u09CD\u09B8 (null) \u0996\u09C1\u09B2\u09B2\u09C7 \u099A\u0995\u09CB\u09B2\u09C7\u099F \u09A8\u09AF\u09BC, \u099D\u09BE\u09AE\u09C7\u09B2\u09BE \u09AA\u09BE\u09AC\u09C7 \u2013 NullPointerException!"},question:"What are wrapper classes and autoboxing? What are the common pitfalls? (What does this code print?)",answer:"Output: `true`, `false`, `true`, then a NullPointerException. Wrapper classes (Integer, Long, Double, Boolean\u2026) wrap primitives as objects so they can be used in collections and generics; autoboxing converts primitive \u2192 wrapper and unboxing does the reverse automatically. `Integer.valueOf` caches values from -128 to 127, so `==` on two boxed 127s compares the same cached object but two boxed 128s are different objects; unboxing a null wrapper throws NullPointerException. Other pitfalls are hidden object creation in hot loops and `List.remove(int)` vs `remove(Object)` overload confusion.",points:["Autoboxing: int \u2192 Integer; unboxing: Integer \u2192 int (compiler inserts valueOf / intValue)","Integer cache -128..127 (upper bound configurable); never compare wrappers with ==","Unboxing null \u2192 NullPointerException (e.g. Map.get returning null into an int)","Boxing in tight loops creates garbage; prefer primitives / primitive streams","list.remove(1) removes index 1, list.remove(Integer.valueOf(1)) removes the value"],code:`Integer a = 127, b = 127;
Integer c = 128, d = 128;
System.out.println(a == b);      // true  (cached objects)
System.out.println(c == d);      // false (different objects)
System.out.println(c.equals(d)); // true  (compare values)

java.util.Map<String, Integer> stock = new java.util.HashMap<>();
int qty = stock.get("pen");      // NullPointerException: unboxing null`},{id:"jv-17",level:"mid",topic:"java-core",difficulty:"medium",simple:{hi:"Record ek railway ticket jaisa hai \u2013 naam, train number, seat sab ek baar print ho gaya, badal nahi sakte. Java tumhare liye ticket ka poora format khud bana deta hai, tumhe har line haath se nahi likhni padti.",en:"A record is like a railway ticket \u2013 name, train number and seat are printed once and cannot be changed. Java creates the whole ticket format for you, so you don't have to write every line by hand.",bn:"Record \u09B9\u09B2\u09CB \u09B0\u09C7\u09B2\u09C7\u09B0 \u099F\u09BF\u0995\u09BF\u099F\u09C7\u09B0 \u09AE\u09A4\u09CB \u2013 \u09A8\u09BE\u09AE, \u099F\u09CD\u09B0\u09C7\u09A8 \u09A8\u09AE\u09CD\u09AC\u09B0, \u09B8\u09BF\u099F \u09B8\u09AC \u098F\u0995\u09AC\u09BE\u09B0 \u099B\u09BE\u09AA\u09BE \u09B9\u09AF\u09BC\u09C7 \u0997\u09C7\u099B\u09C7, \u09AC\u09A6\u09B2\u09BE\u09A8\u09CB \u09AF\u09BE\u09AF\u09BC \u09A8\u09BE\u0964 Java \u09A4\u09CB\u09AE\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u099F\u09BF\u0995\u09BF\u099F\u09C7\u09B0 \u09AA\u09C1\u09B0\u09CB format \u09A8\u09BF\u099C\u09C7\u0987 \u09AC\u09BE\u09A8\u09BF\u09AF\u09BC\u09C7 \u09A6\u09C7\u09AF\u09BC, \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BE \u09B2\u09BE\u0987\u09A8 \u09B9\u09BE\u09A4\u09C7 \u09B2\u09BF\u0996\u09A4\u09C7 \u09B9\u09AF\u09BC \u09A8\u09BE\u0964"},question:"What are records in Java? When would you use them instead of a normal class?",answer:"A record is a concise, transparent carrier for immutable data: `record Point(int x, int y) {}` automatically gets private final fields, a canonical constructor, accessor methods `x()` and `y()`, and `equals()`, `hashCode()` and `toString()` based on all components. Records are implicitly final, cannot extend another class (they extend java.lang.Record) but can implement interfaces, and can have static fields, extra methods and a compact constructor for validation. Use them for DTOs, API request/response objects, value objects, map keys and multiple return values; avoid them when you need mutable state, inheritance, or JPA entities that require a no-arg constructor and setters.",points:["Auto-generated: private final fields, canonical constructor, accessors, equals/hashCode/toString","Implicitly final, shallowly immutable (a List component can still be mutated \u2013 copy it)","Compact constructor for validation/normalisation","Can implement interfaces, have static members and methods; no instance fields beyond components","Great for DTOs and value objects; not suitable for JPA entities","Work with record patterns in switch/instanceof deconstruction"],code:`import java.util.List;

record Order(String id, double amount, List<String> items) {
    Order {                                   // compact constructor
        if (amount < 0) throw new IllegalArgumentException("amount < 0");
        items = List.copyOf(items);           // defensive, unmodifiable copy
    }
    boolean isLarge() { return amount > 10_000; }
}

// var o = new Order("A1", 15000, List.of("TV"));
// o.amount()   -> 15000.0
// o.isLarge()  -> true
// o            -> Order[id=A1, amount=15000.0, items=[TV]]
// o.equals(new Order("A1", 15000, List.of("TV"))) -> true`},{id:"jv-18",level:"mid",topic:"java-core",difficulty:"medium",simple:{hi:"Sealed class ek school ki fixed houses jaisi hai \u2013 Red, Blue, Green, Yellow. Principal ne pehle hi likh diya hai ki sirf yahi chaar houses honge, koi naya house khud se nahi bana sakta. Isliye sports teacher ko pata hai ki har bachcha inhi chaar mein se kisi ek mein hai.",en:"A sealed class is like a school's fixed houses \u2013 Red, Blue, Green, Yellow. The principal has written that only these four houses exist and nobody can create a new one on their own. So the sports teacher knows every child belongs to one of these four.",bn:"Sealed class \u09B9\u09B2\u09CB \u09B8\u09CD\u0995\u09C1\u09B2\u09C7\u09B0 \u09A8\u09BF\u09B0\u09CD\u09A6\u09BF\u09B7\u09CD\u099F house-\u0997\u09C1\u09B2\u09CB\u09B0 \u09AE\u09A4\u09CB \u2013 Red, Blue, Green, Yellow\u0964 \u09AA\u09CD\u09B0\u09BF\u09A8\u09CD\u09B8\u09BF\u09AA\u09BE\u09B2 \u0986\u0997\u09C7\u0987 \u09B2\u09BF\u0996\u09C7 \u09A6\u09BF\u09AF\u09BC\u09C7\u099B\u09C7\u09A8 \u09AF\u09C7 \u09B6\u09C1\u09A7\u09C1 \u098F\u0987 \u099A\u09BE\u09B0\u099F\u09C7 house \u09A5\u09BE\u0995\u09AC\u09C7, \u0995\u09C7\u0989 \u09A8\u09BF\u099C\u09C7 \u09A5\u09C7\u0995\u09C7 \u09A8\u09A4\u09C1\u09A8 house \u09AC\u09BE\u09A8\u09BE\u09A4\u09C7 \u09AA\u09BE\u09B0\u09AC\u09C7 \u09A8\u09BE\u0964 \u09A4\u09BE\u0987 \u09B8\u09CD\u09AA\u09CB\u09B0\u09CD\u099F\u09B8 \u099F\u09BF\u099A\u09BE\u09B0 \u099C\u09BE\u09A8\u09C7\u09A8 \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BE \u09AC\u09BE\u099A\u09CD\u099A\u09BE \u098F\u0987 \u099A\u09BE\u09B0\u099F\u09C7\u09B0 \u0995\u09CB\u09A8\u09CB \u098F\u0995\u099F\u09BE\u09AF\u09BC \u0986\u099B\u09C7\u0964"},question:"What are sealed classes and interfaces? Why are they useful?",answer:"A sealed class or interface restricts which classes may extend or implement it, using `sealed ... permits A, B, C`. Each permitted subclass must be declared `final`, `sealed` or `non-sealed`, and must be in the same module (or the same package if unnamed module). This lets you model a closed set of alternatives \u2014 like a domain's fixed states or an algebraic data type \u2014 and, combined with pattern matching for switch, the compiler can check exhaustiveness so you do not need a `default` branch and get a compile error when a new subtype is added.",points:["`sealed` + `permits` lists the only allowed subtypes","Subtypes must be final, sealed or non-sealed","Permits can be omitted if subclasses are in the same source file","Enables exhaustive switch without default; adding a subtype breaks the build at the right places","Records (implicitly final) are a natural fit as permitted subtypes"],code:`sealed interface Payment permits Card, Upi, Cash {}
record Card(String number) implements Payment {}
record Upi(String vpa) implements Payment {}
record Cash(double amount) implements Payment {}

class Fees {
    static double fee(Payment p) {
        return switch (p) {                 // exhaustive: no default needed
            case Card c -> 2.0;
            case Upi u  -> 0.0;
            case Cash c -> 0.5;
        };
    }
}`},{id:"jv-19",level:"senior",topic:"java-core",difficulty:"hard",simple:{hi:"Pattern matching ek smart ticket checker jaisa hai: dekhte hi pehchaan leta hai 'ye sleeper ka ticket hai' aur saath hi seat number bhi padh leta hai \u2013 alag se ticket kholke dobara padhna nahi padta. Har type ke ticket ke liye uske paas ek ready jawab hai.",en:"Pattern matching is like a smart ticket checker: at a glance he recognises 'this is a sleeper ticket' and reads the seat number at the same time \u2013 no need to open the ticket again to read it. He has a ready answer for every type of ticket.",bn:"Pattern matching \u09B9\u09B2\u09CB \u098F\u0995\u099C\u09A8 \u099A\u09BE\u09B2\u09BE\u0995 \u099F\u09BF\u0995\u09BF\u099F \u099A\u09C7\u0995\u09BE\u09B0\u09C7\u09B0 \u09AE\u09A4\u09CB: \u09A6\u09C7\u0996\u09C7\u0987 \u099A\u09BF\u09A8\u09C7 \u09AB\u09C7\u09B2\u09C7 '\u098F\u099F\u09BE sleeper-\u098F\u09B0 \u099F\u09BF\u0995\u09BF\u099F' \u0986\u09B0 \u09B8\u0999\u09CD\u0997\u09C7 \u09B8\u0999\u09CD\u0997\u09C7 \u09B8\u09BF\u099F \u09A8\u09AE\u09CD\u09AC\u09B0\u0993 \u09AA\u09A1\u09BC\u09C7 \u09A8\u09C7\u09AF\u09BC \u2013 \u0986\u09B2\u09BE\u09A6\u09BE \u0995\u09B0\u09C7 \u099F\u09BF\u0995\u09BF\u099F \u0996\u09C1\u09B2\u09C7 \u0986\u09AC\u09BE\u09B0 \u09AA\u09A1\u09BC\u09A4\u09C7 \u09B9\u09AF\u09BC \u09A8\u09BE\u0964 \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BE \u09A7\u09B0\u09A8\u09C7\u09B0 \u099F\u09BF\u0995\u09BF\u099F\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u09A4\u09BE\u09B0 \u0995\u09BE\u099B\u09C7 \u098F\u0995\u099F\u09BE \u09A4\u09C8\u09B0\u09BF \u0989\u09A4\u09CD\u09A4\u09B0 \u0986\u099B\u09C7\u0964"},question:"Explain pattern matching for instanceof and switch in modern Java.",answer:"Pattern matching for instanceof tests a type and binds a variable in one step: `if (obj instanceof String s && !s.isBlank())`, removing the explicit cast. Pattern matching for switch (final in Java 21) lets `case` labels be type patterns and record patterns, with guards using `when`, an explicit `case null`, and exhaustiveness checking for sealed hierarchies. Record patterns can deconstruct nested records directly (`case Circle(Point(var x, var y), double r)`). Together with sealed types and records this gives a data-oriented style that replaces long if-else instanceof chains and many visitor patterns.",points:["instanceof pattern: type test + cast + binding variable; scope follows flow (works with &&)","switch patterns: type patterns, record patterns, `when` guards, `case null`","Switch over a sealed type is checked for exhaustiveness at compile time","More specific cases must come before general ones (dominance) or it does not compile","Switch expressions use `->` and yield a value; no fall-through"],code:`sealed interface Shape permits Circle, Rect {}
record Circle(double r) implements Shape {}
record Rect(double w, double h) implements Shape {}

class Geo {
    static String describe(Object o) {
        if (o instanceof String s && !s.isBlank()) return "text: " + s.trim();
        return switch (o) {
            case null -> "null";
            case Circle c when c.r() == 0 -> "point";
            case Circle(double r) -> "circle area " + Math.PI * r * r;
            case Rect(double w, double h) when w == h -> "square " + w;
            case Rect(double w, double h) -> "rect " + w * h;
            case Integer i -> "int " + i;
            default -> "unknown";
        };
    }
}
// describe(new Rect(2, 2)) -> "square 2.0"`},{id:"jv-20",level:"junior",topic:"java-core",difficulty:"easy",simple:{hi:"var ek samajhdaar dukaandaar jaisa hai: tum haath mein aam dikhate ho to wo khud likh leta hai 'aam' \u2013 tumhe bolna nahi padta. Par ek baar 'aam' likh diya to baad mein usmein kela nahi daal sakte.",en:"var is like a smart shopkeeper: when you show a mango in your hand, he writes 'mango' himself \u2013 you don't have to say it. But once he has written 'mango', you can't later put a banana in that place.",bn:"var \u09B9\u09B2\u09CB \u098F\u0995\u099C\u09A8 \u09AC\u09C1\u09A6\u09CD\u09A7\u09BF\u09AE\u09BE\u09A8 \u09A6\u09CB\u0995\u09BE\u09A8\u09A6\u09BE\u09B0\u09C7\u09B0 \u09AE\u09A4\u09CB: \u09A4\u09C1\u09AE\u09BF \u09B9\u09BE\u09A4\u09C7 \u0986\u09AE \u09A6\u09C7\u0996\u09BE\u09B2\u09C7 \u09B8\u09C7 \u09A8\u09BF\u099C\u09C7\u0987 \u09B2\u09BF\u0996\u09C7 \u09A8\u09C7\u09AF\u09BC '\u0986\u09AE' \u2013 \u09A4\u09CB\u09AE\u09BE\u0995\u09C7 \u09AC\u09B2\u09A4\u09C7 \u09B9\u09AF\u09BC \u09A8\u09BE\u0964 \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u098F\u0995\u09AC\u09BE\u09B0 '\u0986\u09AE' \u09B2\u09C7\u0996\u09BE \u09B9\u09AF\u09BC\u09C7 \u0997\u09C7\u09B2\u09C7 \u09AA\u09B0\u09C7 \u09B8\u09C7\u0996\u09BE\u09A8\u09C7 \u0995\u09B2\u09BE \u09B0\u09BE\u0996\u09A4\u09C7 \u09AA\u09BE\u09B0\u09AC\u09C7 \u09A8\u09BE\u0964"},question:"What is `var` in Java? Where can and can't you use it?",answer:"`var` (local variable type inference) lets the compiler infer the static type of a local variable from its initializer: `var list = new ArrayList<String>();` is still strongly typed as ArrayList<String>. It works for local variables with an initializer, enhanced for-loop and classic for-loop variables, try-with-resources variables, and lambda parameters. It cannot be used for fields, method parameters, return types, without an initializer, with a `null` initializer, or with array initializers like `var a = {1, 2}`. Java is still statically typed \u2014 `var` is not like JavaScript's var \u2014 so use it when the type is obvious from the right-hand side.",points:["Compile-time inference only; no dynamic typing","Allowed: locals with initializer, for/for-each, try-with-resources, lambda params","Not allowed: fields, method params, return types, `var x;`, `var x = null;`, `var a = {1,2};`","`var` is a reserved type name, not a keyword (can still be a variable name)","Avoid it when it hides an important type (e.g. `var result = service.process();`)"],code:`import java.util.*;

var names = new ArrayList<String>();     // ArrayList<String>
names.add("Asha");
// names.add(10);                       // compile error: still typed

for (var n : names) System.out.println(n.toUpperCase());

var map = new HashMap<String, List<Integer>>();

// var x;            // error: no initializer
// var y = null;     // error: cannot infer
// var arr = {1, 2}; // error: array initializer needs explicit type`},{id:"jv-21",level:"junior",topic:"java-core",difficulty:"medium",simple:{hi:"Enum cricket ke dismissal types jaisa hai \u2013 Bowled, Caught, LBW, Run Out, Stumped. List fix hai, umpire apni marzi se naya type nahi bana sakta. Aur har type ke saath extra info bhi ho sakti hai, jaise 'kis fielder ne pakda'.",en:"An enum is like the types of dismissal in cricket \u2013 Bowled, Caught, LBW, Run Out, Stumped. The list is fixed; the umpire can't invent a new type. And each type can carry extra information too, like 'which fielder caught it'.",bn:"Enum \u09B9\u09B2\u09CB \u0995\u09CD\u09B0\u09BF\u0995\u09C7\u099F\u09C7 \u0986\u0989\u099F \u09B9\u0993\u09AF\u09BC\u09BE\u09B0 \u09A7\u09B0\u09A8\u0997\u09C1\u09B2\u09CB\u09B0 \u09AE\u09A4\u09CB \u2013 Bowled, Caught, LBW, Run Out, Stumped\u0964 \u09A4\u09BE\u09B2\u09BF\u0995\u09BE\u099F\u09BE \u09A8\u09BF\u09B0\u09CD\u09A6\u09BF\u09B7\u09CD\u099F, \u0986\u09AE\u09CD\u09AA\u09BE\u09AF\u09BC\u09BE\u09B0 \u09A8\u09BF\u099C\u09C7\u09B0 \u0987\u099A\u09CD\u099B\u09C7\u09AE\u09A4\u09CB \u09A8\u09A4\u09C1\u09A8 \u09A7\u09B0\u09A8 \u09AC\u09BE\u09A8\u09BE\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u09A8\u09BE\u0964 \u0986\u09B0 \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BE \u09A7\u09B0\u09A8\u09C7\u09B0 \u09B8\u0999\u09CD\u0997\u09C7 \u09AC\u09BE\u09A1\u09BC\u09A4\u09BF \u09A4\u09A5\u09CD\u09AF\u0993 \u09A5\u09BE\u0995\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7, \u09AF\u09C7\u09AE\u09A8 '\u0995\u09CB\u09A8 fielder \u09A7\u09B0\u09C7\u099B\u09C7'\u0964"},question:"What are enums in Java? Can enums have fields, constructors and methods?",answer:"An enum is a special class that defines a fixed set of named constants, giving type safety instead of int or String constants. Every enum implicitly extends java.lang.Enum, so it cannot extend another class but can implement interfaces; it can have fields, private constructors, methods, and even constant-specific method bodies. Enums provide `values()`, `valueOf()`, `name()` and `ordinal()`, work in switch, are effectively singletons per constant (safe to compare with ==), and have efficient companions EnumMap and EnumSet.",points:["Fixed set of type-safe constants; implicitly final and static instances","Constructors are private; fields and methods are allowed","Can implement interfaces and have constant-specific bodies",'values(), valueOf("NAME") (throws IllegalArgumentException if unknown), ordinal()',"Do not persist ordinal() \u2014 reordering constants breaks data; store name()","Single-element enum is a recommended way to implement a singleton"],code:`enum Coin {
    ONE(1), TWO(2), FIVE(5), TEN(10);

    private final int value;
    Coin(int value) { this.value = value; }   // implicitly private
    int value() { return value; }
}

enum Op {
    PLUS  { int apply(int a, int b) { return a + b; } },
    MINUS { int apply(int a, int b) { return a - b; } };
    abstract int apply(int a, int b);
}

// Coin.FIVE.value()          -> 5
// Coin.valueOf("TEN")        -> TEN
// Op.MINUS.apply(10, 3)      -> 7
// Coin.ONE == Coin.ONE       -> true`},{id:"jv-22",level:"senior",topic:"java-core",difficulty:"hard",simple:{hi:"Immutable object Aadhaar card jaisa hai \u2013 ek baar ban gaya to usmein pen se kuch nahi likh sakte. Naam badalna hai to naya card banta hai. Aur agar koi tumhe photocopy maange, to tum photocopy dete ho, asli card nahi \u2013 yahi defensive copy hai.",en:"An immutable object is like an Aadhaar card \u2013 once made, you can't write anything on it with a pen. To change the name, a new card is issued. And if someone asks for a copy, you give a photocopy, not the original \u2013 that is a defensive copy.",bn:"Immutable object \u09B9\u09B2\u09CB Aadhaar \u0995\u09BE\u09B0\u09CD\u09A1\u09C7\u09B0 \u09AE\u09A4\u09CB \u2013 \u098F\u0995\u09AC\u09BE\u09B0 \u09A4\u09C8\u09B0\u09BF \u09B9\u09B2\u09C7 \u09A4\u09BE\u09A4\u09C7 \u09AA\u09C7\u09A8 \u09A6\u09BF\u09AF\u09BC\u09C7 \u0995\u09BF\u099B\u09C1 \u09B2\u09C7\u0996\u09BE \u09AF\u09BE\u09AF\u09BC \u09A8\u09BE\u0964 \u09A8\u09BE\u09AE \u09AC\u09A6\u09B2\u09BE\u09A4\u09C7 \u09B9\u09B2\u09C7 \u09A8\u09A4\u09C1\u09A8 \u0995\u09BE\u09B0\u09CD\u09A1 \u09A4\u09C8\u09B0\u09BF \u09B9\u09AF\u09BC\u0964 \u0986\u09B0 \u0995\u09C7\u0989 \u0995\u09AA\u09BF \u099A\u09BE\u0987\u09B2\u09C7 \u09A4\u09C1\u09AE\u09BF photocopy \u09A6\u09BE\u0993, \u0986\u09B8\u09B2 \u0995\u09BE\u09B0\u09CD\u09A1 \u09A8\u09AF\u09BC \u2013 \u098F\u099F\u09BE\u0987 defensive copy\u0964"},question:"How do you write an immutable class in Java? Write one that holds a mutable field like a List or Date.",answer:"Make the class final (or give it a private constructor with factory methods) so subclasses cannot add mutable behaviour, make all fields private and final, provide no setters, and initialise everything in the constructor. For mutable components, make defensive copies on the way in and never expose the internal reference on the way out \u2014 return a copy or an unmodifiable view, or better, use immutable types like `List.copyOf` and `java.time` classes instead of Date. 'Modifying' operations return a new instance (withers). Immutable objects are automatically thread safe, safe as map keys and easy to cache; a record with a compact constructor that copies collections is the modern shortcut.",points:["final class, private final fields, no setters","Defensive copy of mutable inputs in the constructor (copy before validating)","Never return internal mutable references; return copies / unmodifiable views","Prefer immutable building blocks: List.copyOf, LocalDate instead of Date","Provide `withX(...)` methods that return a new object","Benefits: thread safety, safe sharing and caching, reliable hashCode"],code:`import java.time.LocalDate;
import java.util.List;

public final class Student {
    private final String name;
    private final LocalDate dob;          // already immutable
    private final List<String> subjects;

    public Student(String name, LocalDate dob, List<String> subjects) {
        this.name = name;
        this.dob = dob;
        this.subjects = List.copyOf(subjects); // defensive, unmodifiable copy
    }

    public String getName() { return name; }
    public LocalDate getDob() { return dob; }
    public List<String> getSubjects() { return subjects; } // caller can't modify

    public Student withName(String newName) {
        return new Student(newName, dob, subjects);
    }
}`},{id:"jv-23",level:"mid",topic:"java-core",difficulty:"medium",simple:{hi:"Socho tumne dost ko apne ghar ka address ek parchi pe likh ke diya (reference ki copy). Dost us address pe jaake ghar ki deewar paint kar de, to tumhara ghar badal jaayega. Par agar dost apni parchi pe koi aur address likh le, to tumhara ghar wahi rahega \u2013 kyunki usne sirf apni parchi badli.",en:"Imagine you write your home address on a slip and give it to a friend (a copy of the reference). If the friend goes there and paints the wall, your house changes. But if the friend writes another address on his slip, your house stays the same \u2013 he only changed his own slip.",bn:"\u09AD\u09BE\u09AC\u09CB \u09A4\u09C1\u09AE\u09BF \u09AC\u09A8\u09CD\u09A7\u09C1\u0995\u09C7 \u098F\u0995\u099F\u09BE \u099A\u09BF\u09B0\u0995\u09C1\u099F\u09C7 \u09A8\u09BF\u099C\u09C7\u09B0 \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u09A0\u09BF\u0995\u09BE\u09A8\u09BE \u09B2\u09BF\u0996\u09C7 \u09A6\u09BF\u09B2\u09C7 (reference-\u098F\u09B0 \u0995\u09AA\u09BF)\u0964 \u09AC\u09A8\u09CD\u09A7\u09C1 \u09B8\u09C7\u0987 \u09A0\u09BF\u0995\u09BE\u09A8\u09BE\u09AF\u09BC \u0997\u09BF\u09AF\u09BC\u09C7 \u09A6\u09C7\u0993\u09AF\u09BC\u09BE\u09B2 \u09B0\u0982 \u0995\u09B0\u09C7 \u09A6\u09BF\u09B2\u09C7 \u09A4\u09CB\u09AE\u09BE\u09B0 \u09AC\u09BE\u09A1\u09BC\u09BF \u09AC\u09A6\u09B2\u09C7 \u09AF\u09BE\u09AC\u09C7\u0964 \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09AC\u09A8\u09CD\u09A7\u09C1 \u09A8\u09BF\u099C\u09C7\u09B0 \u099A\u09BF\u09B0\u0995\u09C1\u099F\u09C7 \u0985\u09A8\u09CD\u09AF \u09A0\u09BF\u0995\u09BE\u09A8\u09BE \u09B2\u09BF\u0996\u09C7 \u09A8\u09BF\u09B2\u09C7 \u09A4\u09CB\u09AE\u09BE\u09B0 \u09AC\u09BE\u09A1\u09BC\u09BF \u098F\u0995\u0987 \u09A5\u09BE\u0995\u09AC\u09C7 \u2013 \u0995\u09BE\u09B0\u09A3 \u09B8\u09C7 \u09B6\u09C1\u09A7\u09C1 \u09A8\u09BF\u099C\u09C7\u09B0 \u099A\u09BF\u09B0\u0995\u09C1\u099F \u09AC\u09A6\u09B2\u09C7\u099B\u09C7\u0964"},question:"Is Java pass-by-value or pass-by-reference? Explain with this code.",answer:"Java is always pass-by-value. For primitives the value itself is copied; for objects the value that is copied is the reference, so the method gets its own copy of a pointer to the same object. That is why changing the object's state through the parameter is visible to the caller (`rename` changes the name to \"Ravi\"), but reassigning the parameter to a new object is not (`reassign` leaves the caller's object unchanged), and a classic swap method cannot swap the caller's variables. The output is `Ravi` and then `Ravi` again.",points:["Everything is passed by value; for objects the value is a copy of the reference","Mutating the object via the parameter affects the caller's object","Reassigning the parameter only changes the local copy","A swap(a, b) method cannot swap the caller's variables in Java","Strings and wrappers look 'by value' because they are immutable"],code:`class Person { String name; Person(String n) { name = n; } }

public class Main {
    static void rename(Person p)   { p.name = "Ravi"; }          // changes the object
    static void reassign(Person p) { p = new Person("Amit"); }  // changes local copy only
    static void inc(int x)         { x++; }

    public static void main(String[] args) {
        Person per = new Person("Sam");
        rename(per);
        System.out.println(per.name); // Ravi
        reassign(per);
        System.out.println(per.name); // Ravi
        int n = 5; inc(n);
        System.out.println(n);        // 5
    }
}`},{id:"jv-24",level:"senior",topic:"java-core",difficulty:"medium",simple:{hi:"Java ke versions mobile phone ke updates jaise hain. Java 8 ek bada update tha jisne naye smart features (lambda, stream) diye, aur uske baad har chhe mahine chhote-chhote naye features aate hain. LTS version wo phone hai jise company kai saal tak support karti hai \u2013 isliye offices mein wahi chalta hai.",en:"Java versions are like mobile phone updates. Java 8 was a big update that brought new smart features (lambda, stream), and after that small new features arrive every six months. An LTS version is the phone the company supports for many years \u2013 so that is what offices use.",bn:"Java-\u09B0 versions \u09B9\u09B2\u09CB \u09AE\u09CB\u09AC\u09BE\u0987\u09B2 \u09AB\u09CB\u09A8\u09C7\u09B0 update-\u098F\u09B0 \u09AE\u09A4\u09CB\u0964 Java 8 \u099B\u09BF\u09B2 \u098F\u0995\u099F\u09BE \u09AC\u09A1\u09BC update \u09AF\u09BE \u09A8\u09A4\u09C1\u09A8 smart features (lambda, stream) \u098F\u09A8\u09C7\u099B\u09BF\u09B2, \u0986\u09B0 \u09A4\u09BE\u09B0\u09AA\u09B0 \u09AA\u09CD\u09B0\u09A4\u09BF \u099B\u09AF\u09BC \u09AE\u09BE\u09B8\u09C7 \u099B\u09CB\u099F \u099B\u09CB\u099F \u09A8\u09A4\u09C1\u09A8 features \u0986\u09B8\u09C7\u0964 LTS version \u09B9\u09B2\u09CB \u09B8\u09C7\u0987 \u09AB\u09CB\u09A8 \u09AF\u09C7\u099F\u09BE\u0995\u09C7 \u0995\u09CB\u09AE\u09CD\u09AA\u09BE\u09A8\u09BF \u0985\u09A8\u09C7\u0995 \u09AC\u099B\u09B0 support \u09A6\u09C7\u09AF\u09BC \u2013 \u09A4\u09BE\u0987 \u0985\u09AB\u09BF\u09B8\u09C7 \u09B8\u09C7\u099F\u09BE\u0987 \u099A\u09B2\u09C7\u0964"},question:"What are the main features added in Java 8 and later versions up to Java 21?",answer:"Java 8 was the big functional shift: lambdas, functional interfaces, method references, the Stream API, Optional, default and static interface methods, and the java.time API. Later releases added the module system (9), `var` (10), the standard HttpClient and String methods like isBlank/strip/lines (11), switch expressions (14), text blocks (15), records and pattern matching for instanceof (16), sealed classes (17), and in Java 21 LTS: virtual threads, pattern matching for switch, record patterns and sequenced collections. Java now releases every six months with an LTS every two years (11, 17, 21, 25), and most companies target an LTS such as 17 or 21.",points:["Java 8: lambdas, streams, Optional, default methods, java.time, CompletableFuture","9\u201311: modules, jshell, var, List.of/Map.of, HttpClient, new String methods","14\u201317: switch expressions, text blocks, records, instanceof patterns, sealed classes","21 LTS: virtual threads, switch pattern matching, record patterns, sequenced collections","Six-month release cadence; LTS versions are what enterprises run in production"],code:`// Java 8: lambda + java.time
java.util.List.of("b", "a").forEach(s -> System.out.println(s));
var today = java.time.LocalDate.now();          // var: Java 10

// Text block (15)
String json = """
    { "name": "Asha" }
    """;

// Record (16) + sealed (17) + switch patterns (21)
sealed interface Animal permits Dog, Cat {}
record Dog(String name) implements Animal {}
record Cat(String name) implements Animal {}

static String sound(Animal a) {
    return switch (a) {
        case Dog d -> d.name() + " barks";
        case Cat c -> c.name() + " meows";
    };
}`},{id:"jv-25",level:"fresher",topic:"java-core",difficulty:"easy",simple:{hi:"Constructor naye admission jaisa hai \u2013 bachcha school aata hai to pehle uska naam, class, roll number set hota hai. super() matlab pehle papa ka form bharna, phir bachche ka. this() matlab ek form doosre form ko bolta hai 'ye kaam tum kar do', taaki dobara same cheez na likhni pade.",en:"A constructor is like a new school admission \u2013 when a child joins, their name, class and roll number are set first. super() means filling the parent's form first, then the child's. this() means one form tells another form 'you do this part', so the same thing is not written twice.",bn:"Constructor \u09B9\u09B2\u09CB \u09B8\u09CD\u0995\u09C1\u09B2\u09C7 \u09A8\u09A4\u09C1\u09A8 \u09AD\u09B0\u09CD\u09A4\u09BF\u09B0 \u09AE\u09A4\u09CB \u2013 \u09AC\u09BE\u099A\u09CD\u099A\u09BE \u098F\u09B2\u09C7 \u09AA\u09CD\u09B0\u09A5\u09AE\u09C7 \u09A4\u09BE\u09B0 \u09A8\u09BE\u09AE, \u0995\u09CD\u09B2\u09BE\u09B8, \u09B0\u09CB\u09B2 \u09A8\u09AE\u09CD\u09AC\u09B0 \u09A0\u09BF\u0995 \u0995\u09B0\u09BE \u09B9\u09AF\u09BC\u0964 super() \u09AE\u09BE\u09A8\u09C7 \u0986\u0997\u09C7 \u09AC\u09BE\u09AC\u09BE\u09B0 \u09AB\u09B0\u09CD\u09AE \u09AA\u09C2\u09B0\u09A3, \u09A4\u09BE\u09B0\u09AA\u09B0 \u09AC\u09BE\u099A\u09CD\u099A\u09BE\u09B0\u0964 this() \u09AE\u09BE\u09A8\u09C7 \u098F\u0995 \u09AB\u09B0\u09CD\u09AE \u0985\u09A8\u09CD\u09AF \u09AB\u09B0\u09CD\u09AE\u0995\u09C7 \u09AC\u09B2\u09C7 '\u098F\u0987 \u0985\u0982\u09B6\u099F\u09BE \u09A4\u09C1\u09AE\u09BF \u0995\u09B0\u09C7 \u09A6\u09BE\u0993', \u09AF\u09BE\u09A4\u09C7 \u098F\u0995\u0987 \u099C\u09BF\u09A8\u09BF\u09B8 \u09A6\u09C1\u09AC\u09BE\u09B0 \u09B2\u09BF\u0996\u09A4\u09C7 \u09A8\u09BE \u09B9\u09AF\u09BC\u0964"},question:"What are constructors in Java? Explain constructor chaining with this() and super().",answer:"A constructor is a special block with the class name and no return type that initialises a new object; if you write none, the compiler adds a default no-arg constructor. Constructors can be overloaded, and `this(...)` calls another constructor of the same class to avoid duplicate code, while `super(...)` calls a parent class constructor. Either call must be the first statement, you cannot use both in one constructor, and if you write neither, the compiler inserts `super()` \u2014 so the parent is always initialised before the child. Constructors are not inherited and cannot be overridden.",points:["Same name as the class, no return type, runs on `new`","Default constructor is added only if no constructor is written","this(...) chains within the same class; super(...) calls the parent constructor","this()/super() must be the first statement (traditionally); only one of them per constructor","Parent constructor always runs before the child's body","If the parent has no no-arg constructor, the child must call super(args) explicitly"],code:`class Person {
    protected final String name;
    Person(String name) {
        this.name = name;
        System.out.println("Person(" + name + ")");
    }
}

class Employee extends Person {
    private final double salary;

    Employee(String name) {
        this(name, 30000);              // chain to the other constructor
        System.out.println("Employee(name)");
    }
    Employee(String name, double salary) {
        super(name);                    // parent first
        this.salary = salary;
        System.out.println("Employee(name, salary)");
    }
}
// new Employee("Asha") prints:
// Person(Asha) / Employee(name, salary) / Employee(name)`},{id:"sp-1",level:"fresher",topic:"spring",difficulty:"easy",simple:{hi:"Spring ek kitchen ke saare bartan aur masale jaisa hai \u2014 sab kuch hai, par sab set karke khana tumhe khud banana padta hai. Spring Boot ek ready meal kit jaisa hai: sab cheez naap-tol ke packet mein aati hai, bas gas jalao aur khana ready.",en:"Spring is like a kitchen full of utensils and spices \u2014 everything is there, but you must set it all up and cook yourself. Spring Boot is like a ready meal kit: everything comes measured in packets, just switch on the gas and the food is ready.",bn:"Spring \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE \u09B0\u09BE\u09A8\u09CD\u09A8\u09BE\u0998\u09B0\u09C7\u09B0 \u09B8\u09AC \u09AC\u09BE\u09B8\u09A8\u09AA\u09A4\u09CD\u09B0 \u0986\u09B0 \u09AE\u09B6\u09B2\u09BE\u09B0 \u09AE\u09A4\u09CB \u2014 \u09B8\u09AC \u0986\u099B\u09C7, \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09B8\u09AC \u09B8\u09BE\u099C\u09BF\u09AF\u09BC\u09C7 \u09A4\u09CB\u09AE\u09BE\u0995\u09C7 \u09A8\u09BF\u099C\u09C7 \u09B0\u09BE\u09A8\u09CD\u09A8\u09BE \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7\u0964 Spring Boot \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE \u09B0\u09C7\u09A1\u09BF \u09AE\u09BF\u09B2 \u0995\u09BF\u099F\u09C7\u09B0 \u09AE\u09A4\u09CB: \u09B8\u09AC \u0995\u09BF\u099B\u09C1 \u09AE\u09C7\u09AA\u09C7 \u09AA\u09CD\u09AF\u09BE\u0995\u09C7\u099F\u09C7 \u0986\u09B8\u09C7, \u09B6\u09C1\u09A7\u09C1 \u0997\u09CD\u09AF\u09BE\u09B8 \u099C\u09CD\u09AC\u09BE\u09B2\u09BE\u0993 \u0986\u09B0 \u0996\u09BE\u09AC\u09BE\u09B0 \u09A4\u09C8\u09B0\u09BF\u0964"},question:"What is the difference between Spring Framework and Spring Boot?",answer:"Spring Framework is the core toolkit \u2014 IoC container, dependency injection, AOP, Spring MVC, transactions and data access \u2014 but you assemble and configure it yourself. Spring Boot is an opinionated layer on top of Spring that adds auto-configuration, starter dependencies, an embedded server (Tomcat by default) and production features like Actuator, so you can run a production-ready app with `java -jar` and very little configuration. Boot does not replace Spring; it configures Spring for you.",points:["Spring = the framework (IoC, DI, MVC, AOP, transactions)","Spring Boot = convention over configuration on top of Spring","Auto-configuration and starters remove boilerplate and dependency-version conflicts","Embedded Tomcat/Jetty/Undertow \u2014 runnable fat jar, no separate WAR deployment","Spring Boot 3 needs Java 17+ and uses jakarta.* packages instead of javax.*"],code:`@SpringBootApplication
public class ShopApplication {
    public static void main(String[] args) {
        SpringApplication.run(ShopApplication.class, args); // starts context + embedded Tomcat
    }
}
// run: ./mvnw spring-boot:run   or   java -jar target/shop-0.0.1.jar`},{id:"sp-2",level:"fresher",topic:"spring",difficulty:"easy",simple:{hi:"IoC aisa hai jaise school canteen wale uncle tumhara tiffin bana ke dete hain \u2014 tumhe khud khana nahi banana. Constructor injection matlab class mein aate hi poora tiffin haath mein mil jaata hai, aadha khaali dabba kabhi nahi milta.",en:"IoC is like the school canteen uncle preparing your tiffin \u2014 you don't cook it yourself. Constructor injection means you get the full tiffin in your hand the moment you enter class, never a half-empty box.",bn:"IoC \u09B9\u09B2\u09CB \u09B8\u09CD\u0995\u09C1\u09B2\u09C7\u09B0 \u0995\u09CD\u09AF\u09BE\u09A8\u09CD\u099F\u09BF\u09A8\u09C7\u09B0 \u0995\u09BE\u0995\u09C1 \u09AF\u09C7\u09AE\u09A8 \u099F\u09BF\u09AB\u09BF\u09A8 \u09AC\u09BE\u09A8\u09BF\u09AF\u09BC\u09C7 \u09A6\u09C7\u09A8 \u2014 \u09A4\u09CB\u09AE\u09BE\u0995\u09C7 \u09A8\u09BF\u099C\u09C7 \u09B0\u09BE\u09A8\u09CD\u09A8\u09BE \u0995\u09B0\u09A4\u09C7 \u09B9\u09AF\u09BC \u09A8\u09BE\u0964 Constructor injection \u09AE\u09BE\u09A8\u09C7 \u0995\u09CD\u09B2\u09BE\u09B8\u09C7 \u09A2\u09CB\u0995\u09BE\u09B0 \u09B8\u0999\u09CD\u0997\u09C7 \u09B8\u0999\u09CD\u0997\u09C7\u0987 \u09AA\u09C1\u09B0\u09CB \u099F\u09BF\u09AB\u09BF\u09A8 \u09B9\u09BE\u09A4\u09C7 \u09AA\u09BE\u0993, \u0995\u0996\u09A8\u09CB \u0986\u09A7\u0996\u09BE\u09B2\u09BF \u09AC\u09BE\u0995\u09CD\u09B8 \u09AA\u09BE\u0993 \u09A8\u09BE\u0964"},question:"What are IoC and dependency injection in Spring, and why is constructor injection preferred?",answer:"Inversion of Control means the Spring container, not your code, creates objects (beans) and manages their lifecycle; dependency injection is how Spring does it \u2014 the container passes a bean's dependencies in instead of the bean creating them with `new`. Constructor injection is preferred because dependencies can be `final` (immutable), the object can never exist half-initialised, required dependencies are explicit, and the class is easy to unit test with plain `new` and mocks. With a single constructor, `@Autowired` is not even needed.",points:["IoC: the container controls object creation and wiring, giving loose coupling","DI styles: constructor, setter (optional dependencies), field (discouraged)","Constructor injection gives final fields, immutability and no null dependencies","Easy unit tests without starting a Spring context","A constructor with too many parameters is a design smell \u2014 the class does too much","Field injection hides dependencies and needs reflection or Spring to test"],code:`@Service
public class OrderService {
    private final PaymentClient paymentClient;
    private final OrderRepository orderRepository;

    // single constructor: @Autowired is optional
    public OrderService(PaymentClient paymentClient, OrderRepository orderRepository) {
        this.paymentClient = paymentClient;
        this.orderRepository = orderRepository;
    }
}

// unit test without Spring:
// var service = new OrderService(mock(PaymentClient.class), mock(OrderRepository.class));`},{id:"sp-3",level:"junior",topic:"spring",difficulty:"medium",simple:{hi:"Singleton class ke ek hi blackboard jaisa hai \u2014 sab bachche wahi use karte hain. Prototype aisa hai jaise har bachche ko nayi copy milti hai. Request scope matlab har exam ke liye nayi answer sheet.",en:"Singleton is like one blackboard for the whole class \u2014 every student uses the same one. Prototype is like giving each student a fresh copy. Request scope is a new answer sheet for every exam.",bn:"Singleton \u09B9\u09B2\u09CB \u0995\u09CD\u09B2\u09BE\u09B8\u09C7\u09B0 \u098F\u0995\u099F\u09BE\u0987 \u09AC\u09CD\u09B2\u09CD\u09AF\u09BE\u0995\u09AC\u09CB\u09B0\u09CD\u09A1 \u2014 \u09B8\u09AC \u099B\u09BE\u09A4\u09CD\u09B0 \u09B8\u09C7\u099F\u09BE\u0987 \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09C7\u0964 Prototype \u09AE\u09BE\u09A8\u09C7 \u09AA\u09CD\u09B0\u09A4\u09CD\u09AF\u09C7\u0995 \u099B\u09BE\u09A4\u09CD\u09B0 \u09A8\u09A4\u09C1\u09A8 \u098F\u0995\u099F\u09BE \u0995\u09AA\u09BF \u09AA\u09BE\u09AF\u09BC\u0964 Request scope \u09AE\u09BE\u09A8\u09C7 \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BE \u09AA\u09B0\u09C0\u0995\u09CD\u09B7\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09A8\u09A4\u09C1\u09A8 \u0989\u09A4\u09CD\u09A4\u09B0\u09AA\u09A4\u09CD\u09B0\u0964"},question:"What bean scopes does Spring support?",answer:"Scope decides how many instances of a bean Spring creates. `singleton` (default) gives one shared instance per container; `prototype` gives a new instance every time the bean is requested; the web-aware scopes `request`, `session`, `application` and `websocket` give one instance per HTTP request, HTTP session, ServletContext and WebSocket session. Spring does not call destroy callbacks for prototype beans, and a prototype injected into a singleton is created only once \u2014 use `ObjectProvider` (or `@Lookup`) to get a fresh instance each time.",points:["singleton is the default \u2014 one instance per ApplicationContext, not per JVM","Singleton beans are shared across threads, so keep them stateless or thread-safe","prototype: new instance per lookup; container does not manage its destruction","request / session / application / websocket only work in a web-aware context","Prototype into singleton: inject ObjectProvider<T> or use a scoped proxy"],code:`@Component
@Scope(ConfigurableBeanFactory.SCOPE_PROTOTYPE)
public class ReportBuilder { }

@Service
public class ReportService {
    private final ObjectProvider<ReportBuilder> builders;

    public ReportService(ObjectProvider<ReportBuilder> builders) {
        this.builders = builders;
    }

    public void generate() {
        ReportBuilder builder = builders.getObject(); // new instance on every call
    }
}`},{id:"sp-4",level:"junior",topic:"spring",difficulty:"medium",simple:{hi:"Bean ki life ek train journey jaisi hai: ticket bana (create), saman chadha (dependencies), seat pe baithe (@PostConstruct), safar kiya (use), aur station pe saman le ke utar gaye (@PreDestroy).",en:"A bean's life is like a train journey: ticket booked (created), luggage loaded (dependencies), seated (@PostConstruct), the journey (use), and getting off at the station with your luggage (@PreDestroy).",bn:"Bean-\u098F\u09B0 \u099C\u09C0\u09AC\u09A8 \u098F\u0995\u099F\u09BE \u099F\u09CD\u09B0\u09C7\u09A8 \u09AF\u09BE\u09A4\u09CD\u09B0\u09BE\u09B0 \u09AE\u09A4\u09CB: \u099F\u09BF\u0995\u09BF\u099F \u0995\u09BE\u099F\u09BE (create), \u09AE\u09BE\u09B2\u09AA\u09A4\u09CD\u09B0 \u09A4\u09CB\u09B2\u09BE (dependencies), \u09B8\u09BF\u099F\u09C7 \u09AC\u09B8\u09BE (@PostConstruct), \u09AF\u09BE\u09A4\u09CD\u09B0\u09BE (use), \u0986\u09B0 \u09B8\u09CD\u099F\u09C7\u09B6\u09A8\u09C7 \u09AE\u09BE\u09B2\u09AA\u09A4\u09CD\u09B0 \u09A8\u09BF\u09AF\u09BC\u09C7 \u09A8\u09C7\u09AE\u09C7 \u09AF\u09BE\u0993\u09AF\u09BC\u09BE (@PreDestroy)\u0964"},question:"Explain the Spring bean lifecycle.",answer:"Spring instantiates the bean, injects its dependencies, calls Aware callbacks (such as `BeanNameAware`, `ApplicationContextAware`), runs every `BeanPostProcessor.postProcessBeforeInitialization`, then the init callbacks (`@PostConstruct`, `InitializingBean.afterPropertiesSet()`, a custom init method), and finally `postProcessAfterInitialization` \u2014 which is where AOP proxies (for `@Transactional`, `@Async` etc.) are created. The bean is then ready to use. When the context shuts down, `@PreDestroy`, `DisposableBean.destroy()` and a custom destroy method run \u2014 for singletons, not prototypes.",points:["Order: instantiate \u2192 populate dependencies \u2192 Aware \u2192 BPP before \u2192 init \u2192 BPP after \u2192 ready \u2192 destroy","@PostConstruct runs after injection \u2014 safe place to use dependencies (warm caches, validate config)","Don't do heavy work in the constructor; dependencies of setter/field injection aren't set yet","Proxies are created in postProcessAfterInitialization, so the injected object may be a proxy","Spring Boot 3 uses jakarta.annotation.PostConstruct / PreDestroy","Destroy callbacks are not called for prototype beans"],code:`import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;

@Component
public class CacheLoader {
    private final ProductRepository repo;

    public CacheLoader(ProductRepository repo) { this.repo = repo; } // 1. instantiate + inject

    @PostConstruct
    void init() {                                                     // 2. after injection
        System.out.println("Warming cache with " + repo.count() + " products");
    }

    @PreDestroy
    void cleanup() {                                                  // 3. on context close
        System.out.println("Releasing resources");
    }
}`},{id:"sp-5",level:"fresher",topic:"spring",difficulty:"easy",simple:{hi:"Sab school staff hain (@Component), par badge alag hai: principal ka office (@Controller) logon se baat karta hai, teacher (@Service) padhati hai, aur librarian (@Repository) kitaabein sambhaalta hai.",en:"Everyone is school staff (@Component), but with different badges: the principal's office (@Controller) talks to visitors, the teacher (@Service) teaches, and the librarian (@Repository) looks after the books.",bn:"\u09B8\u09AC\u09BE\u0987 \u09B8\u09CD\u0995\u09C1\u09B2\u09C7\u09B0 \u09B8\u09CD\u099F\u09BE\u09AB (@Component), \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09AC\u09CD\u09AF\u09BE\u099C \u0986\u09B2\u09BE\u09A6\u09BE: \u09AA\u09CD\u09B0\u09BF\u09A8\u09CD\u09B8\u09BF\u09AA\u09BE\u09B2\u09C7\u09B0 \u0985\u09AB\u09BF\u09B8 (@Controller) \u09B2\u09CB\u0995\u09C7\u09A6\u09C7\u09B0 \u09B8\u0999\u09CD\u0997\u09C7 \u0995\u09A5\u09BE \u09AC\u09B2\u09C7, \u099F\u09BF\u099A\u09BE\u09B0 (@Service) \u09AA\u09A1\u09BC\u09BE\u09A8, \u0986\u09B0 \u09B2\u09BE\u0987\u09AC\u09CD\u09B0\u09C7\u09B0\u09BF\u09AF\u09BC\u09BE\u09A8 (@Repository) \u09AC\u0987\u09AA\u09A4\u09CD\u09B0 \u09B8\u09BE\u09AE\u09B2\u09BE\u09A8\u0964"},question:"What is the difference between @Component, @Service, @Repository and @Controller?",answer:"`@Component` is the generic stereotype that marks a class for component scanning so Spring registers it as a bean. `@Service`, `@Repository` and `@Controller` are specialisations of `@Component`: all of them register a bean, but they document the layer and some add behaviour \u2014 `@Repository` enables translation of persistence exceptions into Spring's `DataAccessException` hierarchy, and `@Controller` marks a Spring MVC request handler (`@RestController` = `@Controller` + `@ResponseBody`). `@Service` adds no extra behaviour; it expresses business-layer intent.",points:["All four are detected by component scanning","@Controller / @RestController \u2014 web layer, handles HTTP requests","@Service \u2014 business logic layer","@Repository \u2014 data access layer, adds exception translation","Spring Data JPA repository interfaces don't need @Repository \u2014 they are detected automatically","Using the right stereotype makes layers clear and lets AOP pointcuts target them"],code:`@RestController            // web layer
class ProductController { }

@Service                   // business logic
class ProductService { }

@Repository                // data access + exception translation
class ProductJdbcDao { }

@Component                 // generic helper bean
class PriceFormatter { }`},{id:"sp-6",level:"junior",topic:"spring",difficulty:"medium",simple:{hi:"Class mein do monitor hain. Teacher bolti hai 'monitor ko bulao' toh head monitor (@Primary) aata hai. Agar teacher naam se bulaye \u2014 'Riya ko bulao' (@Qualifier) \u2014 toh Riya hi aati hai.",en:"There are two monitors in class. When the teacher says 'call the monitor', the head monitor (@Primary) comes. If she calls by name \u2014 'call Riya' (@Qualifier) \u2014 then Riya comes.",bn:"\u0995\u09CD\u09B2\u09BE\u09B8\u09C7 \u09A6\u09C1\u099C\u09A8 \u09AE\u09A8\u09BF\u099F\u09B0 \u0986\u099B\u09C7\u0964 \u099F\u09BF\u099A\u09BE\u09B0 \u09AF\u0996\u09A8 \u09AC\u09B2\u09C7\u09A8 '\u09AE\u09A8\u09BF\u099F\u09B0\u0995\u09C7 \u09A1\u09BE\u0995\u09CB', \u09A4\u0996\u09A8 \u09B9\u09C7\u09A1 \u09AE\u09A8\u09BF\u099F\u09B0 (@Primary) \u0986\u09B8\u09C7\u0964 \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09A8\u09BE\u09AE \u09A7\u09B0\u09C7 \u09A1\u09BE\u0995\u09B2\u09C7 \u2014 '\u09B0\u09BF\u09AF\u09BC\u09BE\u0995\u09C7 \u09A1\u09BE\u0995\u09CB' (@Qualifier) \u2014 \u09A4\u0996\u09A8 \u09B0\u09BF\u09AF\u09BC\u09BE\u0987 \u0986\u09B8\u09C7\u0964"},question:"How do @Autowired, @Qualifier and @Primary work when there are multiple beans of the same type?",answer:'`@Autowired` asks Spring to inject a dependency by type (it is optional on a single constructor). If more than one bean of that type exists, Spring throws `NoUniqueBeanDefinitionException` unless it can decide: `@Primary` marks the default bean to choose, and `@Qualifier("name")` at the injection point picks a specific bean by qualifier or bean name. `@Qualifier` takes precedence over `@Primary`. You can also inject `List<PaymentGateway>` or `Map<String, PaymentGateway>` to get all implementations.',points:["Injection is by type first, then narrowed by qualifier","@Primary = default choice; @Qualifier = explicit choice at the injection point","@Qualifier wins over @Primary","As a fallback, Spring matches the parameter name against bean names","Inject List/Map of an interface to implement strategy patterns","Optional dependencies: ObjectProvider<T> or @Autowired(required = false)"],code:`public interface PaymentGateway { void pay(long paise); }

@Component
@Primary
class UpiGateway implements PaymentGateway { public void pay(long paise) { } }

@Component("card")
class CardGateway implements PaymentGateway { public void pay(long paise) { } }

@Service
class CheckoutService {
    private final PaymentGateway defaultGateway;
    private final PaymentGateway cardGateway;

    CheckoutService(PaymentGateway defaultGateway,
                    @Qualifier("card") PaymentGateway cardGateway) {
        this.defaultGateway = defaultGateway; // UpiGateway (@Primary)
        this.cardGateway = cardGateway;       // CardGateway (@Qualifier)
    }
}`},{id:"sp-7",level:"mid",topic:"spring",difficulty:"medium",simple:{hi:"Starter ek instant noodles packet jaisa hai \u2014 noodles aur masala ek saath. Auto-configuration ek smart maa jaisi hai: dekhti hai kitchen mein kya hai, aur agar tumne khud kuch nahi banaya toh default khana bana deti hai.",en:"A starter is like an instant noodles packet \u2014 noodles and masala together. Auto-configuration is like a smart mother: she checks what is in the kitchen, and if you haven't cooked anything yourself, she makes the default meal.",bn:"Starter \u09B9\u09B2\u09CB \u0987\u09A8\u09B8\u09CD\u099F\u09CD\u09AF\u09BE\u09A8\u09CD\u099F \u09A8\u09C1\u09A1\u09B2\u09B8\u09C7\u09B0 \u09AA\u09CD\u09AF\u09BE\u0995\u09C7\u099F\u09C7\u09B0 \u09AE\u09A4\u09CB \u2014 \u09A8\u09C1\u09A1\u09B2\u09B8 \u0986\u09B0 \u09AE\u09B6\u09B2\u09BE \u098F\u0995\u09B8\u0999\u09CD\u0997\u09C7\u0964 Auto-configuration \u09B9\u09B2\u09CB \u098F\u0995 \u09AC\u09C1\u09A6\u09CD\u09A7\u09BF\u09AE\u09BE\u09A8 \u09AE\u09BE\u09AF\u09BC\u09C7\u09B0 \u09AE\u09A4\u09CB: \u09B0\u09BE\u09A8\u09CD\u09A8\u09BE\u0998\u09B0\u09C7 \u0995\u09C0 \u0986\u099B\u09C7 \u09A6\u09C7\u0996\u09C7 \u09A8\u09C7\u09A8, \u0986\u09B0 \u09A4\u09C1\u09AE\u09BF \u09A8\u09BF\u099C\u09C7 \u0995\u09BF\u099B\u09C1 \u09A8\u09BE \u09AC\u09BE\u09A8\u09BE\u09B2\u09C7 \u09A1\u09BF\u09AB\u09B2\u09CD\u099F \u0996\u09BE\u09AC\u09BE\u09B0 \u09AC\u09BE\u09A8\u09BF\u09AF\u09BC\u09C7 \u09A6\u09C7\u09A8\u0964"},question:"How do Spring Boot starters and auto-configuration work?",answer:"Starters are curated dependency bundles \u2014 for example `spring-boot-starter-web` brings Spring MVC, Jackson and embedded Tomcat \u2014 with compatible versions managed by Spring Boot's dependency management (BOM). Auto-configuration is a set of `@AutoConfiguration` classes that Boot loads (in Boot 3 they are listed in `META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports`) and that apply only when their conditions match: `@ConditionalOnClass`, `@ConditionalOnMissingBean`, `@ConditionalOnProperty` and so on. Because of `@ConditionalOnMissingBean`, defining your own bean makes the default back off. Run with `--debug` to see the conditions evaluation report, and exclude a configuration with `@SpringBootApplication(exclude = ...)`.",points:["Starter = dependencies only; auto-configuration = conditional @Configuration classes","Classpath + properties + existing beans decide what gets configured","Your own bean overrides the default thanks to @ConditionalOnMissingBean","Boot 3 uses AutoConfiguration.imports; Boot 2 used spring.factories","--debug or the Actuator conditions endpoint explains why something was (not) configured","You can write your own starter for shared company libraries"],code:`@AutoConfiguration
@ConditionalOnClass(SmsClient.class)
@EnableConfigurationProperties(SmsProperties.class)
public class SmsAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean            // backs off if the app defines its own SmsClient
    @ConditionalOnProperty(prefix = "sms", name = "enabled", havingValue = "true")
    SmsClient smsClient(SmsProperties props) {
        return new SmsClient(props.apiKey());
    }
}

// src/main/resources/META-INF/spring/
//   org.springframework.boot.autoconfigure.AutoConfiguration.imports
// com.example.sms.SmsAutoConfiguration`},{id:"sp-8",level:"fresher",topic:"spring",difficulty:"easy",simple:{hi:"@SpringBootApplication school ki ek ghanti jaisa hai \u2014 ek baar bajao toh teen kaam ho jaate hain: attendance (scan), timetable set (configuration) aur saari classes shuru (auto-configuration).",en:"@SpringBootApplication is like one school bell \u2014 ring it once and three things happen: attendance (scan), timetable setup (configuration), and all classes start (auto-configuration).",bn:"@SpringBootApplication \u09B9\u09B2\u09CB \u09B8\u09CD\u0995\u09C1\u09B2\u09C7\u09B0 \u098F\u0995\u099F\u09BE \u0998\u09A3\u09CD\u099F\u09BE\u09B0 \u09AE\u09A4\u09CB \u2014 \u098F\u0995\u09AC\u09BE\u09B0 \u09AC\u09BE\u099C\u09BE\u09B2\u09C7\u0987 \u09A4\u09BF\u09A8\u099F\u09C7 \u0995\u09BE\u099C \u09B9\u09AF\u09BC: \u09B9\u09BE\u099C\u09BF\u09B0\u09BE (scan), \u09B0\u09C1\u099F\u09BF\u09A8 \u09A0\u09BF\u0995 \u0995\u09B0\u09BE (configuration), \u0986\u09B0 \u09B8\u09AC \u0995\u09CD\u09B2\u09BE\u09B8 \u09B6\u09C1\u09B0\u09C1 (auto-configuration)\u0964"},question:"What does @SpringBootApplication do?",answer:"It is a convenience annotation that combines `@SpringBootConfiguration` (a specialised `@Configuration`), `@EnableAutoConfiguration` and `@ComponentScan`. Component scanning starts from the package of the annotated class and covers its sub-packages, so the main class should sit in the root package; beans outside it are not found unless you set `scanBasePackages`. `SpringApplication.run()` then creates the ApplicationContext and starts the embedded server.",points:["= @SpringBootConfiguration + @EnableAutoConfiguration + @ComponentScan","Put the main class in the root package (e.g. com.example.shop)","Classes in sibling/parent packages are not scanned by default","exclude / excludeName turn off specific auto-configurations","The main class can also declare @Bean methods because it is a configuration class"],code:`package com.example.shop;   // root package: scans com.example.shop.**

@SpringBootApplication(exclude = DataSourceAutoConfiguration.class)
public class ShopApplication {
    public static void main(String[] args) {
        SpringApplication.run(ShopApplication.class, args);
    }
}`},{id:"sp-9",level:"fresher",topic:"spring",difficulty:"easy",simple:{hi:"Profiles school ke kapdon jaise hain: weekdays ke liye uniform (prod), sports day ke liye tracksuit (dev). Bachcha wahi hai, bas din ke hisaab se kapde badalte hain.",en:"Profiles are like school clothes: the regular uniform for weekdays (prod), a tracksuit for sports day (dev). The child is the same; only the clothes change by the day.",bn:"Profiles \u09B9\u09B2\u09CB \u09B8\u09CD\u0995\u09C1\u09B2\u09C7\u09B0 \u09AA\u09CB\u09B6\u09BE\u0995\u09C7\u09B0 \u09AE\u09A4\u09CB: \u09B8\u09AA\u09CD\u09A4\u09BE\u09B9\u09C7\u09B0 \u09A6\u09BF\u09A8\u09C7 \u0987\u0989\u09A8\u09BF\u09AB\u09B0\u09CD\u09AE (prod), \u09B8\u09CD\u09AA\u09CB\u09B0\u09CD\u099F\u09B8 \u09A1\u09C7-\u09A4\u09C7 \u099F\u09CD\u09B0\u09CD\u09AF\u09BE\u0995\u09B8\u09C1\u099F (dev)\u0964 \u099B\u09BE\u09A4\u09CD\u09B0 \u098F\u0995\u0987, \u09B6\u09C1\u09A7\u09C1 \u09A6\u09BF\u09A8 \u0985\u09A8\u09C1\u09AF\u09BE\u09AF\u09BC\u09C0 \u09AA\u09CB\u09B6\u09BE\u0995 \u09AC\u09A6\u09B2\u09BE\u09AF\u09BC\u0964"},question:"How do application.properties / application.yml and profiles work in Spring Boot?",answer:'Spring Boot reads configuration from `application.properties` or `application.yml`, plus environment variables, command-line arguments and other sources. Profiles let you keep environment-specific values in files like `application-dev.yml` and `application-prod.yml` (or profile sections in one YAML), activated with `spring.profiles.active=prod` or the env variable `SPRING_PROFILES_ACTIVE`. Profile-specific values override the default file, and command-line arguments and environment variables override both. `@Profile("dev")` registers a bean only when that profile is active.',points:["properties = key=value; YAML = hierarchical, supports multiple documents with ---","application-{profile}.yml overrides application.yml","Command-line args > env variables > config files (roughly)","Env variables use relaxed binding: SPRING_DATASOURCE_URL \u2192 spring.datasource.url","@Profile on beans/configs; never commit real secrets \u2014 use env vars or a vault"],code:`# application.yml
server:
  port: 8080
spring:
  datasource:
    url: jdbc:postgresql://localhost:5432/shop
---
spring:
  config:
    activate:
      on-profile: prod
  datasource:
    url: jdbc:postgresql://prod-db:5432/shop
    password: \${DB_PASSWORD}

# run: java -jar shop.jar --spring.profiles.active=prod`},{id:"sp-10",level:"junior",topic:"spring",difficulty:"medium",simple:{hi:"@Value ek ek cheez alag alag maangne jaisa hai \u2014 'ek pen do', 'ek pencil do'. @ConfigurationProperties poora geometry box ek saath lene jaisa hai \u2014 sab cheezein ek set mein.",en:"@Value is like asking for things one by one \u2014 'give me a pen', 'give me a pencil'. @ConfigurationProperties is like taking the whole geometry box at once, everything together in one set.",bn:"@Value \u09AE\u09BE\u09A8\u09C7 \u098F\u0995\u099F\u09BE \u098F\u0995\u099F\u09BE \u0995\u09B0\u09C7 \u099C\u09BF\u09A8\u09BF\u09B8 \u099A\u09BE\u0993\u09AF\u09BC\u09BE \u2014 '\u098F\u0995\u099F\u09BE \u09AA\u09C7\u09A8 \u09A6\u09BE\u0993', '\u098F\u0995\u099F\u09BE \u09AA\u09C7\u09A8\u09CD\u09B8\u09BF\u09B2 \u09A6\u09BE\u0993'\u0964 @ConfigurationProperties \u09AE\u09BE\u09A8\u09C7 \u09AA\u09C1\u09B0\u09CB \u099C\u09CD\u09AF\u09BE\u09AE\u09BF\u09A4\u09BF \u09AC\u09BE\u0995\u09CD\u09B8\u099F\u09BE \u098F\u0995\u09B8\u0999\u09CD\u0997\u09C7 \u09A8\u09C7\u0993\u09AF\u09BC\u09BE, \u09B8\u09AC \u099C\u09BF\u09A8\u09BF\u09B8 \u098F\u0995 \u09B8\u09C7\u099F\u09C7\u0964"},question:"What is @ConfigurationProperties and how is it different from @Value?",answer:'`@ConfigurationProperties(prefix = "app.mail")` binds a group of related properties into a type-safe object (a record or class). It supports relaxed binding (`retry-count` or `RETRY_COUNT` \u2192 `retryCount`), nested objects, lists and maps, conversion to types like `Duration` and `DataSize`, and Bean Validation with `@Validated`. `@Value("${app.mail.host}")` injects a single value and supports SpEL, but values end up scattered and unvalidated. Register properties classes with `@EnableConfigurationProperties` or `@ConfigurationPropertiesScan`.',points:["Use @ConfigurationProperties for groups of settings, @Value for one-off values","Records work with constructor binding \u2014 immutable configuration","@Validated fails startup early on bad configuration","IDE auto-completion via spring-boot-configuration-processor","Duration '5s' and DataSize '10MB' are converted automatically"],code:`@ConfigurationProperties(prefix = "app.mail")
@Validated
public record MailProperties(
        @NotBlank String host,
        int port,
        Duration timeout) { }

@SpringBootApplication
@ConfigurationPropertiesScan
public class ShopApplication { }

// application.yml
// app:
//   mail:
//     host: smtp.example.com
//     port: 587
//     timeout: 5s`},{id:"sp-11",level:"fresher",topic:"spring",difficulty:"easy",simple:{hi:"@PathVariable ghar ka address hai \u2014 'Flat 42' \u2014 ek exact ghar batata hai. @RequestParam ek filter hai \u2014 'Pune mein rehne wale sab log'. ResponseEntity courier ki receipt jaisa hai jisme parcel ke saath status bhi likha hota hai.",en:"@PathVariable is a house address \u2014 'Flat 42' \u2014 it points to one exact house. @RequestParam is a filter \u2014 'everyone living in Pune'. ResponseEntity is like a courier receipt that carries the status along with the parcel.",bn:"@PathVariable \u09B9\u09B2\u09CB \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u09A0\u09BF\u0995\u09BE\u09A8\u09BE \u2014 '\u09AB\u09CD\u09B2\u09CD\u09AF\u09BE\u099F 42' \u2014 \u098F\u0995\u099F\u09BE \u09A8\u09BF\u09B0\u09CD\u09A6\u09BF\u09B7\u09CD\u099F \u09AC\u09BE\u09A1\u09BC\u09BF \u09A6\u09C7\u0996\u09BE\u09AF\u09BC\u0964 @RequestParam \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE \u09AB\u09BF\u09B2\u09CD\u099F\u09BE\u09B0 \u2014 '\u09AA\u09C1\u09A8\u09C7\u09A4\u09C7 \u09A5\u09BE\u0995\u09BE \u09B8\u09AC\u09BE\u0987'\u0964 ResponseEntity \u09B9\u09B2\u09CB \u0995\u09C1\u09B0\u09BF\u09AF\u09BC\u09BE\u09B0\u09C7\u09B0 \u09B0\u09B8\u09BF\u09A6\u09C7\u09B0 \u09AE\u09A4\u09CB, \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 \u09AA\u09BE\u09B0\u09CD\u09B8\u09C7\u09B2\u09C7\u09B0 \u09B8\u0999\u09CD\u0997\u09C7 \u09B8\u09CD\u099F\u09CD\u09AF\u09BE\u099F\u09BE\u09B8\u0993 \u09B2\u09C7\u0996\u09BE \u09A5\u09BE\u0995\u09C7\u0964"},question:"How do you build a REST API with @RestController? What is the difference between @PathVariable and @RequestParam, and why use ResponseEntity?",answer:"`@RestController` is `@Controller` + `@ResponseBody`, so return values are serialised to JSON by Jackson. Handlers are mapped with `@GetMapping`, `@PostMapping`, `@PutMapping`, `@PatchMapping` and `@DeleteMapping` (shortcuts for `@RequestMapping`). `@PathVariable` reads a segment of the URL path that identifies a resource (`/users/42`), while `@RequestParam` reads query parameters used for filtering, sorting or paging (`/users?city=Pune`). `ResponseEntity` lets you control the status code, headers and body \u2014 for example `201 Created` with a Location header or `404 Not Found`.",points:["@RestController = @Controller + @ResponseBody","@PathVariable \u2192 identifies a resource; @RequestParam \u2192 filters/options, can be optional with defaultValue","@RequestBody maps the JSON request body to an object","ResponseEntity controls status + headers + body","Use proper HTTP verbs and status codes (200, 201, 204, 400, 404)"],code:`@RestController
@RequestMapping("/api/users")
public class UserController {
    private final UserService service;
    public UserController(UserService service) { this.service = service; }

    @GetMapping("/{id}")                                   // GET /api/users/42
    public ResponseEntity<UserDto> get(@PathVariable Long id) {
        return service.findById(id)                        // Optional<UserDto>
                .map(ResponseEntity::ok)
                .orElse(ResponseEntity.notFound().build());
    }

    @GetMapping                                            // GET /api/users?city=Pune
    public List<UserDto> search(@RequestParam(defaultValue = "Pune") String city) {
        return service.findByCity(city);
    }

    @PostMapping
    public ResponseEntity<UserDto> create(@Valid @RequestBody CreateUserRequest req) {
        UserDto saved = service.create(req);
        return ResponseEntity.created(URI.create("/api/users/" + saved.id())).body(saved);
    }
}`},{id:"sp-12",level:"junior",topic:"spring",difficulty:"medium",simple:{hi:"ControllerAdvice school ke sick room jaisa hai \u2014 kisi bhi class mein bachcha gire, sab ko ek hi jagah le jaate hain aur ek hi tarike se first-aid milta hai.",en:"ControllerAdvice is like the school sick room \u2014 whichever class a child falls in, everyone is taken to the same place and gets first-aid the same way.",bn:"ControllerAdvice \u09B9\u09B2\u09CB \u09B8\u09CD\u0995\u09C1\u09B2\u09C7\u09B0 \u09B8\u09BF\u0995 \u09B0\u09C1\u09AE\u09C7\u09B0 \u09AE\u09A4\u09CB \u2014 \u09AF\u09C7 \u0995\u09CD\u09B2\u09BE\u09B8\u09C7\u0987 \u0995\u09CB\u09A8\u09CB \u09AC\u09BE\u099A\u09CD\u099A\u09BE \u09AA\u09A1\u09BC\u09C7 \u09AF\u09BE\u0995, \u09B8\u09AC\u09BE\u0987\u0995\u09C7 \u098F\u0995\u0987 \u099C\u09BE\u09AF\u09BC\u0997\u09BE\u09AF\u09BC \u09A8\u09BF\u09AF\u09BC\u09C7 \u09AF\u09BE\u0993\u09AF\u09BC\u09BE \u09B9\u09AF\u09BC \u0986\u09B0 \u098F\u0995\u0987\u09AD\u09BE\u09AC\u09C7 \u09AB\u09BE\u09B0\u09CD\u09B8\u09CD\u099F-\u098F\u0987\u09A1 \u09A6\u09C7\u0993\u09AF\u09BC\u09BE \u09B9\u09AF\u09BC\u0964"},question:"How do you implement global exception handling in Spring Boot with @ControllerAdvice?",answer:"`@RestControllerAdvice` (`@ControllerAdvice` + `@ResponseBody`) is a global component whose `@ExceptionHandler` methods handle exceptions thrown from any controller, so you return one consistent error format instead of try/catch in every endpoint. Spring 6 supports the RFC 9457 `ProblemDetail` type as a standard error body, and you can extend `ResponseEntityExceptionHandler` to customise how Spring MVC's built-in exceptions are rendered. Map domain exceptions to proper HTTP statuses (404, 409, 400) and never leak stack traces to clients.",points:["@ExceptionHandler in a controller = local; in @ControllerAdvice = global","The most specific exception handler wins","ProblemDetail gives a standard JSON shape (type, title, status, detail, instance)","spring.mvc.problemdetails.enabled=true makes built-in MVC errors use ProblemDetail","Log the full error server-side; return a safe message to the client","@ControllerAdvice can be limited with basePackages or annotations"],code:`@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(UserNotFoundException.class)
    public ProblemDetail handleNotFound(UserNotFoundException ex) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());
        pd.setTitle("User not found");
        return pd;
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String, String>> handleValidation(MethodArgumentNotValidException ex) {
        Map<String, String> errors = new HashMap<>();
        ex.getBindingResult().getFieldErrors()
          .forEach(e -> errors.put(e.getField(), e.getDefaultMessage()));
        return ResponseEntity.badRequest().body(errors);
    }

    @ExceptionHandler(Exception.class)
    public ProblemDetail handleOther(Exception ex) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.INTERNAL_SERVER_ERROR, "Something went wrong");
    }
}`},{id:"sp-13",level:"junior",topic:"spring",difficulty:"medium",simple:{hi:"Validation railway ke ticket checker jaisa hai \u2014 train mein chadhne se pehle ticket, naam aur umar check karta hai. Galat ticket ho toh gate pe hi rok deta hai (400), andar jaane hi nahi deta.",en:"Validation is like the railway ticket checker \u2014 before you board, he checks ticket, name and age. A wrong ticket is stopped right at the gate (400); you never get inside.",bn:"Validation \u09B9\u09B2\u09CB \u09B0\u09C7\u09B2\u09C7\u09B0 \u099F\u09BF\u0995\u09BF\u099F \u099A\u09C7\u0995\u09BE\u09B0\u09C7\u09B0 \u09AE\u09A4\u09CB \u2014 \u099F\u09CD\u09B0\u09C7\u09A8\u09C7 \u0993\u09A0\u09BE\u09B0 \u0986\u0997\u09C7\u0987 \u099F\u09BF\u0995\u09BF\u099F, \u09A8\u09BE\u09AE, \u09AC\u09AF\u09BC\u09B8 \u09A6\u09C7\u0996\u09C7 \u09A8\u09C7\u09A8\u0964 \u09AD\u09C1\u09B2 \u099F\u09BF\u0995\u09BF\u099F \u09B9\u09B2\u09C7 \u0997\u09C7\u099F\u09C7\u0987 \u0986\u099F\u0995\u09C7 \u09A6\u09C7\u09A8 (400), \u09AD\u09C7\u09A4\u09B0\u09C7 \u09A2\u09C1\u0995\u09A4\u09C7\u0987 \u09A6\u09C7\u09A8 \u09A8\u09BE\u0964"},question:"How do you validate request data in Spring Boot?",answer:"Add `spring-boot-starter-validation` (Jakarta Bean Validation with Hibernate Validator). Put constraints such as `@NotBlank`, `@Email`, `@Size`, `@Min` and `@Positive` on DTO fields and annotate the `@RequestBody` parameter with `@Valid`; invalid input throws `MethodArgumentNotValidException`, which Spring turns into a 400 Bad Request that you can customise in `@ControllerAdvice`. Use `@Valid` on nested objects to cascade, `@Validated` on a bean class to validate method parameters, and validation groups when create and update rules differ. Custom rules are a constraint annotation plus a `ConstraintValidator`.",points:["The validation starter is not included in spring-boot-starter-web \u2014 add it","@Valid on @RequestBody triggers validation \u2192 400 on failure","@Valid on a nested field cascades validation","@Validated supports groups and method-level validation","Custom constraint = @Constraint annotation + ConstraintValidator","Validate at the API boundary but still keep DB constraints"],code:`public record CreateUserRequest(
        @NotBlank @Size(max = 50) String name,
        @NotBlank @Email String email,
        @Min(18) int age,
        @Valid @NotNull AddressDto address) { }

public record AddressDto(@NotBlank String city, @Pattern(regexp = "\\\\d{6}") String pincode) { }

@PostMapping("/api/users")
public ResponseEntity<UserDto> create(@Valid @RequestBody CreateUserRequest req) {
    return ResponseEntity.status(HttpStatus.CREATED).body(service.create(req));
}
// invalid body -> MethodArgumentNotValidException -> 400 Bad Request`},{id:"sp-14",level:"junior",topic:"spring",difficulty:"medium",simple:{hi:"Derived query dukaan wale bhaiya ko seedha bolne jaisa hai: 'findByColourAndSize' \u2014 'laal rang ki medium size shirt dikhao'. Naam sunte hi wo samajh jaate hain kya dhoondhna hai, tumhe SQL likhne ki zaroorat nahi.",en:"A derived query is like telling the shopkeeper directly: 'findByColourAndSize' \u2014 'show me a red shirt in medium size'. He understands just from the words; you don't need to write SQL.",bn:"Derived query \u09AE\u09BE\u09A8\u09C7 \u09A6\u09CB\u0995\u09BE\u09A8\u09A6\u09BE\u09B0\u0995\u09C7 \u09B8\u09B0\u09BE\u09B8\u09B0\u09BF \u09AC\u09B2\u09BE: 'findByColourAndSize' \u2014 '\u09B2\u09BE\u09B2 \u09B0\u0999\u09C7\u09B0 \u09AE\u09BF\u09A1\u09BF\u09AF\u09BC\u09BE\u09AE \u09B8\u09BE\u0987\u099C\u09C7\u09B0 \u09B6\u09BE\u09B0\u09CD\u099F \u09A6\u09C7\u0996\u09BE\u09A8'\u0964 \u09A8\u09BE\u09AE \u09B6\u09C1\u09A8\u09C7\u0987 \u0989\u09A8\u09BF \u09AC\u09C1\u099D\u09C7 \u09AF\u09BE\u09A8 \u0995\u09C0 \u0996\u09C1\u0981\u099C\u09A4\u09C7 \u09B9\u09AC\u09C7, \u09A4\u09CB\u09AE\u09BE\u0995\u09C7 SQL \u09B2\u09BF\u0996\u09A4\u09C7 \u09B9\u09AF\u09BC \u09A8\u09BE\u0964"},question:"How do Spring Data JPA repositories and derived query methods work?",answer:"You declare an interface extending `JpaRepository<Entity, ID>` and Spring Data generates the implementation at runtime, giving CRUD, paging and sorting (`save`, `findById`, `findAll(Pageable)`, `deleteById`). Derived query methods are parsed from the method name \u2014 `findByEmail`, `findByCityAndAgeGreaterThan`, `countByStatus`, `existsByEmail`, `findTop5ByOrderByCreatedAtDesc` \u2014 and turned into JPQL. For complex queries use `@Query` with JPQL or `nativeQuery = true`, plus `@Modifying` for update/delete queries. Return types can be `Optional`, `List`, `Page`, `Slice`, `Stream` or projections (interfaces or records).",points:["JpaRepository extends ListCrudRepository + ListPagingAndSortingRepository","Keywords: And, Or, Between, LessThan, Like, Containing, In, IsNull, OrderBy, Top/First","Method names are validated at startup \u2014 a typo fails fast","@Query for long or complex queries instead of very long method names","@Modifying queries need a transaction (@Transactional on the caller or method)","Pageable + Page<T> for pagination; projections to fetch only needed columns"],code:`public interface UserRepository extends JpaRepository<User, Long> {

    Optional<User> findByEmail(String email);

    List<User> findByCityAndAgeGreaterThanOrderByNameAsc(String city, int age);

    boolean existsByEmail(String email);

    Page<User> findByStatus(UserStatus status, Pageable pageable);

    @Query("select u from User u where lower(u.name) like lower(concat('%', :q, '%'))")
    List<User> search(@Param("q") String q);

    @Modifying
    @Query("update User u set u.status = :status where u.lastLogin < :before")
    int deactivateInactive(@Param("status") UserStatus status,
                           @Param("before") LocalDateTime before);
}`},{id:"sp-15",level:"mid",topic:"spring",difficulty:"medium",simple:{hi:"Entity states school admission jaise hain: form bhara par jama nahi kiya (transient), school ke register mein naam aa gaya aur teacher sab notice karti hai (managed), school chhod diya par ID card abhi bhi paas hai (detached), aur TC le liya (removed).",en:"Entity states are like school admission: form filled but not submitted (transient), name in the school register so teachers notice everything (managed), left school but still holding the ID card (detached), and took the TC (removed).",bn:"Entity states \u09B9\u09B2\u09CB \u09B8\u09CD\u0995\u09C1\u09B2\u09C7 \u09AD\u09B0\u09CD\u09A4\u09BF\u09B0 \u09AE\u09A4\u09CB: \u09AB\u09B0\u09CD\u09AE \u09AD\u09B0\u09BE \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u099C\u09AE\u09BE \u09B9\u09AF\u09BC\u09A8\u09BF (transient), \u09B8\u09CD\u0995\u09C1\u09B2\u09C7\u09B0 \u09B0\u09C7\u099C\u09BF\u09B8\u09CD\u099F\u09BE\u09B0\u09C7 \u09A8\u09BE\u09AE \u0989\u09A0\u09C7\u099B\u09C7 \u2014 \u099F\u09BF\u099A\u09BE\u09B0 \u09B8\u09AC \u0996\u09C7\u09AF\u09BC\u09BE\u09B2 \u09B0\u09BE\u0996\u09C7\u09A8 (managed), \u09B8\u09CD\u0995\u09C1\u09B2 \u099B\u09C7\u09A1\u09BC\u09C7\u099B \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0986\u0987\u09A1\u09BF \u0995\u09BE\u09B0\u09CD\u09A1 \u098F\u0996\u09A8\u09CB \u0995\u09BE\u099B\u09C7 (detached), \u0986\u09B0 \u099F\u09BF\u09B8\u09BF \u09A8\u09BF\u09AF\u09BC\u09C7 \u09A8\u09BF\u09AF\u09BC\u09C7\u099B (removed)\u0964"},question:"What are the Hibernate / JPA entity states?",answer:"Transient: a new object not associated with any persistence context and with no database row (`new User()`). Managed (persistent): attached to the current persistence context after `persist`, `find` or a query \u2014 Hibernate tracks it, and dirty checking writes changes automatically at flush/commit without calling save. Detached: it was managed but the persistence context closed (or `detach`/`clear` was called), so changes are no longer tracked until you `merge` it, which copies its state onto a managed instance and returns that instance. Removed: scheduled for deletion with `remove`, deleted on flush.",points:["Transient \u2192 persist \u2192 Managed \u2192 (context closes) \u2192 Detached \u2192 merge \u2192 Managed","Dirty checking only works for managed entities inside a transaction","merge returns a different, managed object \u2014 use the returned one","Spring Data save() calls persist for new entities and merge for existing ones","The persistence context is a first-level cache: same id \u2192 same object within it","Accessing lazy associations on a detached entity \u2192 LazyInitializationException"],code:`@Service
public class UserStateDemo {
    @PersistenceContext private EntityManager em;

    @Transactional
    public Long create() {
        User u = new User("Asha");          // transient
        em.persist(u);                      // managed
        u.setName("Asha Rao");              // dirty checking: UPDATE at flush, no save() call
        return u.getId();
    }                                       // commit -> context closes -> u is detached

    @Transactional
    public User rename(User detached, String name) {
        detached.setName(name);             // not tracked yet
        return em.merge(detached);          // state copied to a managed instance
    }

    @Transactional
    public void delete(Long id) {
        em.remove(em.find(User.class, id)); // removed -> DELETE at flush
    }
}`},{id:"sp-16",level:"mid",topic:"spring",difficulty:"medium",simple:{hi:"Lazy loading aisa hai jaise thali mein sabzi tabhi aaye jab maango. N+1 problem: 10 dost restaurant mein hain aur waiter har ek ki roti ke liye alag chakkar lagata hai \u2014 1 + 10 trips. JOIN FETCH matlab ek hi baar mein sab ki roti ek bade plate mein le aao.",en:"Lazy loading is like getting sabzi on your thali only when you ask. The N+1 problem: 10 friends at a restaurant and the waiter makes a separate trip for each person's roti \u2014 1 + 10 trips. JOIN FETCH means bringing everyone's roti on one big plate in one trip.",bn:"Lazy loading \u09AE\u09BE\u09A8\u09C7 \u09A5\u09BE\u09B2\u09BE\u09AF\u09BC \u09A4\u09B0\u0995\u09BE\u09B0\u09BF \u09A4\u0996\u09A8\u0987 \u0986\u09B8\u09C7 \u09AF\u0996\u09A8 \u099A\u09BE\u0993\u0964 N+1 problem: \u09B0\u09C7\u09B8\u09CD\u099F\u09C1\u09B0\u09C7\u09A8\u09CD\u099F\u09C7 10 \u099C\u09A8 \u09AC\u09A8\u09CD\u09A7\u09C1, \u0986\u09B0 \u0993\u09AF\u09BC\u09C7\u099F\u09BE\u09B0 \u09AA\u09CD\u09B0\u09A4\u09CD\u09AF\u09C7\u0995\u09C7\u09B0 \u09B0\u09C1\u099F\u09BF\u09B0 \u099C\u09A8\u09CD\u09AF \u0986\u09B2\u09BE\u09A6\u09BE \u0986\u09B2\u09BE\u09A6\u09BE \u09AF\u09BE\u09A4\u09BE\u09AF\u09BC\u09BE\u09A4 \u0995\u09B0\u09C7 \u2014 1 + 10 \u09AC\u09BE\u09B0\u0964 JOIN FETCH \u09AE\u09BE\u09A8\u09C7 \u098F\u0995\u09AC\u09BE\u09B0\u09C7\u0987 \u09B8\u09AC\u09BE\u09B0 \u09B0\u09C1\u099F\u09BF \u098F\u0995\u099F\u09BE \u09AC\u09A1\u09BC \u09AA\u09CD\u09B2\u09C7\u099F\u09C7 \u09A8\u09BF\u09AF\u09BC\u09C7 \u0986\u09B8\u09BE\u0964"},question:"What is the difference between lazy and eager fetching, and what is the N+1 problem?",answer:"`FetchType.LAZY` loads an association only when it is first accessed (through a proxy or lazy collection), while `EAGER` loads it together with the parent. JPA defaults are `@OneToMany`/`@ManyToMany` = LAZY and `@ManyToOne`/`@OneToOne` = EAGER; best practice is to make every association LAZY and fetch what each use case needs. The N+1 problem is 1 query to load N parents plus N extra queries to load each parent's association, typically when you loop over results and touch a lazy relation (EAGER on queries can cause it too). Fix it with `JOIN FETCH`, `@EntityGraph`, batch fetching (`@BatchSize` / `hibernate.default_batch_fetch_size`) or DTO projections.",points:["LAZY = load on access; EAGER = load always","Set @ManyToOne(fetch = LAZY) explicitly \u2014 its default is EAGER","EAGER is not a fix for N+1; it often makes it worse and can't be turned off per query","N+1 = 1 query for parents + N queries for children","Fixes: JOIN FETCH, @EntityGraph, batch fetching, DTO projections","Detect it by logging SQL / counting queries per request"],code:`@Entity
@Table(name = "orders")
public class Order {
    @Id @GeneratedValue private Long id;
    private OrderStatus status;

    @ManyToOne(fetch = FetchType.LAZY)     // override the EAGER default
    private Customer customer;

    @OneToMany(mappedBy = "order")         // LAZY by default
    private List<OrderItem> items = new ArrayList<>();
}

public interface OrderRepository extends JpaRepository<Order, Long> {
    // N+1: findAll() and then order.getCustomer().getName() inside a loop
    @Query("select o from Order o join fetch o.customer where o.status = :status")
    List<Order> findWithCustomer(@Param("status") OrderStatus status);

    @EntityGraph(attributePaths = {"customer", "items"})
    List<Order> findByStatus(OrderStatus status);
}`},{id:"sp-17",level:"mid",topic:"spring",difficulty:"hard",simple:{hi:"Transaction UPI payment jaisa hai \u2014 paisa ya toh poora jaayega aur pahunchega, ya bilkul nahi; beech mein atka nahi rahega. REQUIRES_NEW bank ke alag register jaisa hai jisme entry hamesha likhi jaati hai, chahe payment fail ho jaaye.",en:"A transaction is like a UPI payment \u2014 the money either goes and arrives completely, or not at all; it never gets stuck halfway. REQUIRES_NEW is like the bank's separate register where the entry is always written, even if the payment fails.",bn:"Transaction \u09B9\u09B2\u09CB UPI \u09AA\u09C7\u09AE\u09C7\u09A8\u09CD\u099F\u09C7\u09B0 \u09AE\u09A4\u09CB \u2014 \u099F\u09BE\u0995\u09BE \u09B9\u09AF\u09BC \u09AA\u09C1\u09B0\u09CB\u099F\u09BE \u09AF\u09BE\u09AC\u09C7 \u0986\u09B0 \u09AA\u09CC\u0981\u099B\u09BE\u09AC\u09C7, \u09A8\u09AF\u09BC\u09A4\u09CB \u098F\u0995\u09A6\u09AE\u0987 \u09AF\u09BE\u09AC\u09C7 \u09A8\u09BE; \u09AE\u09BE\u099D\u09AA\u09A5\u09C7 \u0986\u099F\u0995\u09C7 \u09A5\u09BE\u0995\u09AC\u09C7 \u09A8\u09BE\u0964 REQUIRES_NEW \u09B9\u09B2\u09CB \u09AC\u09CD\u09AF\u09BE\u0999\u09CD\u0995\u09C7\u09B0 \u0986\u09B2\u09BE\u09A6\u09BE \u0996\u09BE\u09A4\u09BE\u09B0 \u09AE\u09A4\u09CB, \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 \u098F\u09A8\u09CD\u099F\u09CD\u09B0\u09BF \u09B8\u09AC\u09B8\u09AE\u09AF\u09BC \u09B2\u09C7\u0996\u09BE \u09B9\u09AF\u09BC, \u09AA\u09C7\u09AE\u09C7\u09A8\u09CD\u099F \u09AB\u09C7\u09B2 \u09B9\u09B2\u09C7\u0993\u0964"},question:"How does @Transactional work? Explain propagation and rollback rules.",answer:"`@Transactional` wraps a method in a database transaction through a Spring AOP proxy: the proxy begins (or joins) a transaction before the call and commits or rolls back after it. Propagation decides what happens when a transaction already exists: `REQUIRED` (default) joins it or creates a new one, `REQUIRES_NEW` suspends the current one and runs an independent transaction (e.g. an audit log that must survive a rollback), `NESTED` uses a savepoint, and `SUPPORTS`, `MANDATORY`, `NOT_SUPPORTED`, `NEVER` cover the other cases. By default it rolls back only on unchecked exceptions (`RuntimeException`) and `Error`, not on checked exceptions \u2014 change that with `rollbackFor` / `noRollbackFor`. `readOnly = true` is an optimisation hint for queries (Hibernate can skip dirty checking).",points:["Proxy-based: works only on calls that go through the Spring proxy","REQUIRED (default) vs REQUIRES_NEW vs NESTED (savepoint)","Default rollback: RuntimeException and Error; checked exceptions commit","rollbackFor = Exception.class to roll back on checked exceptions","isolation and timeout attributes are also available","Put it on service methods, keep transactions short; no remote calls inside if possible"],code:`@Service
public class TransferService {
    private final AccountService accounts;
    private final AuditService audit;

    public TransferService(AccountService accounts, AuditService audit) {
        this.accounts = accounts;
        this.audit = audit;
    }

    @Transactional(rollbackFor = InsufficientBalanceException.class)
    public void transfer(Long from, Long to, BigDecimal amount) throws InsufficientBalanceException {
        audit.log(from, to, amount);        // REQUIRES_NEW: commits on its own
        accounts.debit(from, amount);       // joins this transaction (REQUIRED)
        accounts.credit(to, amount);        // any failure rolls back debit + credit, not the audit row
    }
}

@Service
class AuditService {
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void log(Long from, Long to, BigDecimal amount) { /* insert audit row */ }
}`},{id:"sp-18",level:"senior",topic:"spring",difficulty:"hard",simple:{hi:"Cricket ka third umpire (proxy) sirf TV camera se dekhta hai. Agar fielder ne gend chhupa li (exception catch), ya khel camera ke peeche hua (self-invocation), toh umpire ko pata hi nahi chalta aur decision 'not out' (commit) ho jaata hai.",en:"Think of the cricket third umpire (proxy) who only sees through the TV camera. If the fielder hides the ball (exception caught) or the play happens behind the camera (self-invocation), the umpire never knows and the decision is 'not out' (commit).",bn:"\u0995\u09CD\u09B0\u09BF\u0995\u09C7\u099F\u09C7\u09B0 \u09A5\u09BE\u09B0\u09CD\u09A1 \u0986\u09AE\u09CD\u09AA\u09BE\u09AF\u09BC\u09BE\u09B0 (proxy) \u09B6\u09C1\u09A7\u09C1 \u099F\u09BF\u09AD\u09BF \u0995\u09CD\u09AF\u09BE\u09AE\u09C7\u09B0\u09BE \u09A6\u09BF\u09AF\u09BC\u09C7 \u09A6\u09C7\u0996\u09C7\u09A8\u0964 \u09AB\u09BF\u09B2\u09CD\u09A1\u09BE\u09B0 \u09AF\u09A6\u09BF \u09AC\u09B2 \u09B2\u09C1\u0995\u09BF\u09AF\u09BC\u09C7 \u09AB\u09C7\u09B2\u09C7 (exception catch), \u09AC\u09BE \u0996\u09C7\u09B2\u09BE \u0995\u09CD\u09AF\u09BE\u09AE\u09C7\u09B0\u09BE\u09B0 \u0986\u09A1\u09BC\u09BE\u09B2\u09C7 \u09B9\u09AF\u09BC (self-invocation), \u0986\u09AE\u09CD\u09AA\u09BE\u09AF\u09BC\u09BE\u09B0 \u0995\u09BF\u099B\u09C1\u0987 \u099C\u09BE\u09A8\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u09A8\u09BE \u0986\u09B0 \u09B8\u09BF\u09A6\u09CD\u09A7\u09BE\u09A8\u09CD\u09A4 \u09B9\u09AF\u09BC '\u09A8\u099F \u0986\u0989\u099F' (commit)\u0964"},question:"Scenario: A method is annotated with @Transactional and an exception is thrown, but the data is still saved in the database. What could be wrong?",answer:"Check the usual causes: (1) the exception is checked \u2014 by default only `RuntimeException` and `Error` trigger rollback, so add `rollbackFor`; (2) the exception is caught and swallowed inside the method, so the proxy sees a normal return and commits \u2014 rethrow it or mark the transaction rollback-only; (3) self-invocation \u2014 the @Transactional method is called through `this` from another method of the same class, which bypasses the proxy, so no transaction is started at all; (4) the method is private/final, or the object is not a Spring bean (created with `new`), so it is never proxied; (5) the write happened in a `REQUIRES_NEW` transaction, through a different transaction manager/datasource, or on a table that doesn't support transactions (e.g. MySQL MyISAM). The cleanest fix for self-invocation is to move the transactional method into another bean.",points:["Default: no rollback for checked exceptions","Swallowed exceptions \u2192 commit","Self-invocation bypasses the proxy \u2192 no transaction","Private/final methods and non-Spring objects aren't proxied","If an inner REQUIRED method fails and the outer one catches it, commit throws UnexpectedRollbackException","Verify with logging.level.org.springframework.transaction=debug"],code:`@Service
public class OrderService {
    private final OrderRepository repo;
    public OrderService(OrderRepository repo) { this.repo = repo; }

    public void placeAll(List<Order> orders) throws StockException {
        for (Order o : orders) {
            place(o);          // BUG 1: self-invocation -> proxy bypassed, no transaction
        }
    }

    @Transactional
    public void place(Order order) throws StockException {
        repo.save(order);
        try {
            notifyWarehouse(order);
        } catch (RuntimeException e) {
            // BUG 2: swallowed -> proxy sees success and commits
        }
        reserveStock(order);   // BUG 3: StockException is checked -> no rollback by default
    }
    // helpers omitted
}
// Fix: call place() from another bean, use @Transactional(rollbackFor = Exception.class),
// and rethrow instead of swallowing.`},{id:"sp-19",level:"mid",topic:"spring",difficulty:"hard",simple:{hi:"JWT hologram stamp wale cinema ticket jaisa hai. Gate wala har baar register mein tumhara naam nahi dhoondhta \u2014 bas stamp aur show ka time check karke andar jaane deta hai. Spring Security wahi gatekeeper hai.",en:"A JWT is like a cinema ticket with a hologram stamp. The gatekeeper doesn't search a register for your name every time \u2014 he just checks the stamp and show time and lets you in. Spring Security is that gatekeeper.",bn:"JWT \u09B9\u09B2\u09CB \u09B9\u09B2\u09CB\u0997\u09CD\u09B0\u09BE\u09AE \u09B8\u09CD\u099F\u09CD\u09AF\u09BE\u09AE\u09CD\u09AA \u09B2\u09BE\u0997\u09BE\u09A8\u09CB \u09B8\u09BF\u09A8\u09C7\u09AE\u09BE\u09B0 \u099F\u09BF\u0995\u09BF\u099F\u09C7\u09B0 \u09AE\u09A4\u09CB\u0964 \u0997\u09C7\u099F\u09C7\u09B0 \u09B2\u09CB\u0995 \u09AA\u09CD\u09B0\u09A4\u09BF\u09AC\u09BE\u09B0 \u0996\u09BE\u09A4\u09BE\u09AF\u09BC \u09A4\u09CB\u09AE\u09BE\u09B0 \u09A8\u09BE\u09AE \u0996\u09CB\u0981\u099C\u09C7\u09A8 \u09A8\u09BE \u2014 \u09B6\u09C1\u09A7\u09C1 \u09B8\u09CD\u099F\u09CD\u09AF\u09BE\u09AE\u09CD\u09AA \u0986\u09B0 \u09B6\u09CB-\u098F\u09B0 \u09B8\u09AE\u09AF\u09BC \u09A6\u09C7\u0996\u09C7 \u09A2\u09C1\u0995\u09A4\u09C7 \u09A6\u09C7\u09A8\u0964 Spring Security \u09B9\u09B2\u09CB \u09B8\u09C7\u0987 \u0997\u09C7\u099F\u0995\u09BF\u09AA\u09BE\u09B0\u0964"},question:"How does Spring Security work, and how do you secure a REST API with JWT?",answer:"Spring Security is a chain of servlet filters (`SecurityFilterChain`) that runs before your controllers: it authenticates the request (who are you), stores the result in the `SecurityContext`, and authorizes it (are you allowed) through URL rules or method security such as `@PreAuthorize`. In Spring Boot 3 / Spring Security 6 you configure it with a `SecurityFilterChain` bean and the lambda DSL \u2014 `WebSecurityConfigurerAdapter` has been removed. With JWT, the client logs in once and gets a signed token, then sends `Authorization: Bearer <token>` on every request; the server verifies the signature and expiry without any session (stateless) and builds the authentication from the claims. The simplest setup is `spring-boot-starter-oauth2-resource-server` with `.oauth2ResourceServer(o -> o.jwt(...))` instead of a hand-written filter.",points:["Authentication (401 if it fails) vs authorization (403 if it fails)","SecurityFilterChain bean + lambda DSL; requestMatchers + authorizeHttpRequests","Stateless API: SessionCreationPolicy.STATELESS; CSRF can be disabled when no cookies are used","Store passwords with BCrypt (PasswordEncoder), never plain text","JWT is signed, not encrypted \u2014 don't put secrets in it; keep expiry short and use refresh tokens","Resource server maps the scope claim to SCOPE_ authorities; use a JwtAuthenticationConverter for roles"],code:`@Configuration
@EnableWebSecurity
@EnableMethodSecurity
public class SecurityConfig {

    @Bean
    SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .csrf(csrf -> csrf.disable())
            .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/auth/**", "/actuator/health").permitAll()
                .requestMatchers("/api/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated())
            .oauth2ResourceServer(o -> o.jwt(Customizer.withDefaults()));
        return http.build();
    }

    @Bean
    PasswordEncoder passwordEncoder() { return new BCryptPasswordEncoder(); }
}
// application.yml: spring.security.oauth2.resourceserver.jwt.issuer-uri (or a JwtDecoder bean)`},{id:"sp-20",level:"junior",topic:"spring",difficulty:"easy",simple:{hi:"Actuator car ke dashboard jaisa hai \u2014 speed, petrol, engine temperature sab dikhata hai. Driver ko bonnet khole bina pata chal jaata hai ki gaadi theek hai ya nahi.",en:"Actuator is like a car dashboard \u2014 it shows speed, fuel and engine temperature. The driver knows whether the car is fine without opening the bonnet.",bn:"Actuator \u09B9\u09B2\u09CB \u0997\u09BE\u09A1\u09BC\u09BF\u09B0 \u09A1\u09CD\u09AF\u09BE\u09B6\u09AC\u09CB\u09B0\u09CD\u09A1\u09C7\u09B0 \u09AE\u09A4\u09CB \u2014 \u09B8\u09CD\u09AA\u09BF\u09A1, \u09A4\u09C7\u09B2, \u0987\u099E\u09CD\u099C\u09BF\u09A8\u09C7\u09B0 \u09A4\u09BE\u09AA\u09AE\u09BE\u09A4\u09CD\u09B0\u09BE \u09B8\u09AC \u09A6\u09C7\u0996\u09BE\u09AF\u09BC\u0964 \u09AC\u09A8\u09C7\u099F \u09A8\u09BE \u0996\u09C1\u09B2\u09C7\u0987 \u09A1\u09CD\u09B0\u09BE\u0987\u09AD\u09BE\u09B0 \u09AC\u09C1\u099D\u09C7 \u09AF\u09BE\u09A8 \u0997\u09BE\u09A1\u09BC\u09BF \u09A0\u09BF\u0995 \u0986\u099B\u09C7 \u0995\u09BF\u09A8\u09BE\u0964"},question:"What is Spring Boot Actuator and which endpoints are commonly used?",answer:"Spring Boot Actuator adds production-ready endpoints under `/actuator`: `health` (database, disk, and liveness/readiness groups for Kubernetes), `info`, `metrics` (Micrometer), `prometheus` (with `micrometer-registry-prometheus`), `loggers` (change log levels at runtime), `env`, `beans`, `mappings`, `threaddump` and `heapdump`. Over HTTP only `health` is exposed by default; expose others with `management.endpoints.web.exposure.include` and protect them with Spring Security, often on a separate management port. You can add custom checks by implementing `HealthIndicator`.",points:["Add spring-boot-starter-actuator","Only /actuator/health is exposed over HTTP by default","Liveness/readiness probes: /actuator/health/liveness and /readiness","Metrics via Micrometer \u2192 Prometheus/Grafana","env, heapdump, beans can leak secrets \u2014 secure or don't expose them","Custom HealthIndicator for external dependencies"],code:`# application.yml
management:
  server:
    port: 8081
  endpoints:
    web:
      exposure:
        include: health,info,metrics,prometheus
  endpoint:
    health:
      show-details: when-authorized

// Java
@Component
public class PaymentApiHealthIndicator implements HealthIndicator {
    @Override
    public Health health() {
        return pingPaymentApi() ? Health.up().build()
                : Health.down().withDetail("reason", "payment API timeout").build();
    }
    private boolean pingPaymentApi() { return true; /* call the API */ }
}`},{id:"sp-21",level:"junior",topic:"spring",difficulty:"medium",simple:{hi:"Testing cricket practice jaisa hai: nets mein sirf batting practice (unit test / slice), aur poori team ke saath practice match (@SpringBootTest). Mockito bowling machine jaisa hai \u2014 asli bowler ki jagah nakli gend daalta hai.",en:"Testing is like cricket practice: batting in the nets only (unit test / slice), and a full practice match where the whole team plays (@SpringBootTest). Mockito is like a bowling machine \u2014 it throws fake balls in place of a real bowler.",bn:"Testing \u09B9\u09B2\u09CB \u0995\u09CD\u09B0\u09BF\u0995\u09C7\u099F \u09AA\u09CD\u09B0\u09CD\u09AF\u09BE\u0995\u099F\u09BF\u09B8\u09C7\u09B0 \u09AE\u09A4\u09CB: \u09A8\u09C7\u099F\u09C7 \u09B6\u09C1\u09A7\u09C1 \u09AC\u09CD\u09AF\u09BE\u099F\u09BF\u0982 \u09AA\u09CD\u09B0\u09CD\u09AF\u09BE\u0995\u099F\u09BF\u09B8 (unit test / slice), \u0986\u09B0 \u09AA\u09C1\u09B0\u09CB \u09A6\u09B2 \u09A8\u09BF\u09AF\u09BC\u09C7 \u09AA\u09CD\u09B0\u09CD\u09AF\u09BE\u0995\u099F\u09BF\u09B8 \u09AE\u09CD\u09AF\u09BE\u099A (@SpringBootTest)\u0964 Mockito \u09B9\u09B2\u09CB \u09AC\u09CB\u09B2\u09BF\u0982 \u09AE\u09C7\u09B6\u09BF\u09A8\u09C7\u09B0 \u09AE\u09A4\u09CB \u2014 \u0986\u09B8\u09B2 \u09AC\u09CB\u09B2\u09BE\u09B0\u09C7\u09B0 \u09AC\u09A6\u09B2\u09C7 \u09A8\u0995\u09B2 \u09AC\u09B2 \u099B\u09CB\u09A1\u09BC\u09C7\u0964"},question:"How do you test a Spring Boot application? Compare @SpringBootTest, @WebMvcTest, @DataJpaTest and Mockito unit tests.",answer:"`@SpringBootTest` starts the full application context (optionally a real server with `webEnvironment = RANDOM_PORT`) \u2014 good for integration tests but slower. Test slices load only one layer: `@WebMvcTest` loads controllers, advice, filters and `MockMvc` but not services or repositories (you mock those), and `@DataJpaTest` loads JPA repositories with an embedded database and rolls back after each test. Pure business logic is best tested with plain Mockito unit tests (`@ExtendWith(MockitoExtension.class)`, `@Mock`, `@InjectMocks`) without Spring at all. Use `@MockitoBean` (the newer replacement for the deprecated `@MockBean`) to replace a bean inside a Spring test context, and Testcontainers when you need a real database.",points:["Unit tests (Mockito) \u2014 fastest, most numerous","@WebMvcTest \u2014 controller layer: request mapping, validation, JSON, status codes","@DataJpaTest \u2014 repository queries, transactional rollback per test","@SpringBootTest \u2014 full wiring/integration, slowest","@MockitoBean replaces a bean in the context; @Mock is plain Mockito","Testcontainers for real PostgreSQL/MySQL instead of H2 differences"],code:`@WebMvcTest(UserController.class)
class UserControllerTest {

    @Autowired MockMvc mvc;
    @MockitoBean UserService userService;   // older versions: @MockBean

    @Test
    void returnsUser() throws Exception {
        when(userService.findById(1L)).thenReturn(Optional.of(new UserDto(1L, "Asha")));

        mvc.perform(get("/api/users/1"))
           .andExpect(status().isOk())
           .andExpect(jsonPath("$.name").value("Asha"));
    }

    @Test
    void returns404WhenMissing() throws Exception {
        when(userService.findById(9L)).thenReturn(Optional.empty());
        mvc.perform(get("/api/users/9")).andExpect(status().isNotFound());
    }
}`},{id:"sp-22",level:"senior",topic:"spring",difficulty:"hard",simple:{hi:"AOP school ke security guard jaisa hai \u2014 har class mein teacher khud checking nahi karti; guard gate pe hi sab ke liye ek saath kar deta hai. Teacher sirf padhane pe dhyaan deti hai.",en:"AOP is like the school security guard \u2014 the teacher doesn't check everyone in each class herself; the guard does it for everyone at the gate. The teacher just focuses on teaching.",bn:"AOP \u09B9\u09B2\u09CB \u09B8\u09CD\u0995\u09C1\u09B2\u09C7\u09B0 \u09B8\u09BF\u0995\u09BF\u0989\u09B0\u09BF\u099F\u09BF \u0997\u09BE\u09B0\u09CD\u09A1\u09C7\u09B0 \u09AE\u09A4\u09CB \u2014 \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BE \u0995\u09CD\u09B2\u09BE\u09B8\u09C7 \u099F\u09BF\u099A\u09BE\u09B0 \u09A8\u09BF\u099C\u09C7 \u099A\u09C7\u0995\u09BF\u0982 \u0995\u09B0\u09C7\u09A8 \u09A8\u09BE; \u0997\u09BE\u09B0\u09CD\u09A1 \u0997\u09C7\u099F\u09C7\u0987 \u09B8\u09AC\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u098F\u0995\u09B8\u0999\u09CD\u0997\u09C7 \u0995\u09B0\u09C7 \u09A6\u09C7\u09A8\u0964 \u099F\u09BF\u099A\u09BE\u09B0 \u09B6\u09C1\u09A7\u09C1 \u09AA\u09A1\u09BC\u09BE\u09A8\u09CB\u09AF\u09BC \u09AE\u09A8 \u09A6\u09C7\u09A8\u0964"},question:"What is Spring AOP and how does it work internally? What are its limitations?",answer:"AOP separates cross-cutting concerns (logging, security, transactions, metrics) from business code. The key terms are aspect (the module, `@Aspect`), advice (the code that runs \u2014 `@Before`, `@AfterReturning`, `@AfterThrowing`, `@After`, `@Around`), pointcut (an expression that selects where advice applies), join point (in Spring AOP always a method execution) and weaving. Spring AOP is proxy-based and woven at runtime: a JDK dynamic proxy for interfaces or a CGLIB subclass (Spring Boot defaults to CGLIB), so it works only on Spring beans, only for calls that go through the proxy (not self-invocation) and not on private or final methods. `@Transactional`, `@Cacheable`, `@Async` and method security are built on it; for field or constructor join points you need full AspectJ weaving.",points:["Aspect, advice, pointcut, join point, weaving","@Around is the most powerful \u2014 must call proceed() and return its result","Proxy types: JDK dynamic proxy (interfaces) vs CGLIB (class-based, Boot default)","Limitations: self-invocation, private/final methods, only Spring-managed beans, method execution only","Order multiple aspects with @Order","Add spring-boot-starter-aop for @Aspect support"],code:`@Target(ElementType.METHOD)
@Retention(RetentionPolicy.RUNTIME)
public @interface Timed { }

@Aspect
@Component
public class TimingAspect {
    private static final Logger log = LoggerFactory.getLogger(TimingAspect.class);

    @Around("@annotation(com.example.Timed)")
    public Object time(ProceedingJoinPoint pjp) throws Throwable {
        long start = System.nanoTime();
        try {
            return pjp.proceed();
        } finally {
            log.info("{} took {} ms", pjp.getSignature().toShortString(),
                     (System.nanoTime() - start) / 1_000_000);
        }
    }
}`},{id:"sp-23",level:"senior",topic:"spring",difficulty:"hard",simple:{hi:"Microservices ek badi shaadi jaisi hain \u2014 catering, decoration, music sab alag team. Gateway reception desk hai, discovery phone directory, config sab ke liye ek common notice board, aur circuit breaker matlab caterer late ho toh pehle se rakhe snacks serve kar do, poora function mat roko.",en:"Microservices are like a big wedding \u2014 catering, decoration and music are separate teams. The gateway is the reception desk, discovery is the phone directory, config is a common notice board for everyone, and a circuit breaker means: if the caterer is late, serve the snacks kept ready instead of stopping the whole function.",bn:"Microservices \u09B9\u09B2\u09CB \u098F\u0995\u099F\u09BE \u09AC\u09A1\u09BC \u09AC\u09BF\u09AF\u09BC\u09C7\u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u09AE\u09A4\u09CB \u2014 \u0995\u09CD\u09AF\u09BE\u099F\u09BE\u09B0\u09BF\u0982, \u09A1\u09C7\u0995\u09CB\u09B0\u09C7\u09B6\u09A8, \u09AE\u09BF\u0989\u099C\u09BF\u0995 \u09B8\u09AC \u0986\u09B2\u09BE\u09A6\u09BE \u09A6\u09B2\u0964 Gateway \u09B9\u09B2\u09CB \u09B0\u09BF\u09B8\u09C7\u09AA\u09B6\u09A8 \u09A1\u09C7\u09B8\u09CD\u0995, discovery \u09B9\u09B2\u09CB \u09AB\u09CB\u09A8 \u09A1\u09BF\u09B0\u09C7\u0995\u09CD\u099F\u09B0\u09BF, config \u09B9\u09B2\u09CB \u09B8\u09AC\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u098F\u0995\u099F\u09BE \u0995\u09AE\u09A8 \u09A8\u09CB\u099F\u09BF\u09B8 \u09AC\u09CB\u09B0\u09CD\u09A1, \u0986\u09B0 circuit breaker \u09AE\u09BE\u09A8\u09C7 \u0995\u09CD\u09AF\u09BE\u099F\u09BE\u09B0\u09BE\u09B0 \u09A6\u09C7\u09B0\u09BF \u0995\u09B0\u09B2\u09C7 \u0986\u0997\u09C7 \u09A5\u09C7\u0995\u09C7 \u09B0\u09BE\u0996\u09BE \u09B8\u09CD\u09A8\u09CD\u09AF\u09BE\u0995\u09CD\u09B8 \u09AA\u09B0\u09BF\u09AC\u09C7\u09B6\u09A8 \u0995\u09B0\u09CB, \u09AA\u09C1\u09B0\u09CB \u0985\u09A8\u09C1\u09B7\u09CD\u09A0\u09BE\u09A8 \u09A5\u09BE\u09AE\u09BF\u09AF\u09BC\u09CB \u09A8\u09BE\u0964"},question:"How do you build microservices with Spring Cloud? Explain config, service discovery, API gateway and resilience.",answer:"Spring Cloud adds building blocks for distributed systems on top of Spring Boot. Spring Cloud Config serves central, versioned configuration (usually from Git), refreshed via `/actuator/refresh` or Spring Cloud Bus; service discovery with Eureka (or Consul/Kubernetes) lets services find each other by name; Spring Cloud LoadBalancer does client-side load balancing and OpenFeign gives declarative HTTP clients; Spring Cloud Gateway is the API gateway for routing, authentication, rate limiting and other cross-cutting filters; Resilience4j (directly or via Spring Cloud CircuitBreaker) provides circuit breakers, retries, timeouts, rate limiters and bulkheads. Old Netflix components (Hystrix, Zuul, Ribbon) are gone, and Sleuth was replaced by Micrometer Tracing for distributed tracing. On Kubernetes, discovery and config are often handled by the platform (Services, ConfigMaps) instead.",points:["Config Server: externalised config per service/profile, secrets in a vault","Discovery: services register and look each other up by logical name","Gateway: single entry point \u2014 routing, auth, rate limiting, CORS","Circuit breaker: fail fast + fallback when a downstream service is unhealthy","Always set timeouts; combine retry with backoff and idempotent operations","Observability: Micrometer Tracing + metrics + centralised logs"],code:`@FeignClient(name = "inventory-service")      // resolved via discovery + LoadBalancer
public interface InventoryClient {
    @GetMapping("/api/stock/{sku}")
    int stock(@PathVariable("sku") String sku);
}

@Service
public class ProductService {
    private final InventoryClient inventory;
    public ProductService(InventoryClient inventory) { this.inventory = inventory; }

    @CircuitBreaker(name = "inventory", fallbackMethod = "stockFallback") // Resilience4j
    @Retry(name = "inventory")
    public int availableStock(String sku) {
        return inventory.stock(sku);
    }

    public int stockFallback(String sku, Throwable ex) {
        return 0;   // degrade gracefully instead of failing the whole page
    }
}
// main class: @EnableFeignClients`},{id:"sp-24",level:"mid",topic:"spring",difficulty:"medium",simple:{hi:"Library se kitaab ghar le aaye, par unhone kaha tha ek chapter 'baad mein milega'. Ab library band ho gayi (session closed) aur tum wo chapter maangte ho \u2014 nahi milega! Isliye library band hone se pehle hi poori kitaab le aao (JOIN FETCH / DTO).",en:"You brought a book home from the library, but they said one chapter would come 'later'. Now the library is closed (session closed) and you ask for that chapter \u2014 you won't get it! So take the whole book before the library closes (JOIN FETCH / DTO).",bn:"\u09B2\u09BE\u0987\u09AC\u09CD\u09B0\u09C7\u09B0\u09BF \u09A5\u09C7\u0995\u09C7 \u09AC\u0987 \u09AC\u09BE\u09A1\u09BC\u09BF \u0986\u09A8\u09B2\u09C7, \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0993\u09B0\u09BE \u09AC\u09B2\u09C7\u099B\u09BF\u09B2 \u098F\u0995\u099F\u09BE \u0985\u09A7\u09CD\u09AF\u09BE\u09AF\u09BC '\u09AA\u09B0\u09C7 \u09A6\u09C7\u09AC\u09C7'\u0964 \u098F\u0996\u09A8 \u09B2\u09BE\u0987\u09AC\u09CD\u09B0\u09C7\u09B0\u09BF \u09AC\u09A8\u09CD\u09A7 (session closed) \u0986\u09B0 \u09A4\u09C1\u09AE\u09BF \u09B8\u09C7\u0987 \u0985\u09A7\u09CD\u09AF\u09BE\u09AF\u09BC \u099A\u09BE\u0987\u099B \u2014 \u09AA\u09BE\u09AC\u09C7 \u09A8\u09BE! \u09A4\u09BE\u0987 \u09B2\u09BE\u0987\u09AC\u09CD\u09B0\u09C7\u09B0\u09BF \u09AC\u09A8\u09CD\u09A7 \u09B9\u0993\u09AF\u09BC\u09BE\u09B0 \u0986\u0997\u09C7\u0987 \u09AA\u09C1\u09B0\u09CB \u09AC\u0987 \u09A8\u09BF\u09AF\u09BC\u09C7 \u098F\u09B8\u09CB (JOIN FETCH / DTO)\u0964"},question:"Scenario: Your API throws LazyInitializationException: could not initialize proxy - no Session. Why does it happen and how do you fix it?",answer:"A LAZY association is a proxy that can be loaded only while the Hibernate session (persistence context) is open. The service method's transaction has ended, the entity is now detached, and later code touches the lazy association \u2014 typically Jackson serialising the entity in the controller when `spring.jpa.open-in-view` is disabled, or code running outside a web request (`@Async`, schedulers, message listeners). Fix it by loading what the use case needs inside the transaction: a `JOIN FETCH` query or `@EntityGraph`, or map to a DTO inside a `@Transactional(readOnly = true)` service method and return DTOs instead of entities. Avoid band-aids such as switching to EAGER, `hibernate.enable_lazy_load_no_trans`, or relying on Open Session In View (enabled by default in Boot, with a startup warning) \u2014 they hide N+1 queries and hold DB connections longer.",points:["Cause: lazy proxy accessed after the session/transaction closed","Common trigger: returning entities from controllers with open-in-view=false","Fix: JOIN FETCH / @EntityGraph for that query","Fix: map to DTOs inside a read-only transaction","Don't fix with EAGER or enable_lazy_load_no_trans","Hibernate.initialize(entity.getItems()) inside the transaction also works for one-offs"],code:`// Problem (open-in-view=false): items is LAZY, Jackson touches it after the session closed
@GetMapping("/{id}")
public Order get(@PathVariable Long id) {
    return orderRepository.findById(id).orElseThrow();
}

// Fix: fetch what you need and return a DTO
public interface OrderRepository extends JpaRepository<Order, Long> {
    @Query("select o from Order o join fetch o.items where o.id = :id")
    Optional<Order> findWithItems(@Param("id") Long id);
}

@Service
public class OrderQueryService {
    private final OrderRepository repo;
    public OrderQueryService(OrderRepository repo) { this.repo = repo; }

    @Transactional(readOnly = true)
    public OrderDto get(Long id) {
        Order order = repo.findWithItems(id).orElseThrow();
        return OrderDto.from(order);       // map while the session is still open
    }
}`},{id:"sp-25",level:"senior",topic:"spring",difficulty:"hard",simple:{hi:"Socho ek dabbawala 100 gharon ke dabbe 100 alag chakkar laga ke laata hai \u2014 bahut der lagegi. Pehle gino kitne chakkar lag rahe hain (SQL logs), phir saare dabbe ek hi train mein ek saath le aao (JOIN FETCH / batch / DTO).",en:"Imagine a dabbawala bringing tiffins from 100 homes in 100 separate trips \u2014 it takes forever. First count the trips (SQL logs), then bring all the tiffins together in one train (JOIN FETCH / batch / DTO).",bn:"\u09AD\u09BE\u09AC\u09CB \u098F\u0995\u099C\u09A8 \u09A1\u09BE\u09AC\u09CD\u09AC\u09BE\u0993\u09AF\u09BC\u09BE\u09B2\u09BE 100\u099F\u09BE \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u099F\u09BF\u09AB\u09BF\u09A8 100 \u09AC\u09BE\u09B0 \u0986\u09B2\u09BE\u09A6\u09BE \u0986\u09B2\u09BE\u09A6\u09BE \u09AF\u09BE\u09A4\u09BE\u09AF\u09BC\u09BE\u09A4 \u0995\u09B0\u09C7 \u0986\u09A8\u099B\u09C7\u09A8 \u2014 \u0996\u09C1\u09AC \u09A6\u09C7\u09B0\u09BF \u09B9\u09AC\u09C7\u0964 \u0986\u0997\u09C7 \u0997\u09CB\u09A8\u09CB \u0995\u09A4\u09AC\u09BE\u09B0 \u09AF\u09BE\u09A4\u09BE\u09AF\u09BC\u09BE\u09A4 \u09B9\u099A\u09CD\u099B\u09C7 (SQL logs), \u09A4\u09BE\u09B0\u09AA\u09B0 \u09B8\u09AC \u099F\u09BF\u09AB\u09BF\u09A8 \u098F\u0995\u09B8\u0999\u09CD\u0997\u09C7 \u098F\u0995\u099F\u09BE \u099F\u09CD\u09B0\u09C7\u09A8\u09C7 \u09A8\u09BF\u09AF\u09BC\u09C7 \u098F\u09B8\u09CB (JOIN FETCH / batch / DTO)\u0964"},question:"Scenario: The /orders API takes 4 seconds in production for 100 orders, and the logs show hundreds of SQL queries per request. How do you diagnose and fix it?",answer:"This is the classic N+1 problem: one query loads the orders, then each order's lazy `customer` or `items` is loaded separately while mapping or serialising. Diagnose by enabling SQL logging (`logging.level.org.hibernate.SQL=debug`) or Hibernate statistics, or by looking at traces in an APM tool, and count queries per request \u2014 then lock it in with a test that asserts the query count. Fix it with an explicit fetch plan per use case: `JOIN FETCH` / `@EntityGraph` for to-one associations, batch fetching (`hibernate.default_batch_fetch_size`) or a second query for collections, or a DTO projection that selects only the needed columns. Be careful: join-fetching a collection together with pagination makes Hibernate paginate in memory (HHH90003004 warning) \u2014 page the IDs first, then fetch details; also check indexes and keep `open-in-view` off so lazy loads can't silently happen in the web layer.",points:["Measure first: SQL log, Hibernate statistics, APM traces","Root cause: lazy associations accessed in a loop","To-one: JOIN FETCH / @EntityGraph; collections: batch fetch or separate query","DTO projections for read-only list endpoints","Collection fetch + pagination = in-memory paging \u2014 avoid","Add a regression test on query count; check indexes and EXPLAIN plans"],code:`# 1. Diagnose (application.properties)
logging.level.org.hibernate.SQL=debug
spring.jpa.properties.hibernate.generate_statistics=true

// 2. Fix: DTO projection - one query, only needed columns
public record OrderSummary(Long id, String customerName, BigDecimal total) { }

public interface OrderRepository extends JpaRepository<Order, Long> {
    @Query(value = """
            select new com.example.order.OrderSummary(o.id, c.name, o.total)
            from Order o join o.customer c
            where o.createdAt >= :from
            """,
           countQuery = "select count(o) from Order o where o.createdAt >= :from")
    Page<OrderSummary> findSummaries(@Param("from") LocalDateTime from, Pageable pageable);
}

# 3. Or batch-load lazy collections: 1 + ceil(N/50) queries instead of 1 + N
spring.jpa.properties.hibernate.default_batch_fetch_size=50`}],t=[{id:"qv-c1",level:"fresher",topic:"java-core",question:'What does `new String("a") == "a"` evaluate to?',options:["true","false","Compile error","It throws an exception"],correct:1,explanation:"new String() creates a separate heap object, so == compares two different references."},{id:"qv-c2",level:"junior",topic:"java-core",question:"Given `Integer a = 200, b = 200;` what does `a == b` print?",options:["true","Compile error","NullPointerException","false"],correct:3,explanation:"Only values -128 to 127 are cached by default, so 200 is boxed into two different objects."},{id:"qv-c3",level:"junior",topic:"java-core",question:"Which of these is a checked exception?",options:["IOException","NullPointerException","IllegalArgumentException","ArithmeticException"],correct:0,explanation:"IOException extends Exception but not RuntimeException, so the compiler forces it to be handled or declared."},{id:"qv-c4",level:"mid",topic:"java-core",question:"What happens if a class overrides equals() but not hashCode() and its objects are used in a HashSet?",options:["Compile error","Logically equal objects can be stored as duplicates","HashSet automatically uses equals() only","A ClassCastException is thrown"],correct:1,explanation:"Equal objects get different identity hash codes, land in different buckets and are never compared with equals()."},{id:"qv-c5",level:"mid",topic:"java-core",question:"Which statement about Java records is FALSE?",options:["Records are implicitly final","Records get equals(), hashCode() and toString() automatically","Records can extend another class","Records can implement interfaces"],correct:2,explanation:"Records implicitly extend java.lang.Record, so they cannot extend any other class."},{id:"qv-c6",level:"fresher",topic:"java-core",question:"Where can the `var` keyword NOT be used?",options:["A local variable with an initializer","An enhanced for-loop variable","A try-with-resources variable","A class field"],correct:3,explanation:"var works only for local variables (and lambda parameters); fields, parameters and return types need explicit types."},{id:"qv-l1",level:"junior",topic:"java-collections",question:"Which of these Map implementations allows a null key?",options:["Hashtable","ConcurrentHashMap","HashMap","TreeMap with natural ordering"],correct:2,explanation:"HashMap allows one null key; Hashtable and ConcurrentHashMap forbid nulls, and TreeMap with natural ordering throws NullPointerException."},{id:"qv-l2",level:"mid",topic:"java-collections",question:"What does this print? Stream.of(1, 2, 3).map(x -> { System.out.println(x); return x * 2; });",options:["1 2 3","2 4 6","It does not compile","Nothing"],correct:3,explanation:"map is a lazy intermediate operation, and without a terminal operation the pipeline never runs."},{id:"qv-l3",level:"junior",topic:"java-collections",question:"How does HashSet store its elements internally?",options:["As keys of an internal HashMap with a dummy value","In a sorted red-black tree","In a plain array searched with equals()","In a doubly linked list"],correct:0,explanation:"HashSet wraps a HashMap and stores each element as a key mapped to a constant PRESENT object."},{id:"qv-t1",level:"fresher",topic:"java-concurrency",question:"What happens if you call t.run() instead of t.start() on a Thread?",options:["A new thread is created and run() executes on it","run() executes on the current thread; no new thread is started","IllegalThreadStateException is thrown","The thread starts but in the WAITING state"],correct:1,explanation:"run() is an ordinary method call; only start() asks the JVM to create a new thread."},{id:"qv-t2",level:"junior",topic:"java-concurrency",question:"What does declaring a field volatile guarantee?",options:["Atomicity of compound operations like count++","Mutual exclusion between threads","That the field is stored on the stack","Visibility of writes to other threads and no reordering across it"],correct:3,explanation:"volatile gives visibility and ordering (happens-before) but not atomicity or mutual exclusion."},{id:"qv-t3",level:"mid",topic:"java-concurrency",question:"In Java 21, which call creates an executor that starts a new virtual thread for every submitted task?",options:["Executors.newCachedThreadPool()","Executors.newWorkStealingPool()","Executors.newVirtualThreadPerTaskExecutor()","Executors.newFixedThreadPool(Integer.MAX_VALUE)"],correct:2,explanation:"newVirtualThreadPerTaskExecutor() creates one new virtual thread per task; the others use platform threads."},{id:"qv-s1",level:"fresher",topic:"spring",question:"Which annotation combines @SpringBootConfiguration, @EnableAutoConfiguration and @ComponentScan?",options:["@EnableWebMvc","@SpringBootApplication","@SpringBootConfiguration","@Configuration"],correct:1,explanation:"@SpringBootApplication is a meta-annotation that bundles configuration, auto-configuration and component scanning."},{id:"qv-s2",level:"junior",topic:"spring",question:"What is the default scope of a Spring bean?",options:["prototype","request","session","singleton"],correct:3,explanation:"Unless told otherwise, Spring creates one shared (singleton) instance per application context."},{id:"qv-s3",level:"mid",topic:"spring",question:"By default, which exceptions cause a @Transactional method to roll back?",options:["RuntimeException and Error","Any Exception, including checked ones","Only SQLException","None, unless rollbackFor is set"],correct:0,explanation:"Default rollback rules cover unchecked exceptions and errors; checked exceptions commit unless rollbackFor is used."},{id:"qv-s4",level:"mid",topic:"spring",question:"Listing 100 orders triggers 101 SQL queries because each order's customer is loaded lazily. What is the best fix?",options:["Change the association to FetchType.EAGER","Enable spring.jpa.open-in-view","Use JOIN FETCH or @EntityGraph in the query","Call Hibernate.initialize() for each order in a loop"],correct:2,explanation:"A fetch join or entity graph loads orders and customers in a single query, removing the N+1 problem."},{id:"qv-s5",level:"junior",topic:"spring",question:"Which test annotation loads only the web layer (controllers, MockMvc) and not services or repositories?",options:["@SpringBootTest","@WebMvcTest","@DataJpaTest","@JsonTest"],correct:1,explanation:"@WebMvcTest is a test slice for Spring MVC; dependencies such as services must be mocked."}];var r=e("java",[a],[t]);export{r as default};
